VRT_L("1re-c-chimie-r01",{"duree":20,"titre":"Les alcanes : structure et nomenclature","accroche":"Le gaz de cuisine est un alcane.","intro":"Les alcanes sont des hydrocarbures saturés : seulement des liaisons simples.","objectifs":["écrire la formule générale","décrire la géométrie","nommer un alcane ramifié"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Un <strong>alcane</strong> est un hydrocarbure saturé de formule <strong>CₙH₂ₙ₊₂</strong>. Chaque carbone est tétraédrique, avec des angles d'environ 109°.</div>"},{"t":"Nomenclature","html":"<ol><li>Trouver la chaîne carbonée la plus longue.</li><li>Numéroter pour donner les plus petits indices aux ramifications.</li><li>Nommer les groupes alkyles par ordre alphabétique.</li></ol><p>CH₃−CH(CH₃)−CH₂−CH₃ : 2-méthylbutane.</p>","labo":{"type":"trier","invite":"Choisis un alcane.","items":[["Méthane","CH₄, biogaz."],["Propane","C₃H₈."],["Butane","C₄H₁₀, gaz domestique."]]}},{"t":"Isomérie","html":"<p>Le butane et le 2-méthylpropane ont la même formule brute C₄H₁₀ : ce sont des isomères de chaîne.</p>","retenir":"Chaîne la plus longue, indices les plus petits."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Vérification des savoirs.</strong> La formule générale des alcanes est :</p><ol type='a'><li>CₙH₂ₙ</li><li>CₙH₂ₙ₋₂</li><li>CₙH₂ₙ₊₂</li><li>CₙHₙ</li></ol><details><summary>Voir la réponse</summary><p><strong>CₙH₂ₙ₊₂</strong>. Chaque carbone est lié à quatre atomes par des liaisons simples.</p></details><p><strong>Application directe des savoirs.</strong></p><p>Formule brute de l'alcane à 5 carbones ?</p><details><summary>Voir la réponse</summary><p>(Réponse : C₅H₁₂.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Un hydrocarbure A, alcane, a une masse molaire de 72 g/mol. M(C) = 12 g/mol ; M(H) = 1 g/mol.</p><p><strong>Consigne 1.</strong> Détermine sa formule brute.</p><p><strong>Consigne 2.</strong> Écris et nomme les formules semi-développées de ses isomères.</p><details><summary>Voir une réponse attendue</summary><p>14n + 2 = 72, n = 5 : C₅H₁₂. Isomères : pentane CH₃−(CH₂)₃−CH₃ ; 2-méthylbutane CH₃−CH(CH₃)−CH₂−CH₃ ; 2,2-diméthylpropane C(CH₃)₄.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans la démarche expérimentale."}],"revision":["CₙH₂ₙ₊₂.","Tétraèdre.","Nomenclature."],"exo":"<p>Formule brute de l'alcane à 5 carbones ? <em>(Réponse : C₅H₁₂.)</em></p>","quiz":[{"q":"La formule générale des alcanes est :","r":["CₙH₂ₙ","CₙH₂ₙ₋₂","CₙH₂ₙ₊₂","CₙHₙ"],"b":2,"e":"Chaque carbone est lié à quatre atomes par des liaisons simples."},{"q":"Dans un alcane, les liaisons carbone-carbone sont :","r":["doubles","triples","ioniques","simples"],"b":3,"e":"Les alcanes sont des hydrocarbures saturés."},{"q":"L'alcane à 3 atomes de carbone est :","r":["le propane","le butane","l'éthane","le pentane"],"b":0,"e":"Préfixes : méth-1, éth-2, prop-3, but-4, pent-5."},{"q":"Le nom de CH₃-CH(CH₃)-CH₃ est :","r":["butane","méthylpropane","propane","diméthyléthane"],"b":1,"e":"Chaîne principale de 3 carbones avec un groupe méthyle en 2."},{"q":"La formule brute du butane est :","r":["C₄H₈","C₄H₆","C₄H₁₀","C₃H₈"],"b":2,"e":"n = 4 : C₄H₂ₓ₄₊₂."},{"q":"Autour d'un carbone d'alcane, la géométrie est :","r":["plane","linéaire","carrée","tétraédrique"],"b":3,"e":"Angles de liaison voisins de 109°."},{"q":"Le butane et le méthylpropane sont :","r":["des isomères","le même composé","des alcènes","des alcools"],"b":0,"e":"Même formule brute C₄H₁₀, enchaînements différents."},{"q":"Le gaz domestique des bouteilles contient surtout :","r":["du méthane","du butane","de l'éthylène","de l'acétylène"],"b":1,"e":"Il est liquéfié sous pression."},{"q":"La masse molaire du propane C₃H₈ (C = 12, H = 1) vaut :","r":["42 g/mol","36 g/mol","44 g/mol","48 g/mol"],"b":2,"e":"3 × 12 + 8 × 1 = 44."},{"q":"Pour nommer un alcane ramifié, on choisit d'abord :","r":["le groupe substituant le plus petit de la molécule","le premier carbone écrit dans la formule","la chaîne carbonée la plus courte","la chaîne carbonée la plus longue"],"b":3,"e":"On numérote ensuite pour donner les plus petits indices aux ramifications."}],"c":"1re C","m":"chimie","rang":1,"apc":{"module":"Chimie organique : hydrocarbures et composés oxygénés","famille":"Usage des produits pétroliers et des matières plastiques","agir":"Identifier et utiliser de façon sûre les composés organiques","situation":"Une vendeuse de gaz de Bafoussam se demande ce que contient sa bouteille, qui renferme surtout du butane.","tache":"Donne sa formule brute et dessine sa formule semi-développée."},"gratuit":true});
VRT_L("1re-c-chimie-r02",{"duree":20,"titre":"Propriétés des alcanes et préparation du méthane","accroche":"Bien brûler pour ne pas s'intoxiquer.","intro":"Les alcanes brûlent et subissent des substitutions ; le méthane se prépare au laboratoire.","objectifs":["écrire une combustion","décrire une substitution","préparer le méthane"],"parties":[{"t":"Combustion","html":"<div class='def'><b>Définition</b>La <strong>combustion complète</strong> d'un alcane donne du dioxyde de carbone et de l'eau : CH₄ + 2O₂ → CO₂ + 2H₂O. Incomplète, elle produit du monoxyde de carbone, toxique.</div>"},{"t":"Substitution","verrou":true},{"t":"Préparation du méthane","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"chimie","rang":2,"apc":{"module":"Chimie organique : hydrocarbures et composés oxygénés","famille":"Usage des produits pétroliers et des matières plastiques","agir":"Identifier et utiliser de façon sûre les composés organiques","situation":"Une famille de Bamenda cuisine au gaz dans une pièce fermée et ressent des maux de tête.","tache":"Explique le danger et donne un conseil."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-chimie-r03",{"duree":20,"titre":"Alcènes et alcynes : structure et nomenclature","accroche":"Une double ou une triple liaison.","intro":"Les alcènes et les alcynes sont des hydrocarbures insaturés.","objectifs":["écrire leurs formules générales","décrire leur géométrie","les nommer"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>Un <strong>alcène</strong> (CₙH₂ₙ) contient une double liaison C=C, plane, angles de 120°. Un <strong>alcyne</strong> (CₙH₂ₙ₋₂) contient une triple liaison C≡C, linéaire.</div>"},{"t":"Nomenclature","verrou":true},{"t":"Isomérie Z/E","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"chimie","rang":3,"apc":{"module":"Chimie organique : hydrocarbures et composés oxygénés","famille":"Usage des produits pétroliers et des matières plastiques","agir":"Identifier et utiliser de façon sûre les composés organiques","situation":"Dans une plantation de Penja, on mûrit les bananes avec de l'éthylène, le plus simple des alcènes.","tache":"Donne sa formule et sa géométrie."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-chimie-r04",{"duree":20,"titre":"Propriétés des alcènes et alcynes ; acétylène","accroche":"Des additions et des plastiques.","intro":"La liaison multiple permet des réactions d'addition et de polymérisation.","objectifs":["écrire des additions","appliquer la règle de Markovnikov","décrire une polymérisation"],"parties":[{"t":"Additions","html":"<div class='def'><b>Définition</b>Les alcènes et alcynes donnent des <strong>additions</strong> : H₂, Br₂ (décoloration de l'eau de brome), HCl, H₂O. <strong>Règle de Markovnikov</strong> : lors de l'addition de HX, H se fixe sur le carbone le plus hydrogéné.</div>"},{"t":"Polymérisation","verrou":true},{"t":"Acétylène","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"chimie","rang":4,"apc":{"module":"Chimie organique : hydrocarbures et composés oxygénés","famille":"Usage des produits pétroliers et des matières plastiques","agir":"Identifier et utiliser de façon sûre les composés organiques","situation":"Une entreprise de Douala doit produire 120 kg d'isolants en polyéthylène.","tache":"Écris l'équation de polymérisation et calcule la masse d'éthylène nécessaire."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-chimie-r05",{"duree":20,"titre":"Composés oxygénés : généralités","accroche":"Alcool, aldéhyde, cétone, acide.","intro":"Un groupe fonctionnel oxygéné donne à la molécule ses propriétés.","objectifs":["reconnaître les groupes fonctionnels","nommer les composés simples","trouver une formule brute"],"parties":[{"t":"Groupes fonctionnels","html":"<div class='def'><b>Définition</b>Un <strong>groupe fonctionnel</strong> est un groupe d'atomes responsable des propriétés : alcool (−OH), aldéhyde (−CHO), cétone (C=O entre deux carbones), acide carboxylique (−COOH), ester (−COO−).</div>"},{"t":"Nomenclature","verrou":true},{"t":"Formule brute","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"chimie","rang":5,"apc":{"module":"Chimie organique : hydrocarbures et composés oxygénés","famille":"Usage des produits pétroliers et des matières plastiques","agir":"Identifier et utiliser de façon sûre les composés organiques","situation":"Le vin de palme de la région de l'Ouest s'aigrit en quelques jours.","tache":"Nomme les composés oxygénés en jeu."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-chimie-r06",{"duree":20,"titre":"Propriétés physiques et tests des aldéhydes et cétones","accroche":"Un précipité, un miroir d'argent.","intro":"Des réactifs simples distinguent aldéhydes et cétones.","objectifs":["utiliser la DNPH","distinguer aldéhyde et cétone","expliquer les températures d'ébullition"],"parties":[{"t":"Tests","html":"<div class='def'><b>Définition</b>La <strong>DNPH</strong> donne un précipité jaune-orangé avec les aldéhydes et les cétones. Seuls les <strong>aldéhydes</strong> réduisent la liqueur de Fehling (précipité rouge brique), le réactif de Tollens (miroir d'argent) et rosissent le réactif de Schiff.</div>"},{"t":"Propriétés physiques","verrou":true},{"t":"Démarche","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"chimie","rang":6,"apc":{"module":"Chimie organique : hydrocarbures et composés oxygénés","famille":"Usage des produits pétroliers et des matières plastiques","agir":"Identifier et utiliser de façon sûre les composés organiques","situation":"Au laboratoire d'un lycée de Bafia, deux flacons sans étiquette contiennent l'un de l'éthanal, l'autre de la propanone.","tache":"Propose un test pour les identifier."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-chimie-r07",{"duree":20,"titre":"Les composés aromatiques : généralités","accroche":"Le benzène, un cycle très stable.","intro":"Les composés aromatiques contiennent le noyau benzénique.","objectifs":["décrire le benzène","expliquer la délocalisation","nommer des dérivés"],"parties":[{"t":"Le benzène","html":"<div class='def'><b>Définition</b>Le <strong>benzène</strong> C₆H₆ est un cycle plan de six carbones. Ses six électrons π sont <strong>délocalisés</strong> sur tout le cycle : toutes les liaisons C−C mesurent 140 pm.</div>"},{"t":"Dérivés","verrou":true},{"t":"Sécurité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"chimie","rang":7,"apc":{"module":"Chimie organique : hydrocarbures et composés oxygénés","famille":"Usage des produits pétroliers et des matières plastiques","agir":"Identifier et utiliser de façon sûre les composés organiques","situation":"Un vendeur de carburant frelaté à Kousseri manipule l'essence sans gants ni masque.","tache":"Explique le danger."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-chimie-r08",{"duree":20,"titre":"Propriétés chimiques des composés aromatiques","accroche":"Substituer plutôt qu'additionner.","intro":"Le noyau benzénique donne surtout des substitutions, qui le conservent.","objectifs":["écrire une halogénation","écrire une nitration","écrire une addition"],"parties":[{"t":"Substitutions","html":"<div class='def'><b>Définition</b>Le benzène donne principalement des <strong>substitutions</strong> : halogénation (Cl₂ avec AlCl₃), nitration (HNO₃ avec H₂SO₄), alkylation de Friedel-Crafts.</div>"},{"t":"Additions","verrou":true},{"t":"Le TNT","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"chimie","rang":8,"apc":{"module":"Chimie organique : hydrocarbures et composés oxygénés","famille":"Usage des produits pétroliers et des matières plastiques","agir":"Identifier et utiliser de façon sûre les composés organiques","situation":"Une carrière de la région du Centre utilise des explosifs dérivés du toluène.","tache":"Écris la nitration du toluène et calcule la masse de TNT obtenue à partir de 250 g de toluène, avec 80 % de rendement."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-chimie-r09",{"duree":20,"titre":"Action des acides et des ions métalliques sur les métaux","accroche":"Un clou qui se couvre de cuivre.","intro":"Ces réactions mettent en jeu un transfert d'électrons : ce sont des oxydoréductions.","objectifs":["écrire l'action d'un acide sur un métal","écrire une réaction métal-ion","définir oxydant et réducteur"],"parties":[{"t":"Concepts clés","html":"<div class='def'><b>Définition</b>Un <strong>oxydant</strong> capte des électrons ; un <strong>réducteur</strong> en cède. L'<strong>oxydation</strong> est une perte d'électrons, la <strong>réduction</strong> un gain.</div>"},{"t":"Exemples","html":"<p>Zn + 2H₃O⁺ → Zn²⁺ + H₂ + 2H₂O. Un clou de fer dans une solution de sulfate de cuivre : Fe + Cu²⁺ → Fe²⁺ + Cu.</p>","labo":{"type":"calcul","f":"mole","vals":{"m":27,"M":27}}},{"t":"Calcul","html":"<p>2Al + 6H₃O⁺ → 2Al³⁺ + 3H₂ + 6H₂O. 27 g d'aluminium (1 mol) donnent 1,5 mol de H₂, soit 36 L si V_m = 24 L/mol.</p>","retenir":"Oxydation : perte d'électrons."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Vérification des savoirs.</strong> Le fer réagit avec l'acide chlorhydrique en libérant :</p><ol type='a'><li>du dioxygène</li><li>du dichlore</li><li>du dihydrogène</li><li>du dioxyde de carbone</li></ol><details><summary>Voir la réponse</summary><p><strong>du dihydrogène</strong>. Fe + 2H⁺ → Fe²⁺ + H₂.</p></details><p><strong>Application directe des savoirs.</strong></p><p>Dans Fe + Cu²⁺ → Fe²⁺ + Cu, qui est oxydé ?</p><details><summary>Voir la réponse</summary><p>(Réponse : le fer.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Un bijoutier de Foumban veut connaître la composition d'un laiton (cuivre et zinc). Il attaque 10 g d'alliage par un excès d'acide chlorhydrique et recueille 1,2 L de dihydrogène. M(Zn) = 65,4 g/mol ; V_m = 24 L/mol.</p><p><strong>Consigne 1.</strong> Écris l'équation de la réaction et indique quel métal réagit.</p><p><strong>Consigne 2.</strong> Calcule le pourcentage massique de zinc.</p><details><summary>Voir une réponse attendue</summary><p>Zn + 2H₃O⁺ → Zn²⁺ + H₂ + 2H₂O ; le cuivre ne réagit pas. n(H₂) = 0,05 mol = n(Zn), m = 3,27 g, soit 32,7 % de zinc.</p></details></div>","retenir":"Savoir-être mobilisé : Souci de la sécurité au laboratoire."}],"revision":["Oxydant, réducteur.","Oxydation, réduction.","Bilan."],"exo":"<p>Dans Fe + Cu²⁺ → Fe²⁺ + Cu, qui est oxydé ? <em>(Réponse : le fer.)</em></p>","quiz":[{"q":"Le fer réagit avec l'acide chlorhydrique en libérant :","r":["du dioxygène","du dichlore","du dihydrogène","du dioxyde de carbone"],"b":2,"e":"Fe + 2H⁺ → Fe²⁺ + H₂."},{"q":"Le cuivre réagit-il avec l'acide chlorhydrique dilué ?","r":["oui, vivement","oui, avec dégagement de chlore","oui, il devient rouge","non"],"b":3,"e":"Le cuivre est moins réducteur que l'hydrogène."},{"q":"Un clou de fer plongé dans une solution de sulfate de cuivre se couvre :","r":["d'un dépôt de cuivre","de rouille","de sel","de fer pur métallique"],"b":0,"e":"Fe + Cu²⁺ → Fe²⁺ + Cu."},{"q":"Dans cette réaction, le fer :","r":["est réduit","est oxydé","ne réagit pas","se dépose"],"b":1,"e":"Il perd des électrons."},{"q":"Les ions Cu²⁺ dans cette réaction sont :","r":["oxydés","spectateurs","réduits","détruits"],"b":2,"e":"Ils gagnent des électrons."},{"q":"La couleur bleue d'une solution est due aux ions :","r":["Fe²⁺","Zn²⁺","Na⁺","Cu²⁺"],"b":3,"e":"Fe²⁺ est vert pâle ; Zn²⁺ et Na⁺ incolores."},{"q":"Un réducteur est une espèce qui :","r":["cède des électrons","capte des électrons","capte des protons","cède des protons"],"b":0,"e":"Ex. : les métaux."},{"q":"Un oxydant est une espèce qui :","r":["cède des électrons","capte des électrons","cède des protons","ne réagit jamais"],"b":1,"e":"Ex. : Cu²⁺, H⁺."},{"q":"Le zinc plongé dans une solution de Cu²⁺ :","r":["ne réagit pas","dégage du dioxygène","se recouvre de cuivre","se colore en bleu"],"b":2,"e":"Zn + Cu²⁺ → Zn²⁺ + Cu."},{"q":"Le test du dihydrogène est :","r":["le trouble de l'eau de chaux par le gaz dégagé","le rallumage d'une bûchette incandescente","une coloration bleue","une légère détonation à l'approche d'une flamme"],"b":3,"e":"Il brûle avec le dioxygène de l'air."}],"c":"1re C","m":"chimie","rang":9,"apc":{"module":"Oxydoréduction","famille":"Protection des métaux et production d'énergie","agir":"Prévenir la corrosion et exploiter les réactions d'oxydoréduction","situation":"Un chaudronnier de Garoua nettoie des copeaux d'aluminium de 27 g avec de l'acide chlorhydrique en excès.","tache":"Quel volume de gaz se dégage-t-il ?"},"gratuit":true});
VRT_L("1re-c-chimie-r10",{"duree":20,"titre":"Couples oxydant-réducteur","accroche":"Deux formes d'une même espèce.","intro":"Chaque oxydant est associé à un réducteur conjugué : ils forment un couple.","objectifs":["définir un couple","écrire une demi-équation","combiner deux demi-équations"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Un <strong>couple oxydant/réducteur</strong> est formé de deux espèces liées par la demi-équation <strong>Ox + ne⁻ ⇌ Red</strong>.</div>"},{"t":"Exemples","verrou":true},{"t":"Bilan","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"chimie","rang":10,"apc":{"module":"Oxydoréduction","famille":"Protection des métaux et production d'énergie","agir":"Prévenir la corrosion et exploiter les réactions d'oxydoréduction","situation":"Une bijoutière de Foumban dépose une fine couche d'argent sur un bijou en cuivre plongé dans une solution d'ions argent.","tache":"Écris les demi-équations et le bilan."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-chimie-r11",{"duree":20,"titre":"Classification électrochimique","accroche":"Prévoir qui réagit avec qui.","intro":"Classer les couples permet de prévoir les réactions spontanées.","objectifs":["classer des couples","appliquer la règle du gamma","prévoir l'action des acides"],"parties":[{"t":"La classification","html":"<div class='def'><b>Définition</b>On classe les couples selon leur potentiel standard E°. L'oxydant le plus fort réagit spontanément avec le réducteur le plus fort (<strong>règle du gamma</strong>).</div>"},{"t":"Ordre utile","verrou":true},{"t":"Prévisions","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"chimie","rang":11,"apc":{"module":"Oxydoréduction","famille":"Protection des métaux et production d'énergie","agir":"Prévenir la corrosion et exploiter les réactions d'oxydoréduction","situation":"Un menuisier de Kribi range ses clous en fer dans une boîte en cuivre humide.","tache":"Lequel des deux métaux sera attaqué ? Justifie."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-chimie-r12",{"duree":20,"titre":"La pile Daniell : description","accroche":"Une pile de laboratoire de 1,1 V.","intro":"La pile Daniell exploite la réaction entre le zinc et les ions cuivre, sans contact direct.","objectifs":["décrire la pile","écrire sa notation conventionnelle","indiquer les pôles"],"parties":[{"t":"Description","html":"<div class='def'><b>Définition</b>La <strong>pile Daniell</strong> comprend une lame de zinc dans une solution de Zn²⁺ et une lame de cuivre dans une solution de Cu²⁺, reliées par un <strong>pont salin</strong>.</div>"},{"t":"Fonctionnement","verrou":true},{"t":"Notation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"chimie","rang":12,"apc":{"module":"Oxydoréduction","famille":"Protection des métaux et production d'énergie","agir":"Prévenir la corrosion et exploiter les réactions d'oxydoréduction","situation":"Au club scientifique d'un lycée de Bertoua, des élèves fabriquent une pile Daniell pour allumer une diode.","tache":"Décris le montage et indique les pôles."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-chimie-r13",{"duree":20,"titre":"Potentiels et force électromotrice d'une pile","accroche":"Calculer la tension à vide.","intro":"Les potentiels standards permettent de prévoir la force électromotrice d'une pile.","objectifs":["définir le potentiel standard","calculer une f.é.m.","identifier les pôles"],"parties":[{"t":"Potentiel standard","html":"<div class='def'><b>Définition</b>Le <strong>potentiel standard</strong> E° d'un couple est mesuré par rapport à l'électrode standard à hydrogène (E° = 0 V).</div>"},{"t":"Force électromotrice","verrou":true},{"t":"Pôles","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"chimie","rang":13,"apc":{"module":"Oxydoréduction","famille":"Protection des métaux et production d'énergie","agir":"Prévenir la corrosion et exploiter les réactions d'oxydoréduction","situation":"Un électricien de Ngaoundéré veut une pile de plus de 1 V avec des métaux de récupération : zinc, plomb, cuivre.","tache":"Quel couple de métaux choisir ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-chimie-r14",{"duree":20,"titre":"Couples autres que métal/ion métallique","accroche":"Permanganate, dichromate, iode.","intro":"Beaucoup d'oxydants et de réducteurs ne sont pas des métaux ; leurs demi-équations font intervenir l'eau et les ions H⁺.","objectifs":["équilibrer une demi-équation en milieu acide","citer des couples usuels","écrire un bilan"],"parties":[{"t":"Méthode","html":"<div class='def'><b>Définition</b>Pour équilibrer une demi-équation en milieu acide : équilibrer l'élément principal, puis O avec H₂O, puis H avec H⁺, puis les charges avec e⁻.</div>"},{"t":"Couples usuels","verrou":true},{"t":"Bilan","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"chimie","rang":14,"apc":{"module":"Oxydoréduction","famille":"Protection des métaux et production d'énergie","agir":"Prévenir la corrosion et exploiter les réactions d'oxydoréduction","situation":"Les éthylotests chimiques utilisés à Yaoundé virent de l'orange au vert en présence d'alcool.","tache":"Explique ce changement de couleur."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-chimie-r15",{"duree":20,"titre":"Dosages d'oxydoréduction","accroche":"Trouver une concentration inconnue.","intro":"Un dosage utilise une réaction rapide et totale ; l'équivalence se repère par un changement de couleur.","objectifs":["décrire le montage","écrire la relation à l'équivalence","calculer une concentration"],"parties":[{"t":"Équivalence","html":"<div class='def'><b>Définition</b>À l'<strong>équivalence</strong>, les réactifs ont été introduits dans les proportions stœchiométriques. Pour MnO₄⁻ + 5Fe²⁺ : n(Fe²⁺) = 5 × n(MnO₄⁻).</div>"},{"t":"Exemple","verrou":true},{"t":"Repérage","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"chimie","rang":15,"apc":{"module":"Oxydoréduction","famille":"Protection des métaux et production d'énergie","agir":"Prévenir la corrosion et exploiter les réactions d'oxydoréduction","situation":"Le club scientifique d'un lycée de l'Ouest dose l'alcool dans le sang d'un élève par le dichromate, selon le règlement intérieur qui fixe le seuil à 0,5 g/L.","tache":"Indique la démarche pour décider."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-chimie-r16",{"duree":20,"titre":"Électrolyse, corrosion et protection des métaux","accroche":"La rouille coûte cher.","intro":"L'électrolyse force une réaction ; la corrosion est une oxydation naturelle des métaux.","objectifs":["décrire une électrolyse","expliquer la corrosion du fer","choisir une protection"],"parties":[{"t":"Électrolyse","html":"<div class='def'><b>Définition</b>Une <strong>électrolyse</strong> est une réaction d'oxydoréduction forcée par un générateur. L'oxydation a lieu à l'anode (reliée au pôle +), la réduction à la cathode.</div>"},{"t":"Corrosion","verrou":true},{"t":"Protection","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"chimie","rang":16,"apc":{"module":"Oxydoréduction","famille":"Protection des métaux et production d'énergie","agir":"Prévenir la corrosion et exploiter les réactions d'oxydoréduction","situation":"Les tôles des maisons du quartier de Bonabéri, près de la mer, rouillent très vite.","tache":"Explique pourquoi et propose deux protections."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-chimie-r17",{"duree":20,"titre":"Le nombre d'oxydation","accroche":"Un compteur d'électrons.","intro":"Le nombre d'oxydation généralise les notions d'oxydation et de réduction, même sans ions.","objectifs":["appliquer les règles","calculer un nombre d'oxydation","repérer oxydation et réduction"],"parties":[{"t":"Règles","html":"<div class='def'><b>Définition</b>Le <strong>nombre d'oxydation</strong> (n.o.) vaut 0 pour un corps simple, la charge pour un ion monoatomique ; O vaut −2 (sauf peroxydes), H vaut +1 ; la somme des n.o. est égale à la charge de l'édifice.</div>"},{"t":"Exemples","html":"<p>Mn dans MnO₄⁻ : +7. Cr dans Cr₂O₇²⁻ : +6. S dans H₂SO₄ : +6.</p>","labo":{"type":"etapes","items":[["Charge","somme des n.o."],["Oxygène","−2 chacun."],["Hydrogène","+1 chacun."],["Inconnu","par différence."]]}},{"t":"Interprétation","html":"<p>Une oxydation est une augmentation du n.o. ; une réduction, une diminution.</p>","retenir":"Somme des n.o. = charge."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Vérification des savoirs.</strong> Le nombre d'oxydation (n.o.) de l'oxygène est généralement :</p><ol type='a'><li>+II</li><li>0</li><li>−I</li><li>−II</li></ol><details><summary>Voir la réponse</summary><p><strong>−II</strong>. Sauf dans les peroxydes (−I).</p></details><p><strong>Application directe des savoirs.</strong></p><p>n.o. du carbone dans CO₂ ?</p><details><summary>Voir la réponse</summary><p>(Réponse : +4.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Dans l'industrie des engrais, l'ammoniac est oxydé : 4NH₃ + 5O₂ → 4NO + 6H₂O, puis NO devient NO₂ puis HNO₃.</p><p><strong>Consigne 1.</strong> Calcule le nombre d'oxydation de l'azote dans NH₃, NO, NO₂, HNO₃ et N₂.</p><p><strong>Consigne 2.</strong> Montre que la première réaction est une oxydoréduction en précisant l'oxydant et le réducteur.</p><details><summary>Voir une réponse attendue</summary><p>N : −3 (NH₃), +2 (NO), +4 (NO₂), +5 (HNO₃), 0 (N₂). L'azote passe de −3 à +2 (oxydé) ; l'oxygène de 0 à −2 (réduit) : O₂ est l'oxydant, NH₃ le réducteur.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans la démarche expérimentale."}],"revision":["Règles.","Calculs.","Augmentation : oxydation."],"exo":"<p>n.o. du carbone dans CO₂ ? <em>(Réponse : +4.)</em></p>","quiz":[{"q":"Le nombre d'oxydation (n.o.) de l'oxygène est généralement :","r":["+II","0","−I","−II"],"b":3,"e":"Sauf dans les peroxydes (−I)."},{"q":"Le n.o. de l'hydrogène dans les composés est généralement :","r":["+I","−I","0","+II"],"b":0,"e":"Sauf dans les hydrures métalliques."},{"q":"Le n.o. d'un corps simple (Fe, O₂, Cl₂) est :","r":["+I","0","−II","égal à sa masse"],"b":1,"e":"Aucun transfert d'électrons."},{"q":"Le n.o. du soufre dans H₂SO₄ est :","r":["+IV","−II","+VI","+II"],"b":2,"e":"2(+I) + x + 4(−II) = 0."},{"q":"Le n.o. du soufre dans H₂S est :","r":["+II","+VI","0","−II"],"b":3,"e":"Somme nulle : 2 × (+I) + x = 0, donc x = −II."},{"q":"Le n.o. du manganèse dans MnO₄⁻ est :","r":["+VII","+II","+IV","−I"],"b":0,"e":"x + 4(−II) = −1."},{"q":"La somme des n.o. dans un ion vaut :","r":["zéro toujours","la charge de l'ion","le nombre d'atomes","la masse molaire"],"b":1,"e":"Ex. : SO₄²⁻ : somme = −2."},{"q":"Une oxydation correspond à :","r":["une diminution du n.o.","un n.o. inchangé","une augmentation du n.o.","un n.o. nul"],"b":2,"e":"L'élément perd des électrons."},{"q":"Le n.o. de l'azote dans NH₃ est :","r":["+III","0","+V","−III"],"b":3,"e":"Somme nulle : x + 3 × (+I) = 0, donc x = −III."},{"q":"Le n.o. de l'azote dans HNO₃ est :","r":["+V","−III","+III","+I"],"b":0,"e":"(+I) + x + 3(−II) = 0."}],"c":"1re C","m":"chimie","rang":17,"apc":{"module":"Oxydoréduction","famille":"Protection des métaux et production d'énergie","agir":"Prévenir la corrosion et exploiter les réactions d'oxydoréduction","situation":"Un réparateur de batteries de Dschang manipule l'acide des batteries, H₂SO₄ ; il range aussi du dioxyde de soufre SO₂ et du sulfure d'hydrogène H₂S, à l'odeur d'œuf pourri. Son apprenti croit que le soufre a toujours le même nombre d'oxydation.","tache":"Calcule le nombre d'oxydation du soufre dans H₂SO₄, SO₂ et H₂S, puis réponds à l'apprenti."},"gratuit":true});
VRT_L("1re-c-chimie-r18",{"duree":20,"titre":"Utiliser le nombre d'oxydation","accroche":"Équilibrer sans ions.","intro":"Les n.o. permettent d'équilibrer des réactions en voie sèche, comme la métallurgie.","objectifs":["équilibrer avec les n.o.","étudier une réduction d'oxyde","décrire une métallurgie"],"parties":[{"t":"Méthode","html":"<div class='def'><b>Définition</b>La somme des augmentations de n.o. doit être égale à la somme des diminutions.</div>"},{"t":"Exemples","verrou":true},{"t":"Voie sèche","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"chimie","rang":18,"apc":{"module":"Oxydoréduction","famille":"Protection des métaux et production d'énergie","agir":"Prévenir la corrosion et exploiter les réactions d'oxydoréduction","situation":"Dans une usine de Douala, on récupère le cuivre d'oxydes usés en les chauffant dans un courant d'ammoniac : il se forme du cuivre, de l'eau et du diazote. Le contremaître note : CuO + NH₃ → Cu + H₂O + N₂ et veut savoir quelle masse d'ammoniac prévoir pour 1 mol de CuO.","tache":"Équilibre l'équation à l'aide des nombres d'oxydation, puis donne la quantité d'ammoniac pour 1 mol de CuO."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-ecm-r01",{"duree":20,"titre":"Les droits de l'homme","accroche":"Des droits pour chaque être humain, partout.","intro":"Les droits de l'homme sont les droits que toute personne possède du seul fait qu'elle est un être humain. Ils sont proclamés par des textes internationaux et par la Constitution camerounaise.","objectifs":["définir les droits de l'homme","en connaître les caractères","citer les textes qui les proclament"],"parties":[{"t":"Définition et caractères","html":"<div class='def'><b>Définition</b>Les <strong>droits de l'homme</strong> sont l'ensemble des droits et libertés fondamentaux reconnus à toute personne humaine, sans distinction de sexe, d'origine, de religion ou d'opinion.</div><p>Ils sont <strong>universels</strong> (valables pour tous), <strong>inaliénables</strong> (on ne peut pas les céder), <strong>indivisibles</strong> et <strong>interdépendants</strong> (tous se tiennent).</p>"},{"t":"Les catégories de droits","html":"<ul><li><strong>Droits civils et politiques</strong> : droit à la vie, liberté d'expression, droit de vote, procès équitable.</li><li><strong>Droits économiques, sociaux et culturels</strong> : droit à l'éducation, à la santé, au travail, au logement.</li><li><strong>Droits de solidarité</strong> : droit à la paix, au développement, à un environnement sain.</li></ul>","retenir":"Trois générations de droits : civils et politiques, économiques et sociaux, de solidarité.","labo":{"type":"trier","invite":"Choisis une catégorie de droits.","items":[["Civils et politiques","vie, expression, vote, procès équitable."],["Économiques, sociaux et culturels","éducation, santé, travail, logement."],["De solidarité","paix, développement, environnement sain."]]}},{"t":"Les textes fondamentaux","html":"<ul><li>la <strong>Déclaration universelle des droits de l'homme</strong>, adoptée par l'ONU le 10 décembre 1948 ;</li><li>la <strong>Charte africaine des droits de l'homme et des peuples</strong>, adoptée en 1981 ;</li><li>la <strong>Convention relative aux droits de l'enfant</strong> de 1989 ;</li><li>le <strong>préambule de la Constitution</strong> camerounaise du 18 janvier 1996.</li></ul><div class='attention'><b>Attention</b>à chaque droit correspond un devoir : respecter les droits des autres.</div>"},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Question de cours.</strong> Les droits de l'homme sont reconnus à toute personne :</p><ol type='a'><li>seulement si elle paie ses impôts</li><li>à partir de l'âge de la majorité électorale</li><li>du seul fait qu'elle est un être humain</li><li>seulement si elle est de nationalité camerounaise</li></ol><details><summary>Voir la réponse</summary><p><strong>du seul fait qu'elle est un être humain</strong>. Ils sont universels.</p></details><p><strong>Exercice.</strong></p><p>Le droit à l'éducation appartient à quelle catégorie ?</p><details><summary>Voir la réponse</summary><p>(Réponse : aux droits économiques, sociaux et culturels.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Document : rapport d'une ONG signalant des enfants travaillant dans une carrière de pierres à la périphérie de Yaoundé, sans scolarisation.</p><p><strong>Consigne 1.</strong> Identifie deux droits de l'enfant violés.</p><p><strong>Consigne 2.</strong> Propose deux actions et les acteurs à mobiliser.</p><details><summary>Voir une réponse attendue</summary><p>Droit à l'éducation et droit d'être protégé contre l'exploitation économique. Actions : signalement aux services des Affaires sociales et à la CDHC ; campagne de sensibilisation des parents avec les chefs de quartier et une aide à la scolarisation.</p></details></div>","retenir":"Savoir-être mobilisé : Tolérance et respect de l'autre."}],"revision":["Droits universels, inaliénables, indivisibles.","Civils et politiques ; économiques, sociaux et culturels ; de solidarité.","DUDH 1948, Charte africaine 1981, CDE 1989, Constitution 1996."],"exo":"<p>Le droit à l'éducation appartient à quelle catégorie ? <em>(Réponse : aux droits économiques, sociaux et culturels.)</em></p>","quiz":[{"q":"Les droits de l'homme sont reconnus à toute personne :","r":["seulement si elle paie ses impôts","à partir de l'âge de la majorité électorale","du seul fait qu'elle est un être humain","seulement si elle est de nationalité camerounaise"],"b":2,"e":"Ils sont universels."},{"q":"La Déclaration universelle des droits de l'homme a été adoptée le :","r":["24 octobre 1945","25 mai 1963","18 janvier 1996","10 décembre 1948"],"b":3,"e":"Adoptée par l'Assemblée générale de l'ONU à Paris."},{"q":"Dire que les droits de l'homme sont inaliénables signifie :","r":["qu'on ne peut pas les céder ni les perdre","qu'ils ne concernent que les étrangers","qu'ils changent selon les pays","qu'on peut les vendre à un tiers"],"b":0,"e":"Personne ne peut y renoncer ni en être privé arbitrairement."},{"q":"Le droit à l'éducation fait partie des droits :","r":["civils et politiques uniquement","économiques, sociaux et culturels","de solidarité entre les peuples","réservés aux adultes"],"b":1,"e":"Comme la santé, le travail, le logement."},{"q":"Le droit de vote fait partie des droits :","r":["économiques et sociaux","de solidarité","civils et politiques","culturels seulement"],"b":2,"e":"Il permet de participer à la vie politique."},{"q":"Le droit à un environnement sain est un droit :","r":["civil et politique","économique et individuel","réservé aux États","de solidarité"],"b":3,"e":"Les droits de solidarité concernent toute la collectivité."},{"q":"La Charte africaine des droits de l'homme et des peuples a été adoptée en :","r":["1981","1948","1963","2002"],"b":0,"e":"Elle a été adoptée à Nairobi et est entrée en vigueur en 1986."},{"q":"La Convention relative aux droits de l'enfant date de :","r":["1948","1989","1996","2000"],"b":1,"e":"Adoptée par l'ONU le 20 novembre 1989."},{"q":"Au Cameroun, les droits fondamentaux sont proclamés dans :","r":["le règlement intérieur des écoles","le Code de la route","le préambule de la Constitution","les statuts des partis politiques"],"b":2,"e":"Le préambule de la Constitution de 1996 les énumère."},{"q":"À chaque droit correspond :","r":["un impôt particulier à payer chaque année à l'État","une autorisation du chef de l'État","un privilège réservé à certains","le devoir de respecter les droits des autres"],"b":3,"e":"Droits et devoirs vont ensemble."}],"c":"1re C","m":"ecm","rang":1,"apc":{"module":"Les droits humains","famille":"Vie citoyenne et droits humains","agir":"Promouvoir et défendre les droits humains dans son milieu","situation":"Dans un village du Mayo-Tsanaga, une fille de 13 ans est retirée de l'école par son père qui veut la marier ; sa camarade de classe s'indigne mais ne sait pas comment réagir.","tache":"Identifie deux droits de l'enfant violés et indique deux personnes ou structures auxquelles la camarade peut s'adresser."},"gratuit":true});
VRT_L("1re-c-ecm-r02",{"duree":20,"titre":"Les institutions de protection des droits de l'homme","accroche":"Qui défend nos droits quand ils sont violés ?","intro":"Des institutions nationales et internationales veillent au respect des droits de l'homme : elles reçoivent les plaintes, enquêtent, sensibilisent et sanctionnent.","objectifs":["citer des institutions nationales de protection","citer des institutions internationales et africaines","savoir comment les saisir"],"parties":[{"t":"Au Cameroun","html":"<div class='def'><b>Définition</b>Une <strong>institution de protection des droits de l'homme</strong> est un organisme chargé de promouvoir les droits, de recevoir les plaintes et de faire cesser les violations.</div><ul><li>la <strong>Commission des droits de l'homme du Cameroun</strong> (CDHC), créée en 2019 pour remplacer la Commission nationale des droits de l'homme et des libertés ;</li><li>les <strong>tribunaux</strong>, gardiens des libertés individuelles ;</li><li>le <strong>Parlement</strong>, qui vote les lois protectrices ;</li><li>les <strong>ministères</strong> chargés des Affaires sociales et de la Promotion de la femme et de la famille ;</li><li>les <strong>associations et ONG</strong> de défense des droits.</li></ul>"},{"t":"Au niveau africain et mondial","verrou":true},{"t":"Saisir une institution","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"ecm","rang":2,"apc":{"module":"Les droits humains","famille":"Vie citoyenne et droits humains","agir":"Promouvoir et défendre les droits humains dans son milieu","situation":"Moussa, 17 ans, a été gardé à vue quatre jours dans un commissariat de Maroua sans voir de magistrat ni pouvoir prévenir sa famille ; son oncle veut « régler l'affaire avec de l'argent ».","tache":"Indique les droits de Moussa qui ont été méconnus et propose à son oncle une démarche légale."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-ecm-r03",{"duree":20,"titre":"TD : étude d'une structure locale de promotion des droits de l'homme","accroche":"Enquêter près de chez soi.","intro":"Ce travail dirigé conduit à identifier et étudier une structure de sa localité qui promeut les droits de l'homme : centre social, association, clinique juridique, antenne de la CDHC.","objectifs":["préparer une enquête","présenter une structure","évaluer son action"],"parties":[{"t":"Préparer l'enquête","html":"<div class='def'><b>Définition</b>Une <strong>enquête</strong> est une recherche d'informations auprès de personnes et de documents, menée avec un questionnaire préparé et une méthode.</div><ol><li>Choisir la structure et prendre rendez-vous.</li><li>Rédiger un questionnaire : missions, public, activités, moyens, difficultés.</li><li>Répartir les rôles : questions, prise de notes, photographies autorisées.</li></ol>"},{"t":"Présenter la structure","verrou":true},{"t":"Évaluer et restituer","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"ecm","rang":3,"apc":{"module":"Les droits humains","famille":"Vie citoyenne et droits humains","agir":"Promouvoir et défendre les droits humains dans son milieu","situation":"Ton groupe doit enquêter sur le centre social de ton arrondissement. Le responsable n'accorde que 30 minutes d'entretien et refuse que l'on photographie les personnes accueillies.","tache":"Rédige cinq questions prioritaires pour l'entretien et explique comment respecter la règle sur les photographies."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-ecm-r04",{"duree":20,"titre":"Le concept d'intégrité morale","accroche":"Être droit même quand personne ne regarde.","intro":"L'intégrité morale est une qualité essentielle du citoyen et de l'agent public. Son absence ouvre la porte à la corruption, à la fraude et au détournement.","objectifs":["définir l'intégrité morale","identifier ses manifestations et ses contraires","en mesurer l'importance pour la société"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>L'<strong>intégrité morale</strong> est la qualité d'une personne honnête, droite et incorruptible, qui agit conformément aux règles et à sa conscience, même lorsqu'elle pourrait tirer profit d'un manquement.</div><p>Elle se manifeste par l'<strong>honnêteté</strong>, la <strong>probité</strong>, le <strong>respect de la parole donnée</strong>, la <strong>loyauté</strong> et le <strong>sens du bien commun</strong>.</p>"},{"t":"Les atteintes à l'intégrité","verrou":true},{"t":"Pourquoi l'intégrité est-elle essentielle ?","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"ecm","rang":4,"apc":{"module":"L'intégrité morale","famille":"Vie citoyenne et morale","agir":"Adopter et promouvoir un comportement intègre","situation":"À l'approche du Probatoire, un message circule dans ta classe : « sujets disponibles contre 5 000 F ». Sept camarades veulent payer ; ta meilleure amie hésite.","tache":"Rédige un message de huit lignes pour la convaincre de refuser, en utilisant deux arguments liés à l'intégrité morale."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-ecm-r05",{"duree":20,"titre":"Les institutions de promotion et de préservation de l'intégrité morale au Cameroun","accroche":"Les gardiens de la probité publique.","intro":"Pour lutter contre la corruption et les détournements, le Cameroun a mis en place des institutions de prévention, de contrôle et de répression.","objectifs":["citer les institutions de lutte contre la corruption","préciser le rôle de chacune","savoir dénoncer un acte de corruption"],"parties":[{"t":"Les institutions de prévention","html":"<div class='def'><b>Définition</b>Une <strong>institution de préservation de l'intégrité morale</strong> est un organisme public chargé de prévenir, contrôler ou sanctionner les atteintes à la probité.</div><ul><li>la <strong>Commission nationale anti-corruption</strong> (CONAC), créée en 2006 : prévention, enquêtes, sensibilisation, réception des dénonciations ;</li><li>les <strong>cellules de lutte contre la corruption</strong> dans les ministères ;</li><li>l'<strong>Agence nationale d'investigation financière</strong> (ANIF) contre le blanchiment.</li></ul>"},{"t":"Les institutions de contrôle et de répression","verrou":true},{"t":"Dénoncer un acte de corruption","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"ecm","rang":5,"apc":{"module":"L'intégrité morale","famille":"Vie citoyenne et morale","agir":"Adopter et promouvoir un comportement intègre","situation":"Pour obtenir l'acte de naissance de son fils, une mère de Sangmélima s'entend dire par un agent : « reviens demain avec 3 000 F, sinon ton dossier dort ». L'acte est en principe délivré gratuitement.","tache":"Identifie l'infraction commise et indique à la mère deux institutions qu'elle peut saisir, avec la démarche à suivre."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-ecm-r06",{"duree":20,"titre":"TD : l'intégrité morale en milieu scolaire","accroche":"L'école, première école de l'intégrité.","intro":"Le lycée est un lieu où l'on apprend aussi à être honnête. Ce travail dirigé repère les atteintes à l'intégrité en milieu scolaire et construit des réponses.","objectifs":["identifier les atteintes à l'intégrité à l'école","en analyser les causes et les conséquences","élaborer une charte d'intégrité"],"parties":[{"t":"Les atteintes en milieu scolaire","html":"<div class='def'><b>Définition</b>Une <strong>atteinte à l'intégrité en milieu scolaire</strong> est tout comportement malhonnête qui fausse l'évaluation, l'accès aux services ou la vie commune à l'école.</div><ul><li>la tricherie aux devoirs et aux examens ;</li><li>l'achat de notes ou de places ;</li><li>la falsification de bulletins ou de signatures ;</li><li>le vol de matériel ;</li><li>le harcèlement en échange de notes.</li></ul>"},{"t":"Causes et conséquences","verrou":true},{"t":"Une charte d'intégrité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"ecm","rang":6,"apc":{"module":"L'intégrité morale","famille":"Vie citoyenne et morale","agir":"Adopter et promouvoir un comportement intègre","situation":"Lors d'une composition, l'enseignant de ton lycée de Bertoua découvre que 18 copies sur 52 sont identiques. Le club d'éducation à la citoyenneté veut agir avant les examens officiels.","tache":"Propose une charte de cinq engagements et deux actions du club pour la faire vivre."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-ecm-r07",{"duree":20,"titre":"Les médias et leur impact sur l'opinion publique","accroche":"Ce que nous pensons dépend de ce que nous lisons.","intro":"Les médias informent, éduquent et divertissent ; ils façonnent aussi l'opinion publique, pour le meilleur et parfois pour le pire.","objectifs":["définir les médias et l'opinion publique","citer les types de médias","analyser leur influence"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>Les <strong>médias</strong> sont les moyens de diffusion de l'information auprès d'un large public : presse écrite, radio, télévision, internet et réseaux sociaux. L'<strong>opinion publique</strong> est l'ensemble des idées et jugements partagés par une grande partie de la population sur une question.</div>"},{"t":"Les rôles des médias","verrou":true},{"t":"Impacts positifs et négatifs","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"ecm","rang":7,"apc":{"module":"Les médias et l'opinion publique","famille":"Vie citoyenne et communication","agir":"Exploiter les médias avec esprit critique","situation":"Un message audio partagé 2 000 fois sur WhatsApp affirme qu'un vaccin distribué gratuitement à Douala « rend stérile ». Dans ton quartier, des parents refusent de faire vacciner leurs enfants.","tache":"Explique l'impact de ce message sur l'opinion publique et propose trois gestes pour lutter contre cette fausse nouvelle."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-ecm-r08",{"duree":20,"titre":"La protection de l'opinion publique au Cameroun","accroche":"Liberté de la presse et responsabilité.","intro":"La liberté de communication est garantie, mais elle s'exerce dans le respect de la loi. Des textes et des institutions protègent le public contre la manipulation et les dérives.","objectifs":["connaître le cadre juridique de la communication","citer les institutions de régulation","identifier les limites de la liberté d'expression"],"parties":[{"t":"Le cadre juridique","html":"<div class='def'><b>Définition</b>La <strong>protection de l'opinion publique</strong> désigne l'ensemble des règles et institutions qui garantissent une information libre, pluraliste et responsable, et protègent le public contre les abus.</div><p>La <strong>loi du 19 décembre 1990</strong> sur la liberté de communication sociale organise la presse et l'audiovisuel ; le Code pénal sanctionne la diffamation, la propagation de fausses nouvelles et l'incitation à la haine. La loi de 2010 sur la cybersécurité et la cybercriminalité encadre internet.</p>"},{"t":"Les institutions de régulation","verrou":true},{"t":"Les limites de la liberté d'expression","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"ecm","rang":8,"apc":{"module":"Les médias et l'opinion publique","famille":"Vie citoyenne et communication","agir":"Exploiter les médias avec esprit critique","situation":"Un blogueur de Bafoussam publie la photo d'un enseignant de ton lycée avec la légende « voleur de notes », sans aucune preuve ; la publication est partagée 600 fois.","tache":"Explique pourquoi cette publication dépasse les limites de la liberté d'expression et indique les recours possibles pour l'enseignant."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-ecm-r09",{"duree":20,"titre":"TD : la publicité dans les médias","accroche":"Décoder un message qui veut nous faire acheter.","intro":"La publicité finance de nombreux médias. Ce travail dirigé apprend à analyser une publicité et à repérer ses procédés de persuasion.","objectifs":["définir la publicité","analyser une affiche ou un spot","adopter un comportement de consommateur averti"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>publicité</strong> est un message diffusé dans les médias pour faire connaître un produit, un service ou une idée et inciter le public à l'acheter ou à l'adopter.</div><p>On distingue la publicité <strong>commerciale</strong> et la publicité <strong>institutionnelle</strong> ou d'intérêt général (campagne contre le paludisme, pour la sécurité routière).</p>"},{"t":"Analyser une publicité","verrou":true},{"t":"Le consommateur averti","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"ecm","rang":9,"apc":{"module":"Les médias et l'opinion publique","famille":"Vie citoyenne et communication","agir":"Exploiter les médias avec esprit critique","situation":"Une affiche de Douala vante une crème qui « éclaircit la peau en 7 jours, 100 % sans danger », avec la photo d'une jeune femme souriante et le slogan « Brille comme une star ».","tache":"Analyse cette publicité (cible, procédés) et explique pourquoi elle peut être dangereuse et trompeuse."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-ecm-r10",{"duree":20,"titre":"Les atteintes à l'intégrité physique, morale et au patrimoine","accroche":"Protéger la personne et ses biens.","intro":"La loi protège la personne humaine dans son corps, dans son honneur et dans ses biens. Le Code pénal du 12 juillet 2016 punit les atteintes à ces droits.","objectifs":["distinguer les trois types d'atteintes","en donner des exemples","connaître les conduites à tenir"],"parties":[{"t":"Les atteintes à l'intégrité physique","html":"<div class='def'><b>Définition</b>Une <strong>atteinte à l'intégrité physique</strong> est un acte qui blesse le corps d'une personne ou met sa vie en danger.</div><p>Exemples : coups et blessures, meurtre, viol, mutilations génitales, châtiments corporels excessifs, bagarres.</p>"},{"t":"Les atteintes à l'intégrité morale","html":"<p>Elles blessent la dignité, l'honneur ou l'équilibre psychologique : injures, diffamation, menaces, harcèlement (y compris sur internet), humiliations, discriminations.</p><p>Les <strong>femmes</strong> en sont souvent victimes : violences conjugales, mariages forcés ou précoces, mutilations, et dans le monde du travail discrimination à l'embauche, inégalités de salaire, harcèlement sexuel, licenciement pour grossesse, interdits par le Code pénal et le Code du travail. Des associations comme l'ALVF (Association de lutte contre les violences faites aux femmes) accompagnent les victimes.</p>","retenir":"Les mots et les écrans peuvent aussi blesser.","labo":{"type":"trier","invite":"Choisis une atteinte.","items":[["Intégrité physique","coups, blessures, viol, mutilations."],["Intégrité morale","injures, diffamation, harcèlement."],["Patrimoine","vol, escroquerie, destruction de biens."]]}},{"t":"Les atteintes au patrimoine","html":"<p>Elles visent les biens d'une personne ou de la collectivité : vol, escroquerie, abus de confiance, destruction de biens, détournement de biens publics, incendie volontaire.</p><p><strong>Conduite à tenir</strong> : protéger la victime, alerter (police 117, gendarmerie, sapeurs-pompiers 118), conserver les preuves, porter plainte.</p><div class='attention'><b>Attention</b>la vengeance personnelle et la « justice populaire » sont elles-mêmes des infractions.</div>"},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Question de cours.</strong> Les coups et blessures sont une atteinte à l'intégrité :</p><ol type='a'><li>physique</li><li>morale</li><li>patrimoniale</li><li>électorale</li></ol><details><summary>Voir la réponse</summary><p><strong>physique</strong>. Ils blessent le corps.</p></details><p><strong>Exercice.</strong></p><p>Un élève publie des moqueries répétées sur un camarade dans un groupe de classe. Quelle atteinte commet-il ?</p><details><summary>Voir la réponse</summary><p>(Réponse : une atteinte à l'intégrité morale, par cyberharcèlement.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Dans un quartier de Douala, un élève est frappé et filmé par des camarades ; la vidéo est partagée avec des moqueries ; son téléphone lui est volé.</p><p><strong>Consigne 1.</strong> Identifie les trois types d'atteintes.</p><p><strong>Consigne 2.</strong> Indique la conduite à tenir pour un témoin.</p><details><summary>Voir une réponse attendue</summary><p>Physique (coups), morale (vidéo humiliante, moqueries), patrimoine (vol du téléphone). Le témoin protège la victime, alerte un adulte ou la police, ne partage pas la vidéo et témoigne.</p></details></div>","retenir":"Savoir-être mobilisé : Sens de la responsabilité."}],"revision":["Physique : coups, blessures, viol, mutilations.","Morale : injures, diffamation, harcèlement, discrimination.","Patrimoine : vol, escroquerie, destruction, détournement ; alerter, preuves, plainte."],"exo":"<p>Un élève publie des moqueries répétées sur un camarade dans un groupe de classe. Quelle atteinte commet-il ? <em>(Réponse : une atteinte à l'intégrité morale, par cyberharcèlement.)</em></p>","quiz":[{"q":"Les coups et blessures sont une atteinte à l'intégrité :","r":["physique","morale","patrimoniale","électorale"],"b":0,"e":"Ils blessent le corps."},{"q":"L'injure est une atteinte à l'intégrité :","r":["physique","morale","au patrimoine","territoriale"],"b":1,"e":"Elle blesse la dignité."},{"q":"Le vol est une atteinte :","r":["à l'intégrité physique","à l'intégrité morale seulement","au patrimoine","au droit de vote"],"b":2,"e":"Il vise les biens."},{"q":"Le Code pénal camerounais en vigueur date du :","r":["19 décembre 1990","14 août 1992","18 janvier 1996","12 juillet 2016"],"b":3,"e":"Loi n° 2016/007 du 12 juillet 2016."},{"q":"Le cyberharcèlement est une atteinte à l'intégrité :","r":["morale","patrimoniale","physique","territoriale"],"b":0,"e":"Les mots en ligne peuvent blesser."},{"q":"L'escroquerie consiste à :","r":["frapper une personne pour lui faire peur","obtenir un bien par la tromperie","insulter un voisin","voter deux fois"],"b":1,"e":"C'est une atteinte au patrimoine."},{"q":"Le numéro de la police au Cameroun est :","r":["118","119","117","112"],"b":2,"e":"Le 118 est celui des sapeurs-pompiers."},{"q":"La « justice populaire » est :","r":["une forme légale de justice","recommandée par la loi","un droit des victimes","elle-même une infraction"],"b":3,"e":"Seule la justice officielle peut juger."},{"q":"Les mutilations génitales féminines sont une atteinte :","r":["à l'intégrité physique","au patrimoine","à la liberté de la presse","au droit de vote"],"b":0,"e":"Elles blessent gravement le corps."},{"q":"Face à une agression, il faut d'abord :","r":["filmer la scène pour les réseaux","protéger la victime et alerter","se venger de l'agresseur","fuir sans rien dire"],"b":1,"e":"Protéger, alerter, témoigner."}],"c":"1re C","m":"ecm","rang":10,"apc":{"module":"Les formes de violences","famille":"Paix et sécurité","agir":"Prévenir et combattre les violences et l'extrémisme violent","situation":"Au marché de Mbouda, un voleur présumé est rattrapé par la foule qui commence à le frapper ; un commerçant crie de le brûler. Tu es présent avec ton grand frère.","tache":"Identifie les atteintes commises dans cette scène et décris la conduite responsable à tenir."},"gratuit":true});
VRT_L("1re-c-ecm-r11",{"duree":20,"titre":"L'extrémisme violent","accroche":"Quand les idées deviennent des armes.","intro":"L'extrémisme violent menace la paix au Cameroun, notamment avec les attaques de Boko Haram dans l'Extrême-Nord et les violences armées dans les régions du Nord-Ouest et du Sud-Ouest.","objectifs":["définir l'extrémisme violent","identifier ses causes et ses manifestations","connaître les signes de radicalisation"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>L'<strong>extrémisme violent</strong> est l'attitude de personnes ou de groupes qui adoptent des idées extrêmes (religieuses, politiques, ethniques) et utilisent la violence pour les imposer.</div><p>Le <strong>terrorisme</strong> en est une forme : il vise à semer la terreur dans la population par des attentats, des enlèvements ou des massacres.</p>"},{"t":"Causes et manifestations","verrou":true},{"t":"Les signes de radicalisation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"ecm","rang":11,"apc":{"module":"Les formes de violences","famille":"Paix et sécurité","agir":"Prévenir et combattre les violences et l'extrémisme violent","situation":"Ton cousin de 17 ans, à Kousséri, a quitté l'école, ne parle plus à sa famille, passe ses nuits à regarder des vidéos de combattants et répète qu'« un vrai homme doit prendre les armes ».","tache":"Identifie trois signes de radicalisation et propose une démarche pour l'aider."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-ecm-r12",{"duree":20,"titre":"La notion de paix","accroche":"Plus que l'absence de guerre.","intro":"La paix est un bien précieux que le Cameroun a appris à mesurer face aux crises. Elle ne se réduit pas à l'absence de combats : elle suppose la justice, le respect et la sécurité de tous.","objectifs":["définir la paix","distinguer paix négative et paix positive","identifier les facteurs de paix"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>paix</strong> est l'état d'une société ou de relations entre États où règnent la sécurité, la concorde et le respect mutuel, sans violence ni conflit armé.</div><p>On distingue la <strong>paix négative</strong> (absence de guerre) et la <strong>paix positive</strong> (présence de justice, de droits respectés et de bonnes relations).</p>"},{"t":"Les niveaux de la paix","verrou":true},{"t":"Les facteurs de paix","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"ecm","rang":12,"apc":{"module":"La notion de paix","famille":"Paix et sécurité","agir":"Promouvoir la paix et le vivre ensemble","situation":"Dans ton quartier de Yaoundé, aucune bagarre n'a eu lieu depuis un an, mais les familles de deux communautés ne se parlent plus et refusent les mariages mixtes.","tache":"Explique pourquoi cette situation n'est pas une paix véritable et propose deux actions pour construire une paix positive."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-ecm-r13",{"duree":20,"titre":"TD : les symboles de la paix au Cameroun","accroche":"Enquête sur les signes qui unissent.","intro":"Chaque culture camerounaise possède des signes, objets et rites qui expriment la paix et la réconciliation. Ce travail dirigé les fait découvrir par l'enquête.","objectifs":["recenser des symboles de paix","en expliquer la signification","présenter les résultats d'une enquête"],"parties":[{"t":"Les symboles universels","html":"<div class='def'><b>Définition</b>Un <strong>symbole de paix</strong> est un objet, une image, un geste ou un rite qui représente la paix et la réconciliation dans une culture.</div><ul><li>la <strong>colombe</strong> portant un rameau d'olivier ;</li><li>le <strong>drapeau blanc</strong> ;</li><li>la <strong>poignée de main</strong> et l'accolade ;</li><li>le <strong>flambeau</strong> de la paix.</li></ul>"},{"t":"Des symboles camerounais","verrou":true},{"t":"Mener l'enquête","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"ecm","rang":13,"apc":{"module":"La notion de paix","famille":"Paix et sécurité","agir":"Promouvoir la paix et le vivre ensemble","situation":"Ta classe de 1re prépare une exposition sur les symboles de la paix pour la Journée internationale de la paix. Les élèves viennent de cinq régions différentes.","tache":"Propose un plan d'enquête en quatre étapes et un tableau à trois colonnes pour présenter les résultats."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-ecm-r14",{"duree":20,"titre":"Les stratégies de promotion de la paix","accroche":"Construire la paix au quotidien.","intro":"La paix se prépare et s'entretient. Les États, les communautés et chaque citoyen disposent de stratégies pour prévenir les conflits et renforcer la cohésion.","objectifs":["citer des stratégies de promotion de la paix","identifier les acteurs","proposer des actions à son niveau"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une <strong>stratégie de promotion de la paix</strong> est un ensemble d'actions organisées pour prévenir les conflits, réduire les tensions et renforcer la cohésion sociale.</div>"},{"t":"Les stratégies","verrou":true},{"t":"Les acteurs et le rôle du jeune","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"ecm","rang":14,"apc":{"module":"La notion de paix","famille":"Paix et sécurité","agir":"Promouvoir la paix et le vivre ensemble","situation":"Dans ton lycée, des bagarres opposent régulièrement les élèves de deux quartiers rivaux ; trois blessés ont été recensés depuis la rentrée et des insultes circulent sur un groupe en ligne.","tache":"Propose une stratégie de paix en trois actions, en précisant pour chacune les acteurs mobilisés."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-ecm-r15",{"duree":20,"titre":"Le règlement pacifique des différends","accroche":"Résoudre les conflits sans violence.","intro":"Un différend peut opposer deux personnes, deux communautés ou deux États. Il existe des moyens pacifiques de le régler, du dialogue jusqu'au juge international. L'affaire de Bakassi en est un exemple célèbre.","objectifs":["définir un différend","citer les modes de règlement pacifique","analyser l'exemple de Bakassi"],"parties":[{"t":"Différend et modes de règlement","html":"<div class='def'><b>Définition</b>Un <strong>différend</strong> est un désaccord sur un droit, un intérêt ou un fait entre deux ou plusieurs parties. Son <strong>règlement pacifique</strong> consiste à y mettre fin sans recourir à la force.</div><ul><li><strong>la négociation</strong> : discussion directe entre les parties ;</li><li><strong>les bons offices et la médiation</strong> : un tiers rapproche les parties et propose une solution ;</li><li><strong>la conciliation</strong> : une commission examine et propose ;</li><li><strong>l'arbitrage</strong> : des arbitres choisis rendent une décision obligatoire ;</li><li><strong>le règlement judiciaire</strong> : un tribunal, comme la Cour internationale de justice, tranche.</li></ul>"},{"t":"L'exemple de Bakassi","verrou":true},{"t":"À l'échelle de chacun","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"ecm","rang":15,"apc":{"module":"La notion de paix","famille":"Paix et sécurité","agir":"Promouvoir la paix et le vivre ensemble","situation":"Deux familles de Foumban se disputent une parcelle de 2 hectares héritée d'un ancêtre commun ; les jeunes des deux familles ont déjà échangé des menaces et des coups de machette ont été évités de justesse.","tache":"Propose, dans l'ordre, trois modes de règlement pacifique adaptés à ce différend et justifie leur choix."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-ecm-r16",{"duree":20,"titre":"Dossier : la lutte contre l'extrémisme violent au Cameroun","accroche":"Défendre, prévenir, réintégrer.","intro":"Face à Boko Haram et aux groupes armés, le Cameroun combine une réponse sécuritaire, judiciaire, sociale et éducative. Ce dossier analyse cette lutte et la place des citoyens.","objectifs":["présenter les moyens de lutte contre l'extrémisme violent","analyser leurs résultats et leurs limites","proposer des actions citoyennes"],"parties":[{"t":"Les réponses sécuritaire et judiciaire","html":"<div class='def'><b>Définition</b>La <strong>lutte contre l'extrémisme violent</strong> est l'ensemble des actions qui visent à prévenir la radicalisation, à protéger les populations et à neutraliser les groupes violents.</div><ul><li>engagement des forces de défense et de sécurité, dont la Force multinationale mixte du bassin du lac Tchad avec les pays voisins ;</li><li>comités de vigilance des populations dans l'Extrême-Nord ;</li><li>loi du 23 décembre 2014 contre le terrorisme.</li></ul>"},{"t":"Les réponses sociales et éducatives","verrou":true},{"t":"Résultats, limites et rôle du citoyen","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"ecm","rang":16,"apc":{"module":"Les formes de violences","famille":"Paix et sécurité","agir":"Prévenir et combattre les violences et l'extrémisme violent","situation":"Dans un village du Mayo-Sava, l'école a rouvert après trois ans de fermeture due aux attaques ; 40 % des élèves sont des enfants déplacés et plusieurs jeunes du village ont rejoint autrefois un groupe armé avant de se rendre.","tache":"Analyse deux défis de ce village et propose trois actions complémentaires pour éviter le retour de l'extrémisme violent."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-ecm-r17",{"duree":20,"titre":"L'importance du vivre ensemble au Cameroun","accroche":"Plus de deux cents ethnies, une seule nation.","intro":"Le Cameroun est souvent présenté comme « l'Afrique en miniature » pour la diversité de ses peuples, de ses langues, de ses religions et de ses paysages. Vivre ensemble est la condition de sa stabilité et de son développement.","objectifs":["définir le vivre ensemble","identifier les éléments de la diversité camerounaise","expliquer l'importance du vivre ensemble"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>vivre ensemble</strong> est la capacité de personnes et de communautés différentes à partager pacifiquement un même espace, dans le respect mutuel, l'égalité des droits et la solidarité.</div>"},{"t":"La diversité camerounaise","verrou":true},{"t":"Pourquoi vivre ensemble ?","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"ecm","rang":17,"apc":{"module":"La notion de paix","famille":"Paix et sécurité","agir":"Promouvoir la paix et le vivre ensemble","situation":"Lors de l'élection du délégué de ta classe à Buea, un candidat déclare : « ne votez pas pour lui, il n'est pas de chez nous ». La classe compte des élèves de six régions et deux sous-systèmes.","tache":"Montre en quoi ce discours menace le vivre ensemble et rédige un appel de six lignes pour une campagne fondée sur les idées."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-ecm-r18",{"duree":20,"titre":"Dossier : la Commission nationale pour la promotion du bilinguisme et du multiculturalisme","accroche":"Une institution au service de l'unité.","intro":"Créée par décret du 23 janvier 2017, la Commission nationale pour la promotion du bilinguisme et du multiculturalisme (CNPBM) veille à l'égalité du français et de l'anglais et à la promotion de la diversité culturelle.","objectifs":["présenter la CNPBM","expliquer ses missions","évaluer son action et le rôle du citoyen"],"parties":[{"t":"Présentation","html":"<div class='def'><b>Définition</b>La <strong>CNPBM</strong> est un organe consultatif, placé auprès du président de la République, chargé de promouvoir le bilinguisme officiel (français et anglais) et le multiculturalisme au Cameroun.</div><p>Elle a été créée dans un contexte de tensions dans les régions du Nord-Ouest et du Sud-Ouest, où une partie de la population dénonçait une marginalisation de l'anglais et du sous-système anglophone.</p>"},{"t":"Les missions","verrou":true},{"t":"Évaluation et rôle du citoyen","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"ecm","rang":18,"apc":{"module":"La notion de paix","famille":"Paix et sécurité","agir":"Promouvoir la paix et le vivre ensemble","situation":"Un élève anglophone muté de Limbé à Ngaoundéré reçoit tous ses documents administratifs en français seulement et se fait moquer pour son accent ; il envisage d'abandonner l'école.","tache":"Explique en quoi ses droits et le vivre ensemble sont atteints, et indique deux actions possibles, dont une auprès de la CNPBM."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r01",{"duree":20,"titre":"L'IA dans les métiers et les filières professionnelles","accroche":"L'IA transforme le travail.","intro":"L'intelligence artificielle s'invite dans presque tous les métiers. Connaître ses usages professionnels aide à choisir sa filière et à se préparer.","objectifs":["citer des usages professionnels de l'IA","identifier les compétences nouvelles","mesurer les effets de l'IA sur l'emploi"],"parties":[{"t":"L'IA au travail","html":"<div class='def'><b>Définition</b>Une <strong>application professionnelle de l'IA</strong> est l'usage d'un système d'intelligence artificielle pour accomplir ou faciliter une tâche de travail : analyser, rédiger, diagnostiquer, prévoir, automatiser.</div><ul><li><strong>santé</strong> : aide au diagnostic sur images ;</li><li><strong>droit et administration</strong> : recherche et résumé de textes ;</li><li><strong>agriculture</strong> : prévision des récoltes, détection des maladies ;</li><li><strong>banque</strong> : détection des fraudes, analyse du risque de crédit ;</li><li><strong>communication</strong> : rédaction, traduction, création d'images.</li></ul>"},{"t":"Effets sur l'emploi","html":"<p>L'IA automatise des tâches répétitives, transforme des métiers et en crée de nouveaux (analyste de données, ingénieur en IA, spécialiste de l'éthique des données). Les compétences clés deviennent : esprit critique, maîtrise des outils numériques, créativité, communication.</p>","retenir":"Automatiser, transformer, créer des métiers.","labo":{"type":"trier","invite":"Choisis un secteur.","items":[["Santé","aide au diagnostic sur images."],["Banque","détection des fraudes et du risque."],["Agriculture","prévision des récoltes."],["Communication","rédaction et traduction assistées."]]}},{"t":"Se préparer","html":"<p>Quelle que soit la filière, l'élève a intérêt à maîtriser les outils, à apprendre à vérifier les résultats d'une IA et à développer les compétences humaines que la machine remplace mal : relation, jugement, sens éthique.</p><div class='attention'><b>Attention</b>l'IA ne supprime pas la responsabilité du professionnel : c'est lui qui répond de la décision.</div>"},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Question de cours.</strong> Dans un cabinet médical, l'IA peut servir à :</p><ol type='a'><li>signer les ordonnances à la place du médecin</li><li>remplacer définitivement tous les infirmiers</li><li>décider seule des traitements sans aucun contrôle</li><li>analyser des radiographies</li></ol><details><summary>Voir la réponse</summary><p><strong>analyser des radiographies</strong>. Elle aide au diagnostic ; le médecin décide.</p></details><p><strong>Exercice.</strong></p><p>Cite un nouveau métier lié à l'IA.</p><details><summary>Voir la réponse</summary><p>(Réponse : analyste de données ou ingénieur en intelligence artificielle.)</p></details></div>","retenir":"Savoir-être mobilisé : Esprit critique."}],"revision":["Usages : santé, droit, agriculture, banque, communication.","Effets : automatisation, transformation, nouveaux métiers.","Compétences : esprit critique, outils, créativité, éthique."],"exo":"<p>Cite un nouveau métier lié à l'IA. <em>(Réponse : analyste de données ou ingénieur en intelligence artificielle.)</em></p>","quiz":[{"q":"Dans un cabinet médical, l'IA peut servir à :","r":["signer les ordonnances à la place du médecin","remplacer définitivement tous les infirmiers","décider seule des traitements sans aucun contrôle","analyser des radiographies"],"b":3,"e":"Elle aide au diagnostic ; le médecin décide."},{"q":"L'automatisation par l'IA touche surtout :","r":["les tâches répétitives","les décisions éthiques les plus délicates","les métiers qui demandent de l'empathie","les relations humaines entre collègues"],"b":0,"e":"Saisie, tri, classement, réponses standard."},{"q":"Un métier né avec l'IA est :","r":["porteur d'eau dans les quartiers anciens","ingénieur en données","conducteur de calèche dans les grandes villes","allumeur de réverbères à huile"],"b":1,"e":"Collecte, préparation et analyse des données."},{"q":"Dans le domaine juridique, l'IA peut :","r":["rendre seule les jugements à la place du juge et des avocats","voter les lois à la place des parlementaires","rechercher rapidement des textes et des décisions","arrêter les suspects dans la rue sans policier"],"b":2,"e":"Elle facilite la recherche documentaire."},{"q":"Une compétence essentielle face à l'IA est :","r":["la capacité à tout recopier sans lire","la mémorisation des mots de passe d'autrui","l'utilisation exclusive du papier et du crayon","l'esprit critique"],"b":3,"e":"Il faut juger la qualité des réponses."},{"q":"En agriculture, des drones avec IA permettent :","r":["de surveiller l'état des cultures","de remplacer totalement la pluie et le soleil","de supprimer le besoin de semences de qualité","de récolter sans aucune intervention humaine"],"b":0,"e":"Ils repèrent maladies et manque d'eau."},{"q":"Dans la banque, l'IA sert notamment à :","r":["imprimer elle-même la monnaie nationale","évaluer les risques de crédit","fixer seule le taux directeur de la BEAC","fermer les agences les jours de marché"],"b":1,"e":"Elle analyse l'historique des clients."},{"q":"En communication, l'IA générative aide à :","r":["garantir que toutes les publicités sont vraies et honnêtes","remplacer la loi sur la protection des données","produire des premières versions de textes et de visuels","interdire la publication de toute fausse information"],"b":2,"e":"Le professionnel relit et corrige."},{"q":"L'IA transforme un métier quand :","r":["elle supprime toutes les compétences humaines nécessaires","elle interdit l'usage de l'ordinateur au bureau","elle rend le diplôme inutile pour tous les postes","elle modifie la manière d'exécuter les tâches"],"b":3,"e":"Le métier évolue sans disparaître."},{"q":"Pour se préparer aux métiers de demain, il faut :","r":["apprendre à utiliser les outils d'IA avec éthique","éviter tout contact avec les outils numériques modernes","attendre que l'IA choisisse sa filière à sa place","abandonner les mathématiques et le français à l'école"],"b":0,"e":"Outils, créativité et éthique se complètent."}],"c":"1re C","m":"info","rang":1,"apc":{"module":"Intelligence artificielle appliquée et enjeux professionnels","famille":"Environnement numérique","agir":"Utiliser l'IA de façon responsable dans un projet","situation":"Ta cousine, comptable dans une PME de Douala, craint que « l'IA lui prenne son travail » depuis qu'un logiciel saisit automatiquement les factures.","tache":"Montre-lui comment son métier se transforme plutôt qu'il ne disparaît, et propose deux compétences à développer."},"gratuit":true});
VRT_L("1re-c-info-r02",{"duree":20,"titre":"Réalisation d'un projet scolaire assisté par l'IA","accroche":"Travailler avec l'IA, pas la laisser travailler.","intro":"L'IA peut aider à mener un projet scolaire, à condition de garder la maîtrise de chaque étape et de vérifier ce qu'elle produit.","objectifs":["planifier un projet scolaire","utiliser l'IA à chaque étape de façon pertinente","vérifier et déclarer l'usage de l'IA"],"parties":[{"t":"Le projet et l'IA","html":"<div class='def'><b>Définition</b>Un <strong>projet assisté par l'IA</strong> est un travail mené par l'élève dans lequel l'IA intervient comme outil d'aide (idées, plan, explications, relecture), sous son contrôle.</div>"},{"t":"Les étapes","verrou":true},{"t":"Bonnes pratiques","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":2,"apc":{"module":"Intelligence artificielle appliquée et enjeux professionnels","famille":"Environnement numérique","agir":"Utiliser l'IA de façon responsable dans un projet","situation":"Ton groupe de quatre élèves doit réaliser en trois semaines un dossier sur le traitement des déchets plastiques à Yaoundé ; un membre propose de « tout demander à l'IA la veille ».","tache":"Propose un plan de travail en cinq étapes où l'IA intervient de façon pertinente, en précisant à chaque étape ce qui reste à la charge du groupe."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r03",{"duree":20,"titre":"Cadre juridique et protection des données face à l'IA","accroche":"Nos données nourrissent l'IA.","intro":"Les systèmes d'IA utilisent d'énormes quantités de données, dont des données personnelles. La loi encadre leur collecte et leur usage.","objectifs":["définir une donnée personnelle","connaître le cadre juridique camerounais et international","protéger ses données face aux outils d'IA"],"parties":[{"t":"Données personnelles","html":"<div class='def'><b>Définition</b>Une <strong>donnée personnelle</strong> est toute information qui permet d'identifier une personne directement ou indirectement : nom, numéro de téléphone, photo, voix, adresse, localisation, numéro de compte.</div><p>Certaines sont dites <strong>sensibles</strong> : santé, religion, opinions politiques, données biométriques.</p>"},{"t":"Le cadre juridique","verrou":true},{"t":"Se protéger","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":3,"apc":{"module":"Intelligence artificielle appliquée et enjeux professionnels","famille":"Environnement numérique","agir":"Utiliser l'IA de façon responsable dans un projet","situation":"Pour « faire rire la classe », un élève veut fournir à une application d'IA la photo et des enregistrements vocaux de son professeur afin de produire une fausse vidéo.","tache":"Identifie les données personnelles en jeu, les règles violées et les risques pour l'élève."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r04",{"duree":20,"titre":"Biais algorithmiques et équité de l'IA","accroche":"Une IA peut être injuste.","intro":"Une IA apprend à partir de données produites par des humains. Si ces données sont déséquilibrées, ses décisions peuvent être injustes envers certains groupes.","objectifs":["définir un biais algorithmique","en identifier les causes","proposer des moyens de réduire les biais"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Un <strong>biais algorithmique</strong> est une erreur systématique d'une IA qui la conduit à traiter de façon injuste ou défavorable certaines personnes ou certains groupes.</div><p>Exemples : reconnaissance faciale moins précise sur les peaux foncées parce que les données d'entraînement contenaient surtout des visages clairs ; outil de recrutement qui défavorise les femmes parce qu'il a appris sur des recrutements passés.</p>"},{"t":"Les causes","verrou":true},{"t":"Vers une IA équitable","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":4,"apc":{"module":"Intelligence artificielle appliquée et enjeux professionnels","famille":"Environnement numérique","agir":"Utiliser l'IA de façon responsable dans un projet","situation":"Une banque teste une IA d'octroi de crédit : sur 1 000 dossiers, elle accepte 62 % des demandes d'hommes et 31 % des demandes de femmes au profil financier comparable.","tache":"Montre qu'il s'agit d'un biais, explique sa cause probable et propose trois mesures."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r05",{"duree":20,"titre":"Écriture des algorithmes simples","accroche":"Rappels de base de l'algorithmique.","intro":"Cette leçon révise la structure d'un algorithme, les types de données et les instructions de base avant d'aborder les itérations.","objectifs":["écrire un algorithme complet","utiliser les types et opérateurs","exécuter une trace"],"parties":[{"t":"Rappels","html":"<div class='def'><b>Définition</b>Un <strong>algorithme</strong> est une suite finie et ordonnée d'instructions non ambiguës qui résout un problème. Il comporte un en-tête, une partie déclarative (constantes, variables typées) et un corps (Début ... Fin).</div><p>Types : entier, réel, caractère, chaîne, booléen. Opérateurs : +, −, *, /, div (division entière), mod (reste), comparaisons, ET, OU, NON.</p>"},{"t":"Exemple","verrou":true},{"t":"La trace","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":5,"apc":{"module":"Algorithmique : itérations, tableaux et sous-algorithmes","famille":"Algorithmique et programmation","agir":"Résoudre un problème par un algorithme structuré","situation":"Un commerçant veut convertir une durée donnée en secondes en heures, minutes et secondes (par exemple 7 384 s).","tache":"Écris l'algorithme utilisant div et mod, puis fais sa trace pour 7 384 s."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r06",{"duree":20,"titre":"Les structures itératives","accroche":"Répéter efficacement.","intro":"Les boucles permettent de répéter un traitement sans réécrire les instructions. On distingue Pour, Tant que et Répéter ... Jusqu'à.","objectifs":["écrire les trois boucles","choisir la boucle adaptée","éviter les boucles infinies"],"parties":[{"t":"Les trois boucles","html":"<div class='def'><b>Définition</b>Une <strong>structure itérative</strong> (boucle) répète un bloc d'instructions un certain nombre de fois ou tant qu'une condition est remplie.</div><pre>Pour i ← 1 à n Faire ... FinPour\nTant que condition Faire ... FinTantque\nRépéter ... Jusqu'à condition</pre>"},{"t":"Choisir","verrou":true},{"t":"Exemple : somme de 1 à n","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":6,"apc":{"module":"Algorithmique : itérations, tableaux et sous-algorithmes","famille":"Algorithmique et programmation","agir":"Résoudre un problème par un algorithme structuré","situation":"Une épargnante place 100 000 F sur un compte à 5 % d'intérêts par an (intérêts composés) et veut savoir au bout de combien d'années elle aura au moins 150 000 F.","tache":"Écris l'algorithme avec une boucle Tant que et donne le résultat attendu."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r07",{"duree":20,"titre":"Les structures de données","accroche":"Ranger plusieurs valeurs sous un même nom.","intro":"Pour traiter les notes de 40 élèves, déclarer 40 variables serait absurde. On utilise des structures de données comme les tableaux et les enregistrements.","objectifs":["définir une structure de données","déclarer un tableau","déclarer un enregistrement"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une <strong>structure de données</strong> est une manière d'organiser plusieurs données en mémoire pour les manipuler facilement. Un <strong>tableau</strong> regroupe un nombre fixe d'éléments de même type, repérés par un <strong>indice</strong>.</div>"},{"t":"Les tableaux","verrou":true},{"t":"Les enregistrements","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":7,"apc":{"module":"Algorithmique : itérations, tableaux et sous-algorithmes","famille":"Algorithmique et programmation","agir":"Résoudre un problème par un algorithme structuré","situation":"La bibliothèque du lycée veut gérer 500 livres, chacun ayant un titre, un auteur, une année et un état (disponible ou emprunté).","tache":"Propose une structure de données adaptée en déclarant le type et la variable nécessaires."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r08",{"duree":20,"titre":"Opérations sur les tableaux","accroche":"Remplir, parcourir, calculer.","intro":"Les tableaux se manipulent presque toujours avec des boucles : saisie, affichage, somme, recherche du maximum, comptage.","objectifs":["remplir et afficher un tableau","calculer somme et moyenne","rechercher le maximum et compter des éléments"],"parties":[{"t":"Remplir et afficher","html":"<div class='def'><b>Définition</b><strong>Parcourir un tableau</strong>, c'est accéder successivement à chacun de ses éléments, généralement avec une boucle Pour de l'indice de début à l'indice de fin.</div><pre>Pour i ← 1 à n Faire\n   Lire(T[i])\nFinPour</pre>"},{"t":"Somme, moyenne, maximum","verrou":true},{"t":"Compter et décaler","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":8,"apc":{"module":"Algorithmique : itérations, tableaux et sous-algorithmes","famille":"Algorithmique et programmation","agir":"Résoudre un problème par un algorithme structuré","situation":"Les températures maximales de Garoua pendant 7 jours sont relevées dans un tableau : 38, 41, 40, 43, 39, 42, 37.","tache":"Écris l'algorithme qui calcule la moyenne, la température maximale et le nombre de jours à plus de 40 °C, puis donne les résultats."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r09",{"duree":20,"titre":"Exécution d'un algorithme utilisant les tableaux","accroche":"Suivre pas à pas un traitement de tableau.","intro":"Pour vérifier un algorithme sur un tableau, on fait une trace qui suit l'indice et le contenu des cases.","objectifs":["construire une trace avec un tableau","détecter une erreur par la trace","exécuter un algorithme d'inversion"],"parties":[{"t":"La trace d'un tableau","html":"<div class='def'><b>Définition</b><strong>Exécuter un algorithme à la main</strong>, c'est simuler son fonctionnement en notant, à chaque étape, la valeur des variables et le contenu du tableau.</div>"},{"t":"Exemple : inverser un tableau","verrou":true},{"t":"Détecter les erreurs","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":9,"apc":{"module":"Algorithmique : itérations, tableaux et sous-algorithmes","famille":"Algorithmique et programmation","agir":"Résoudre un problème par un algorithme structuré","situation":"Un camarade a écrit : Pour i ← 1 à 4 Faire T[i] ← T[i + 1] FinPour, pour décaler vers la gauche le tableau T = [4 ; 6 ; 8 ; 10 ; 12].","tache":"Fais la trace de cet algorithme et donne le contenu final de T, puis explique ce qu'il fait."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r10",{"duree":20,"titre":"Fonctions et procédures","accroche":"Découper un problème en sous-problèmes.","intro":"Un long algorithme devient lisible quand on le découpe en sous-algorithmes réutilisables : les fonctions et les procédures.","objectifs":["distinguer fonction et procédure","déclarer et appeler un sous-algorithme","expliquer l'intérêt de la modularité"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>Un <strong>sous-algorithme</strong> est un bloc d'instructions nommé, appelé depuis l'algorithme principal. Une <strong>fonction</strong> renvoie une valeur ; une <strong>procédure</strong> exécute une action sans renvoyer de valeur.</div>"},{"t":"Syntaxe","verrou":true},{"t":"Intérêts","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":10,"apc":{"module":"Algorithmique : itérations, tableaux et sous-algorithmes","famille":"Algorithmique et programmation","agir":"Résoudre un problème par un algorithme structuré","situation":"Un programme de gestion de notes doit calculer plusieurs fois la moyenne de trois notes avec coefficients et afficher une appréciation (« Bien » à partir de 14, « Passable » de 10 à 14, « Insuffisant » sinon).","tache":"Écris une fonction de moyenne et une procédure d'appréciation, puis montre comment les appeler."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r11",{"duree":20,"titre":"Modes de passage des paramètres","accroche":"Par valeur ou par adresse.","intro":"Quand on appelle un sous-algorithme, ses paramètres peuvent recevoir une copie de la valeur ou désigner directement la variable d'origine.","objectifs":["distinguer paramètres formels et effectifs","distinguer passage par valeur et par référence","choisir le mode adapté"],"parties":[{"t":"Paramètres","html":"<div class='def'><b>Définition</b>Les <strong>paramètres formels</strong> sont ceux écrits dans la déclaration du sous-algorithme ; les <strong>paramètres effectifs</strong> sont les valeurs ou variables fournies lors de l'appel.</div>"},{"t":"Les deux modes","verrou":true},{"t":"Choisir","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":11,"apc":{"module":"Algorithmique : itérations, tableaux et sous-algorithmes","famille":"Algorithmique et programmation","agir":"Résoudre un problème par un algorithme structuré","situation":"Une procédure Augmenter(p : entier) contient p ← p + 500. Dans l'algorithme principal, prix ← 2000 puis Augmenter(prix) ; Écrire(prix).","tache":"Indique la valeur affichée et explique-la, puis corrige la procédure pour que le prix soit réellement augmenté."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r12",{"duree":20,"titre":"Exécution d'un algorithme intégrant fonctions et procédures","accroche":"Suivre les appels.","intro":"Exécuter à la main un algorithme qui appelle des sous-algorithmes demande de suivre le passage des paramètres et le retour des valeurs.","objectifs":["tracer un appel de fonction","suivre les variables locales","vérifier le passage des paramètres"],"parties":[{"t":"La pile d'appels","html":"<div class='def'><b>Définition</b>Lors d'un <strong>appel</strong>, l'exécution passe au sous-algorithme avec ses paramètres ; à la fin, elle revient à l'instruction qui suit l'appel, avec la valeur renvoyée pour une fonction.</div>"},{"t":"Exemple","verrou":true},{"t":"Méthode de trace","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":12,"apc":{"module":"Algorithmique : itérations, tableaux et sous-algorithmes","famille":"Algorithmique et programmation","agir":"Résoudre un problème par un algorithme structuré","situation":"Fonction F(n : entier) : entier ; Début : Si n mod 2 = 0 Alors Retourner n div 2 Sinon Retourner 3 * n + 1 FinSi ; FinFonction. L'algorithme principal part de x ← 6 et applique x ← F(x) jusqu'à obtenir 1, en comptant les étapes.","tache":"Fais la trace complète et donne le nombre d'étapes."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r13",{"duree":20,"titre":"Installation d'un compilateur","accroche":"Préparer son poste pour programmer en C.","intro":"Pour programmer en C, il faut un compilateur qui traduit le code source en programme exécutable, souvent intégré à un environnement de développement.","objectifs":["définir compilateur et environnement de développement","installer un compilateur C","compiler un premier programme"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>Un <strong>compilateur</strong> traduit un programme écrit dans un langage de haut niveau (C) en langage machine exécutable. Un <strong>environnement de développement intégré</strong> (EDI) réunit un éditeur, un compilateur et un débogueur (Code::Blocks, Dev-C++, Visual Studio Code avec GCC).</div>"},{"t":"Installer","html":"<ol><li>Télécharger un EDI depuis son site officiel, de préférence avec le compilateur inclus (par exemple Code::Blocks avec MinGW/GCC).</li><li>Lancer l'installation et accepter les options par défaut.</li><li>Vérifier que l'EDI détecte le compilateur dans ses réglages.</li><li>Créer un projet « Console application » en C.</li></ol>","retenir":"Éditeur + compilateur + débogueur = EDI.","labo":{"type":"etapes","items":[["Télécharger","EDI avec compilateur."],["Installer","options par défaut."],["Vérifier","compilateur détecté."],["Créer","un projet console."],["Compiler et exécuter","Build and run."]]}},{"t":"Premier programme","html":"<pre>#include &lt;stdio.h&gt;\nint main(void)\n{\n   printf(\"Bonjour le Cameroun !\\n\");\n   return 0;\n}</pre><p>Compiler puis exécuter (« Build and run ») : la console affiche le message. Les étapes de la compilation : prétraitement, compilation, édition des liens.</p><div class='attention'><b>Attention</b>un message d'erreur de compilation indique la ligne : on lit le premier message en priorité.</div>"},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Question de cours.</strong> Un compilateur transforme :</p><ol type='a'><li>le code source en programme exécutable</li><li>un programme exécutable en image affichable</li><li>un texte en fichier audio</li><li>un tableur en base de données</li></ol><details><summary>Voir la réponse</summary><p><strong>le code source en programme exécutable</strong>. Langage C → exécutable.</p></details><p><strong>Exercice.</strong></p><p>Quel fichier d'en-tête faut-il inclure pour utiliser printf ?</p><details><summary>Voir la réponse</summary><p>(Réponse : stdio.h.)</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur et méthode."}],"revision":["Compilateur : source → exécutable.","EDI : éditeur, compilateur, débogueur (Code::Blocks, GCC).","Premier programme : include, main, printf, return 0."],"exo":"<p>Quel fichier d'en-tête faut-il inclure pour utiliser printf ? <em>(Réponse : stdio.h.)</em></p>","quiz":[{"q":"Un compilateur transforme :","r":["le code source en programme exécutable","un programme exécutable en image affichable","un texte en fichier audio","un tableur en base de données"],"b":0,"e":"Langage C → exécutable."},{"q":"Code::Blocks est :","r":["un système d'exploitation libre pour les serveurs","un environnement de développement intégré","un tableur en ligne","un antivirus gratuit"],"b":1,"e":"EDI : éditeur, compilateur, débogueur."},{"q":"GCC est :","r":["un navigateur web","un logiciel de dessin","un compilateur C","un traitement de texte"],"b":2,"e":"GNU Compiler Collection."},{"q":"Un EDI regroupe notamment :","r":["un clavier, une souris et un écran","un tableur, un traitement de texte et un antivirus","une imprimante, un scanner et un modem","un éditeur, un compilateur et un débogueur"],"b":3,"e":"Integrated Development Environment."},{"q":"Tout programme C commence son exécution par la fonction :","r":["main","printf","scanf","include"],"b":0,"e":"C'est le point d'entrée."},{"q":"return 0; à la fin de main signifie :","r":["que le programme a rencontré une erreur","que le programme s'est bien terminé","que le programme recommence au début","que l'affichage est effacé"],"b":1,"e":"Code de retour 0 = succès."},{"q":"Le fichier source d'un programme C porte l'extension :","r":[".exe",".html",".c",".docx"],"b":2,"e":"Par exemple bonjour.c."},{"q":"Le débogueur sert à :","r":["traduire automatiquement le programme en langue anglaise","imprimer le code source en couleur","installer automatiquement le compilateur","exécuter pas à pas pour trouver les erreurs"],"b":3,"e":"Points d'arrêt, inspection des variables."},{"q":"Dev-C++ est :","r":["un EDI pour le langage C","un tableur pour les programmeurs","un réseau social","un système de fichiers"],"b":0,"e":"Comme Code::Blocks."},{"q":"Une erreur de compilation est signalée :","r":["uniquement après l'exécution","avec la ligne concernée","par un son de l'ordinateur","jamais par le compilateur"],"b":1,"e":"On corrige puis on recompile."}],"c":"1re C","m":"info","rang":13,"apc":{"module":"Programmation en C, HTML, CSS et JavaScript","famille":"Algorithmique et programmation","agir":"Traduire un algorithme en programme et créer une page web","situation":"Dans la salle informatique, Code::Blocks affiche « Can't find compiler executable » quand un élève clique sur « Build ».","tache":"Explique la cause de ce message et la démarche pour corriger le problème."},"gratuit":true});
VRT_L("1re-c-info-r14",{"duree":20,"titre":"Bibliothèques et fonctions d'entrée/sortie en C","accroche":"Lire et afficher en langage C.","intro":"Le langage C s'appuie sur des bibliothèques standard. Les fonctions printf et scanf de stdio.h permettent d'afficher et de lire des données.","objectifs":["inclure une bibliothèque","afficher avec printf","lire avec scanf"],"parties":[{"t":"Bibliothèques","html":"<div class='def'><b>Définition</b>Une <strong>bibliothèque</strong> est un ensemble de fonctions déjà écrites, que l'on rend disponibles par une directive <code>#include</code>. Exemples : stdio.h (entrées-sorties), math.h (fonctions mathématiques), string.h (chaînes).</div>"},{"t":"Afficher et lire","verrou":true},{"t":"Déclarations et types","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":14,"apc":{"module":"Programmation en C, HTML, CSS et JavaScript","famille":"Algorithmique et programmation","agir":"Traduire un algorithme en programme et créer une page web","situation":"Un élève veut écrire un programme C qui lit le prix unitaire d'un cahier et la quantité, puis affiche le montant à payer ; son programme se compile mais plante dès la saisie.","tache":"Écris un programme correct et indique l'erreur la plus probable de l'élève."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r15",{"duree":20,"titre":"Structures itératives en C","accroche":"Les boucles for, while et do while.","intro":"Les boucles de l'algorithmique se traduisent directement en C par for, while et do ... while.","objectifs":["traduire une boucle Pour en for","traduire Tant que et Répéter","écrire un programme avec boucle"],"parties":[{"t":"Correspondances","html":"<div class='def'><b>Définition</b>En C, une <strong>boucle</strong> s'écrit avec <code>for</code> (Pour), <code>while</code> (Tant que) ou <code>do ... while</code> (Répéter ... Jusqu'à, avec la condition inversée).</div>"},{"t":"Syntaxe","verrou":true},{"t":"Opérateurs utiles","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":15,"apc":{"module":"Programmation en C, HTML, CSS et JavaScript","famille":"Algorithmique et programmation","agir":"Traduire un algorithme en programme et créer une page web","situation":"Un programme doit afficher la table de multiplication d'un nombre lu au clavier (de 1 à 10) et redemander le nombre tant qu'il n'est pas compris entre 1 et 12.","tache":"Écris le programme C en utilisant do ... while et for."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r16",{"duree":20,"titre":"Tableaux et fichiers multimédias dans une page web","accroche":"Structurer et enrichir une page HTML.","intro":"Le langage HTML décrit le contenu d'une page web à l'aide de balises. On peut y insérer des tableaux, des images, du son et de la vidéo.","objectifs":["créer un tableau HTML","insérer image, audio et vidéo","respecter la structure d'une page"],"parties":[{"t":"Les tableaux","html":"<div class='def'><b>Définition</b>Le <strong>HTML</strong> (HyperText Markup Language) est le langage de description des pages web ; il utilise des <strong>balises</strong> comme &lt;p&gt; ... &lt;/p&gt;. Un tableau se construit avec &lt;table&gt;, des lignes &lt;tr&gt;, des cellules d'en-tête &lt;th&gt; et des cellules &lt;td&gt;.</div><pre>&lt;table&gt;\n  &lt;tr&gt;&lt;th&gt;Région&lt;/th&gt;&lt;th&gt;Chef-lieu&lt;/th&gt;&lt;/tr&gt;\n  &lt;tr&gt;&lt;td&gt;Littoral&lt;/td&gt;&lt;td&gt;Douala&lt;/td&gt;&lt;/tr&gt;\n&lt;/table&gt;</pre>"},{"t":"Les médias","verrou":true},{"t":"Fusion de cellules","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":16,"apc":{"module":"Programmation en C, HTML, CSS et JavaScript","famille":"Algorithmique et programmation","agir":"Traduire un algorithme en programme et créer une page web","situation":"Pour le site du club de tourisme, tu dois créer une page présentant trois sites touristiques (nom, région, photo) et une courte vidéo de présentation stockée dans le dossier videos.","tache":"Décris le code HTML de la page : tableau avec images et insertion de la vidéo."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r17",{"duree":20,"titre":"Création des formulaires","accroche":"Recueillir des informations sur le web.","intro":"Un formulaire HTML permet à l'utilisateur de saisir des informations : inscription, contact, commande.","objectifs":["créer un formulaire","utiliser les principaux champs","rendre un formulaire clair et accessible"],"parties":[{"t":"Le formulaire","html":"<div class='def'><b>Définition</b>Un <strong>formulaire</strong> est une zone de page web, délimitée par &lt;form&gt;, qui contient des champs de saisie et un bouton d'envoi transmettant les données à un programme (attribut action).</div>"},{"t":"Les champs","verrou":true},{"t":"Bonnes pratiques","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":17,"apc":{"module":"Programmation en C, HTML, CSS et JavaScript","famille":"Algorithmique et programmation","agir":"Traduire un algorithme en programme et créer une page web","situation":"Le lycée veut un formulaire d'inscription au tournoi de football : nom, classe (liste), poste (gardien, défenseur, milieu, attaquant : un seul choix), téléphone, et acceptation du règlement.","tache":"Indique pour chaque information le champ HTML adapté et ses attributs essentiels."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r18",{"duree":20,"titre":"Mise en forme d'une page web avec le CSS","accroche":"Séparer le fond et la forme.","intro":"Le HTML décrit le contenu ; le CSS (Cascading Style Sheets) décrit sa présentation : couleurs, polices, marges, disposition.","objectifs":["définir le CSS","écrire des règles CSS","lier une feuille de style à une page"],"parties":[{"t":"Le CSS","html":"<div class='def'><b>Définition</b>Le <strong>CSS</strong> est le langage qui décrit la présentation des pages HTML. Une <strong>règle</strong> se compose d'un sélecteur et de déclarations propriété : valeur.</div><pre>h1 { color: #142554; text-align: center; }\np { font-family: Arial, sans-serif; font-size: 16px; }\n.important { background-color: #FFC93C; }\n#menu { margin: 0; padding: 10px; }</pre>"},{"t":"Les sélecteurs","verrou":true},{"t":"Intégrer le CSS","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":18,"apc":{"module":"Programmation en C, HTML, CSS et JavaScript","famille":"Algorithmique et programmation","agir":"Traduire un algorithme en programme et créer une page web","situation":"Le site du club compte six pages dont chacune contient ses propres attributs de couleur ; le président veut changer la couleur de tous les titres en une seule opération.","tache":"Explique pourquoi une feuille de style externe résout le problème et écris la règle et la ligne de liaison nécessaires."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r19",{"duree":20,"titre":"Organisation des dossiers d'un site web","accroche":"Une arborescence claire pour un site qui fonctionne.","intro":"Un site web est un ensemble de fichiers liés entre eux. Une bonne organisation des dossiers évite les liens cassés et facilite la mise en ligne.","objectifs":["organiser l'arborescence d'un site","écrire des chemins relatifs","créer des liens entre pages"],"parties":[{"t":"L'arborescence","html":"<div class='def'><b>Définition</b>L'<strong>arborescence d'un site</strong> est l'organisation de ses fichiers en dossiers : la page d'accueil index.html à la racine, et des dossiers par type de ressource.</div><pre>monsite/\n   index.html\n   contact.html\n   css/style.css\n   images/logo.png\n   js/script.js\n   pages/activites.html</pre>"},{"t":"Les chemins relatifs","verrou":true},{"t":"Règles de nommage","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":19,"apc":{"module":"Programmation en C, HTML, CSS et JavaScript","famille":"Algorithmique et programmation","agir":"Traduire un algorithme en programme et créer une page web","situation":"Le site du club fonctionne sur l'ordinateur de Paul, mais après copie sur une clé et ouverture sur un autre poste, aucune image ne s'affiche ; ses balises contiennent src=\"C:\\Users\\Paul\\Desktop\\Photo Club.JPG\".","tache":"Explique la cause du problème et propose une organisation et un chemin corrects."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r20",{"duree":20,"titre":"Introduction au JavaScript","accroche":"Rendre une page web interactive.","intro":"HTML structure, CSS présente, JavaScript fait agir : il réagit aux clics, calcule, modifie la page sans la recharger.","objectifs":["situer JavaScript par rapport à HTML et CSS","insérer un script dans une page","utiliser alert, console.log et document"],"parties":[{"t":"Rôle de JavaScript","html":"<div class='def'><b>Définition</b><strong>JavaScript</strong> est un langage de programmation interprété par le navigateur, qui permet de rendre une page web interactive : réagir aux actions de l'utilisateur, effectuer des calculs, modifier le contenu de la page.</div>"},{"t":"Insérer un script","verrou":true},{"t":"Agir sur la page","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":20,"apc":{"module":"Programmation en C, HTML, CSS et JavaScript","famille":"Algorithmique et programmation","agir":"Traduire un algorithme en programme et créer une page web","situation":"Sur la page d'accueil du club, un paragraphe d'identifiant « date » doit afficher automatiquement la date du jour, et un message de bienvenue doit apparaître dans la console.","tache":"Écris le script et indique où le placer."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r21",{"duree":20,"titre":"Variables et instructions d'entrée/sortie en JavaScript","accroche":"Lire et afficher en JavaScript.","intro":"Comme en algorithmique, un programme JavaScript manipule des variables et échange des informations avec l'utilisateur.","objectifs":["déclarer des variables","lire une donnée","afficher un résultat"],"parties":[{"t":"Variables","html":"<div class='def'><b>Définition</b>En JavaScript, une <strong>variable</strong> se déclare avec <code>let</code> (valeur modifiable) ou <code>const</code> (valeur fixe). Les types sont dynamiques : nombre, chaîne, booléen, tableau, objet.</div><pre>let nom = \"Awa\";\nconst TVA = 0.1925;\nlet age = 16;</pre>"},{"t":"Entrées et sorties","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":21,"apc":{"module":"Programmation en C, HTML, CSS et JavaScript","famille":"Algorithmique et programmation","agir":"Traduire un algorithme en programme et créer une page web","situation":"Un élève écrit : let a = prompt(\"a ?\"); let b = prompt(\"b ?\"); alert(a + b); il saisit 15 et 10 et obtient 1510.","tache":"Explique le résultat et corrige le programme."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r22",{"duree":20,"titre":"Opérations de base en JavaScript","accroche":"Calculer et comparer.","intro":"JavaScript dispose d'opérateurs arithmétiques, de comparaison et logiques, ainsi que de l'objet Math pour les calculs.","objectifs":["utiliser les opérateurs arithmétiques","utiliser les comparaisons et opérateurs logiques","utiliser l'objet Math"],"parties":[{"t":"Opérateurs","html":"<div class='def'><b>Définition</b>Un <strong>opérateur</strong> est un symbole qui réalise une opération sur des valeurs : +, −, *, / (division), % (reste), ** (puissance).</div><pre>let r = 17 % 5;   // 2\nlet p = 2 ** 10;  // 1024\nlet q = Math.floor(17 / 5); // 3</pre>"},{"t":"Comparaisons et logique","verrou":true},{"t":"L'objet Math","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":22,"apc":{"module":"Programmation en C, HTML, CSS et JavaScript","famille":"Algorithmique et programmation","agir":"Traduire un algorithme en programme et créer une page web","situation":"Une boutique en ligne applique une remise de 15 % si le montant dépasse 20 000 F et si le client est membre.","tache":"Écris l'instruction JavaScript qui calcule le montant à payer à partir de montant et membre (booléen), arrondi au franc."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r23",{"duree":20,"titre":"Traduction des algorithmes en JavaScript","accroche":"De l'algorithme au programme.","intro":"Les structures de l'algorithmique se traduisent presque mot pour mot en JavaScript.","objectifs":["traduire les structures alternatives","traduire les boucles","traduire les tableaux"],"parties":[{"t":"Table de correspondance","html":"<div class='def'><b>Définition</b><strong>Traduire un algorithme</strong>, c'est réécrire chacune de ses instructions dans la syntaxe d'un langage de programmation, sans changer sa logique.</div><ul><li>x ← 5 → <code>x = 5;</code></li><li>Si ... Alors ... Sinon → <code>if (...) { } else { }</code></li><li>Pour i ← 1 à n → <code>for (let i = 1; i &lt;= n; i++) { }</code></li><li>Tant que → <code>while (...) { }</code></li><li>Tableau[1..n] → <code>let t = [];</code> (indices à partir de 0)</li></ul>"},{"t":"Exemple","verrou":true},{"t":"Les fonctions","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":23,"apc":{"module":"Programmation en C, HTML, CSS et JavaScript","famille":"Algorithmique et programmation","agir":"Traduire un algorithme en programme et créer une page web","situation":"L'algorithme suivant compte les élèves admis : nb ← 0 ; Pour i ← 1 à n : Si T[i] ≥ 10 Alors nb ← nb + 1 ; Écrire(nb).","tache":"Traduis-le en une fonction JavaScript qui reçoit un tableau de notes, puis donne le résultat pour [9, 14, 10, 7, 16]."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r24",{"duree":20,"titre":"Fonctions et évènements en JavaScript","accroche":"Réagir aux actions de l'utilisateur.","intro":"Une page devient interactive quand des fonctions s'exécutent en réponse à des évènements : clic, saisie, chargement.","objectifs":["écrire une fonction JavaScript","associer une fonction à un évènement","modifier la page en réponse"],"parties":[{"t":"Évènements","html":"<div class='def'><b>Définition</b>Un <strong>évènement</strong> est une action détectée par le navigateur : clic (click), saisie (input), survol (mouseover), chargement de la page (load), envoi d'un formulaire (submit). Un <strong>gestionnaire d'évènement</strong> est la fonction exécutée quand il se produit.</div>"},{"t":"Associer une fonction","verrou":true},{"t":"Lire un champ","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":24,"apc":{"module":"Programmation en C, HTML, CSS et JavaScript","famille":"Algorithmique et programmation","agir":"Traduire un algorithme en programme et créer une page web","situation":"Une page doit calculer l'indice de masse corporelle (IMC = poids ÷ taille²) quand on clique sur « Calculer », à partir de deux champs d'identifiants poids et taille.","tache":"Écris la fonction et l'association à l'évènement, avec un affichage arrondi à une décimale."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r25",{"duree":20,"titre":"Programmation d'un convertisseur","accroche":"Un projet complet en HTML, CSS et JavaScript.","intro":"Ce projet réunit les acquis : une page avec un formulaire, une présentation soignée et un script qui convertit des valeurs.","objectifs":["concevoir l'interface d'un convertisseur","programmer la conversion","tester et améliorer l'application"],"parties":[{"t":"Le projet","html":"<div class='def'><b>Définition</b>Un <strong>convertisseur</strong> est une application qui transforme une valeur d'une unité dans une autre : francs CFA en euros, degrés Celsius en Fahrenheit, kilomètres en miles.</div><p>Rappel : 1 euro = 655,957 F CFA (parité fixe).</p>"},{"t":"Le code","verrou":true},{"t":"Tester","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":25,"apc":{"module":"Programmation en C, HTML, CSS et JavaScript","famille":"Algorithmique et programmation","agir":"Traduire un algorithme en programme et créer une page web","situation":"Un vendeur de pièces détachées de Douala reçoit des prix en euros de ses fournisseurs et veut une page qui convertit un montant en euros en F CFA, en ajoutant 10 % de frais de transport.","tache":"Écris la fonction de conversion et donne le résultat pour 250 €."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r26",{"duree":20,"titre":"Besoins matériels pour l'installation d'un système d'exploitation","accroche":"Vérifier avant d'installer.","intro":"Avant d'installer un système d'exploitation, on vérifie que l'ordinateur dispose des ressources minimales demandées.","objectifs":["définir un système d'exploitation","lire une configuration minimale","vérifier la compatibilité d'un ordinateur"],"parties":[{"t":"Le système d'exploitation","html":"<div class='def'><b>Définition</b>Le <strong>système d'exploitation</strong> (SE) est le logiciel de base qui gère le matériel (processeur, mémoire, disques, périphériques) et permet l'exécution des applications. Exemples : Windows, Linux (Ubuntu), macOS, Android.</div>"},{"t":"La configuration requise","verrou":true},{"t":"Vérifier un poste","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":26,"apc":{"module":"Système d'exploitation, invite de commandes et sécurité","famille":"Environnement numérique","agir":"Installer, configurer et protéger un poste de travail","situation":"Un système demande au minimum un processeur 64 bits, 4 Go de RAM et 64 Go d'espace disque. Le vieil ordinateur du secrétariat possède un processeur 64 bits, 2 Go de RAM et 120 Go de disque dont 70 Go libres.","tache":"Indique si l'installation est possible et propose une solution."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r27",{"duree":20,"titre":"Installation d'un système d'exploitation","accroche":"Les étapes d'une installation propre.","intro":"Installer un système d'exploitation suit une démarche précise, de la sauvegarde des données à la configuration du premier compte.","objectifs":["préparer une installation","suivre les étapes d'installation","partitionner un disque"],"parties":[{"t":"Préparer","html":"<div class='def'><b>Définition</b>L'<strong>installation d'un système d'exploitation</strong> consiste à copier ses fichiers sur le disque, à préparer ce disque et à configurer les réglages de base pour que l'ordinateur démarre sur ce système.</div><ol><li>Sauvegarder les données personnelles.</li><li>Créer un support d'installation (clé USB démarrable) depuis l'image officielle.</li><li>Régler l'ordre de démarrage dans le BIOS/UEFI pour démarrer sur la clé.</li></ol>"},{"t":"Installer","verrou":true},{"t":"Partitions","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":27,"apc":{"module":"Système d'exploitation, invite de commandes et sécurité","famille":"Environnement numérique","agir":"Installer, configurer et protéger un poste de travail","situation":"Le technicien de ton lycée doit réinstaller le système d'un ordinateur infecté contenant les bulletins de l'année non sauvegardés.","tache":"Décris dans l'ordre les étapes à suivre, en insistant sur celle qui protège les bulletins."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r28",{"duree":20,"titre":"Configuration d'un système d'exploitation","accroche":"Adapter le système à l'utilisateur.","intro":"Après l'installation, on configure le système : comptes, pilotes, réseau, mises à jour, sécurité et personnalisation.","objectifs":["créer et gérer des comptes utilisateurs","installer des pilotes","régler mises à jour, réseau et sécurité"],"parties":[{"t":"Les comptes","html":"<div class='def'><b>Définition</b><strong>Configurer un système d'exploitation</strong>, c'est régler ses paramètres pour l'adapter au matériel et aux utilisateurs : comptes, pilotes, réseau, sécurité, apparence.</div><p>Un compte <strong>administrateur</strong> peut installer des logiciels et modifier les réglages ; un compte <strong>standard</strong> a des droits limités. Pour un poste partagé (salle informatique), les élèves utilisent des comptes standards.</p>"},{"t":"Pilotes et périphériques","verrou":true},{"t":"Réseau, mises à jour, sécurité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":28,"apc":{"module":"Système d'exploitation, invite de commandes et sécurité","famille":"Environnement numérique","agir":"Installer, configurer et protéger un poste de travail","situation":"Après installation, l'imprimante du secrétariat n'imprime que des caractères incompréhensibles et la résolution de l'écran est très faible ; tous les employés utilisent le compte administrateur.","tache":"Identifie les causes de ces problèmes et propose une configuration correcte."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r29",{"duree":20,"titre":"Introduction à l'invite de commandes","accroche":"Commander l'ordinateur au clavier.","intro":"L'invite de commandes permet de piloter l'ordinateur en tapant des instructions. Elle est rapide et indispensable aux techniciens.","objectifs":["définir l'invite de commandes","ouvrir l'interpréteur","se repérer dans l'arborescence"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>L'<strong>invite de commandes</strong> (interface en ligne de commande) est une interface textuelle dans laquelle l'utilisateur tape des commandes interprétées par le système : cmd ou PowerShell sous Windows, le terminal (bash) sous Linux.</div>"},{"t":"Se repérer","html":"<p>L'invite affiche le dossier courant, par exemple <code>C:\\Users\\Eleve&gt;</code>. Commandes de base sous Windows :</p><ul><li><code>cd dossier</code> : entrer dans un dossier ; <code>cd ..</code> : remonter ;</li><li><code>dir</code> : lister le contenu (ls sous Linux) ;</li><li><code>cls</code> : effacer l'écran (clear sous Linux) ;</li><li><code>cd \\</code> : revenir à la racine du lecteur (C:\\) ;</li><li><code>help</code> : aide.</li></ul><p>Pour ouvrir l'invite : touches Windows + R, taper <code>cmd</code>, puis Entrée (ou rechercher « Invite de commandes » dans le menu Démarrer).</p>","retenir":"cd, dir, cls, help.","labo":{"type":"trier","invite":"Choisis une commande.","items":[["cd","changer de dossier."],["cd ..","remonter au dossier parent."],["dir","lister le contenu du dossier."],["cls","effacer l'écran."]]}},{"t":"Intérêt","html":"<p>Exécuter des tâches rapides ou répétitives, diagnostiquer le réseau, gérer un ordinateur à distance, écrire des scripts d'automatisation.</p><div class='attention'><b>Attention</b>certaines commandes suppriment des fichiers sans passer par la corbeille : on vérifie avant d'appuyer sur Entrée.</div>"},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Question de cours.</strong> L'invite de commandes est :</p><ol type='a'><li>un logiciel de dessin vectoriel</li><li>une interface textuelle</li><li>un navigateur web</li><li>un tableur</li></ol><details><summary>Voir la réponse</summary><p><strong>une interface textuelle</strong>. On tape des commandes au clavier.</p></details><p><strong>Exercice.</strong></p><p>Quelle commande permet de remonter d'un dossier ?</p><details><summary>Voir la réponse</summary><p>(Réponse : cd ..)</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur et méthode."}],"revision":["Invite : interface textuelle (cmd, PowerShell, bash).","cd, cd .., dir, cls, help.","Rapidité, diagnostic, scripts."],"exo":"<p>Quelle commande permet de remonter d'un dossier ? <em>(Réponse : cd ..)</em></p>","quiz":[{"q":"L'invite de commandes est :","r":["un logiciel de dessin vectoriel","une interface textuelle","un navigateur web","un tableur"],"b":1,"e":"On tape des commandes au clavier."},{"q":"Sous Windows, l'invite de commandes s'ouvre avec :","r":["paint","calc","cmd","notepad"],"b":2,"e":"Windows + R, puis cmd."},{"q":"La commande cd sert à :","r":["créer un nouveau dossier vide","copier un fichier","effacer l'écran","changer de dossier"],"b":3,"e":"Change directory."},{"q":"cd .. permet de :","r":["remonter au dossier parent","entrer dans le dernier dossier","supprimer le dossier courant","copier le dossier"],"b":0,"e":"Un niveau plus haut."},{"q":"cd \\ permet de :","r":["remonter d'un seul dossier dans l'arborescence","revenir à la racine du lecteur","ouvrir le bureau","fermer l'invite"],"b":1,"e":"Par exemple C:\\."},{"q":"La commande dir sert à :","r":["supprimer le dossier courant","renommer un fichier","lister le contenu du dossier","tester le réseau"],"b":2,"e":"Équivalent de ls sous Linux."},{"q":"La commande cls sert à :","r":["fermer l'ordinateur","copier un fichier","lister les fichiers","effacer l'écran"],"b":3,"e":"De l'anglais clear screen."},{"q":"Sous Linux, l'équivalent de dir est :","r":["ls","cd","rm","cp"],"b":0,"e":"De l'anglais list (lister)."},{"q":"L'invite C:\\Users\\Eleve&gt; indique :","r":["le nom de l'imprimante","le dossier courant","l'adresse IP","la date du jour"],"b":1,"e":"On se trouve dans Eleve."},{"q":"Un intérêt de l'invite de commandes est :","r":["d'afficher de belles images en haute définition","de retoucher des photos","d'automatiser des tâches répétitives","de jouer à des jeux vidéo"],"b":2,"e":"Par des scripts."}],"c":"1re C","m":"info","rang":29,"apc":{"module":"Système d'exploitation, invite de commandes et sécurité","famille":"Environnement numérique","agir":"Installer, configurer et protéger un poste de travail","situation":"L'invite affiche C:\\Users\\Eleve> et tu dois afficher le contenu du dossier C:\\Users\\Eleve\\Documents\\Projets.","tache":"Écris la suite de commandes à taper et explique chacune."},"gratuit":true});
VRT_L("1re-c-info-r30",{"duree":20,"titre":"Utilisation de l'invite de commandes","accroche":"Gérer fichiers et réseau en ligne de commande.","intro":"Au-delà de la navigation, l'invite de commandes permet de créer, copier, renommer et supprimer des fichiers, et de diagnostiquer le réseau.","objectifs":["gérer des fichiers et dossiers","utiliser des commandes réseau","écrire un petit script"],"parties":[{"t":"Fichiers et dossiers","html":"<div class='def'><b>Définition</b>Une <strong>commande</strong> est une instruction tapée dans l'invite, composée d'un nom et éventuellement de paramètres (arguments) qui précisent sur quoi elle agit.</div><ul><li><code>mkdir Projet</code> : créer un dossier ;</li><li><code>copy a.txt b.txt</code> : copier ;</li><li><code>ren ancien.txt nouveau.txt</code> : renommer un fichier ou un dossier (<code>ren Mathematiques Informatique</code>) ;</li><li><code>del fichier.txt</code> : supprimer un fichier ;</li><li><code>rmdir Projet</code> : supprimer un dossier vide.</li></ul>"},{"t":"Commandes réseau","verrou":true},{"t":"Les scripts","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":30,"apc":{"module":"Système d'exploitation, invite de commandes et sécurité","famille":"Environnement numérique","agir":"Installer, configurer et protéger un poste de travail","situation":"Un poste de la salle informatique n'accède plus à internet. Le technicien veut savoir si la carte réseau a une adresse IP et si un serveur extérieur répond.","tache":"Indique les commandes à utiliser, dans l'ordre, et ce que chacune permet de conclure."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r31",{"duree":20,"titre":"Concepts fondamentaux de la sécurité informatique","accroche":"Confidentialité, intégrité, disponibilité.","intro":"La sécurité informatique protège les informations et les systèmes contre les menaces. Elle repose sur quelques objectifs fondamentaux.","objectifs":["définir la sécurité informatique","citer les objectifs de sécurité","distinguer menace, vulnérabilité et risque"],"parties":[{"t":"Les objectifs","html":"<div class='def'><b>Définition</b>La <strong>sécurité informatique</strong> est l'ensemble des moyens techniques, organisationnels et humains qui protègent les systèmes d'information et leurs données.</div><ul><li><strong>confidentialité</strong> : seules les personnes autorisées accèdent à l'information ;</li><li><strong>intégrité</strong> : l'information n'est pas modifiée sans autorisation ;</li><li><strong>disponibilité</strong> : l'information est accessible quand on en a besoin ;</li><li><strong>authentification</strong> : on vérifie l'identité de l'utilisateur ;</li><li><strong>non-répudiation</strong> : on ne peut nier une action effectuée.</li></ul>"},{"t":"Menace, vulnérabilité, risque","verrou":true},{"t":"Le facteur humain","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":31,"apc":{"module":"Système d'exploitation, invite de commandes et sécurité","famille":"Environnement numérique","agir":"Installer, configurer et protéger un poste de travail","situation":"Dans un cybercafé, le mot de passe administrateur est écrit sur un papier collé à l'écran, l'antivirus n'est pas à jour et une panne électrique a rendu le serveur inaccessible deux jours.","tache":"Pour chaque fait, identifie la vulnérabilité ou l'objectif de sécurité touché et propose une mesure."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r32",{"duree":20,"titre":"Introduction à la cybercriminalité et à la cybersécurité","accroche":"Connaître les attaques pour s'en protéger.","intro":"Les cybercriminels utilisent de nombreuses techniques pour voler des données ou de l'argent. La cybersécurité organise la défense.","objectifs":["définir cybercriminalité et cybersécurité","décrire les principales attaques","connaître les acteurs de la cybersécurité au Cameroun"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>La <strong>cybercriminalité</strong> regroupe les infractions commises au moyen ou contre des systèmes informatiques ; la <strong>cybersécurité</strong> est l'ensemble des mesures qui protègent le cyberespace contre ces attaques.</div>"},{"t":"Les principales attaques","verrou":true},{"t":"Au Cameroun","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":32,"apc":{"module":"Système d'exploitation, invite de commandes et sécurité","famille":"Environnement numérique","agir":"Installer, configurer et protéger un poste de travail","situation":"Ta tante reçoit un SMS : « Vous avez gagné 500 000 F. Envoyez 5 000 F de frais et votre code secret au numéro ci-dessous pour recevoir votre gain. »","tache":"Identifie le type d'attaque, deux indices qui la trahissent et la conduite à tenir."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r33",{"duree":20,"titre":"Techniques de protection des données","accroche":"Sauvegarder, chiffrer, contrôler l'accès.","intro":"Protéger les données passe par des techniques complémentaires : mots de passe solides, sauvegardes, chiffrement, antivirus et mises à jour.","objectifs":["créer un mot de passe robuste","mettre en place une stratégie de sauvegarde","expliquer le chiffrement"],"parties":[{"t":"Contrôler l'accès","html":"<div class='def'><b>Définition</b>La <strong>protection des données</strong> est l'ensemble des mesures qui empêchent leur perte, leur vol ou leur modification non autorisée.</div><p>Un mot de passe robuste compte au moins 12 caractères, mêle majuscules, minuscules, chiffres et symboles, et n'est utilisé que pour un seul compte. L'<strong>authentification à deux facteurs</strong> ajoute un code reçu par SMS ou une application.</p>"},{"t":"Sauvegarder","verrou":true},{"t":"Chiffrer et protéger","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":33,"apc":{"module":"Système d'exploitation, invite de commandes et sécurité","famille":"Environnement numérique","agir":"Installer, configurer et protéger un poste de travail","situation":"Un cybercafé de Bamenda conserve toutes les fiches de ses clients sur un seul ordinateur, protégé par le mot de passe « cyber2020 », sans aucune sauvegarde.","tache":"Identifie trois risques et propose un plan de protection en trois mesures."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r34",{"duree":20,"titre":"Notions sur les images numériques","accroche":"Pixels, définition et couleurs.","intro":"Une image numérique est une grille de points colorés. Sa qualité dépend du nombre de points et de la manière de coder les couleurs.","objectifs":["définir pixel, définition et résolution","expliquer le codage RVB","comparer les formats d'images"],"parties":[{"t":"Pixels et définition","html":"<div class='def'><b>Définition</b>Un <strong>pixel</strong> est le plus petit point d'une image matricielle. La <strong>définition</strong> est le nombre de pixels (largeur × hauteur, par exemple 1920 × 1080) ; la <strong>résolution</strong> est le nombre de pixels par unité de longueur (pixels par pouce, ppp).</div>"},{"t":"Le codage des couleurs","verrou":true},{"t":"Les formats","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":34,"apc":{"module":"Multimédia, systèmes d'information et bases de données","famille":"Systèmes d'information","agir":"Organiser l'information d'une organisation","situation":"Le journal du lycée veut publier un logo avec un fond transparent et des photos d'un match ; un élève propose de tout enregistrer en BMP « pour la qualité ».","tache":"Conseille le format adapté à chaque image et explique pourquoi le BMP n'est pas un bon choix."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r35",{"duree":20,"titre":"Calcul de la résolution et de la taille des fichiers multimédias","accroche":"Combien pèse une image, un son, une vidéo ?","intro":"La taille d'un fichier multimédia non compressé se calcule à partir de ses caractéristiques. Ces calculs aident à choisir supports et formats.","objectifs":["calculer la taille d'une image","calculer la taille d'un son","estimer la taille d'une vidéo"],"parties":[{"t":"Taille d'une image","html":"<div class='def'><b>Définition</b>La <strong>taille d'un fichier</strong> est la quantité de mémoire qu'il occupe, exprimée en octets et ses multiples.</div><p><strong>Taille (octets) = largeur × hauteur × profondeur de couleur (en octets)</strong>. Exemple : 1920 × 1080 × 3 = 6 220 800 octets ≈ 5,9 Mo. Dimension imprimée : pixels ÷ résolution (ppp) ; 3000 pixels à 300 ppp donnent 10 pouces, soit 25,4 cm.</p>"},{"t":"Taille d'un son","verrou":true},{"t":"Taille d'une vidéo","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":35,"apc":{"module":"Multimédia, systèmes d'information et bases de données","famille":"Systèmes d'information","agir":"Organiser l'information d'une organisation","situation":"Le club radio du lycée enregistre une émission de 5 minutes en qualité CD (44 100 Hz, 16 bits, stéréo) et veut l'envoyer par une messagerie limitée à 16 Mo par fichier.","tache":"Calcule la taille du fichier non compressé et conclus, puis propose une solution."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r36",{"duree":20,"titre":"Notion d'entreprise","accroche":"L'organisation qui produit.","intro":"Pour comprendre les systèmes d'information, il faut d'abord comprendre l'entreprise : ses activités, sa structure et ses flux.","objectifs":["définir l'entreprise","décrire ses fonctions","identifier les flux d'informations"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une <strong>entreprise</strong> est une organisation qui combine des moyens humains, matériels et financiers pour produire des biens ou des services destinés à être vendus.</div><p>Elle peut être classée selon sa taille (TPE, PME, grande entreprise), son statut (publique, privée, mixte) ou son secteur.</p>"},{"t":"Fonctions et structure","verrou":true},{"t":"Les flux","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":36,"apc":{"module":"Multimédia, systèmes d'information et bases de données","famille":"Systèmes d'information","agir":"Organiser l'information d'une organisation","situation":"Une PME de transformation de manioc à Ebolowa reçoit des commandes par téléphone, les note sur des papiers volants, et oublie souvent des livraisons ; les factures sont faites à la main.","tache":"Identifie les flux en jeu et les problèmes d'information, puis propose une amélioration."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r37",{"duree":20,"titre":"Introduction aux systèmes d'information (1)","accroche":"L'information, ressource de l'organisation.","intro":"Toute organisation produit, stocke et utilise des informations. Le système d'information organise ces activités.","objectifs":["définir le système d'information","décrire ses fonctions","distinguer SI et système informatique"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>système d'information</strong> (SI) est l'ensemble organisé de ressources (personnes, données, procédures, matériels, logiciels) qui permet de collecter, mémoriser, traiter et diffuser l'information utile à une organisation.</div>"},{"t":"Les quatre fonctions","verrou":true},{"t":"SI et système informatique","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":37,"apc":{"module":"Multimédia, systèmes d'information et bases de données","famille":"Systèmes d'information","agir":"Organiser l'information d'une organisation","situation":"Au lycée, les notes sont saisies par les enseignants dans un logiciel, la moyenne est calculée automatiquement, et les bulletins sont imprimés puis remis aux parents.","tache":"Associe chaque étape à une fonction du SI et cite deux ressources humaines et deux ressources techniques de ce système."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r38",{"duree":20,"titre":"Introduction aux systèmes d'information (2)","accroche":"Composants, acteurs et niveaux de décision.","intro":"Ce second volet étudie les composants du SI, ses utilisateurs et le rôle de l'information dans la prise de décision.","objectifs":["décrire les composants du SI","identifier les niveaux de décision","connaître les qualités d'une information utile"],"parties":[{"t":"Les composants","html":"<div class='def'><b>Définition</b>Les <strong>composants d'un SI</strong> sont les ressources humaines (utilisateurs, informaticiens), les ressources matérielles (ordinateurs, réseaux), les ressources logicielles (applications, bases de données), les données et les procédures (règles de fonctionnement).</div>"},{"t":"Les niveaux de décision","verrou":true},{"t":"Une information utile","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":38,"apc":{"module":"Multimédia, systèmes d'information et bases de données","famille":"Systèmes d'information","agir":"Organiser l'information d'une organisation","situation":"Le directeur d'une chaîne de trois pharmacies reçoit les chiffres de ventes avec un mois de retard et découvre trop tard des ruptures de stock de médicaments contre le paludisme.","tache":"Identifie les défauts de l'information reçue et propose une amélioration du SI."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r39",{"duree":20,"titre":"Notion de base de données","accroche":"Stocker des données organisées et partagées.","intro":"Les fichiers séparés entraînent doublons et incohérences. La base de données regroupe les informations de façon structurée et partagée.","objectifs":["définir une base de données","citer les avantages par rapport aux fichiers","donner des exemples d'utilisation"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une <strong>base de données</strong> est un ensemble structuré de données enregistrées sur un support, organisées pour être facilement consultées, mises à jour et partagées par plusieurs utilisateurs.</div>"},{"t":"Avantages","verrou":true},{"t":"Exemples","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":39,"apc":{"module":"Multimédia, systèmes d'information et bases de données","famille":"Systèmes d'information","agir":"Organiser l'information d'une organisation","situation":"Au lycée, l'adresse d'un élève figure dans trois fichiers différents (scolarité, cantine, infirmerie) ; après son déménagement, seul le fichier de scolarité a été corrigé.","tache":"Explique le problème et montre comment une base de données le résout."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r40",{"duree":20,"titre":"Notion de table","accroche":"Lignes, colonnes et clés.","intro":"Dans une base de données relationnelle, les informations sont rangées dans des tables liées entre elles par des clés.","objectifs":["définir table, enregistrement et champ","identifier une clé primaire","relier deux tables par une clé étrangère"],"parties":[{"t":"Table, champ, enregistrement","html":"<div class='def'><b>Définition</b>Une <strong>table</strong> est un ensemble de données organisé en colonnes et en lignes. Une colonne est un <strong>champ</strong> (attribut) avec un type ; une ligne est un <strong>enregistrement</strong> (n-uplet).</div><p>Exemple : table ELEVE (matricule, nom, prenom, date_naissance, classe).</p>"},{"t":"La clé primaire","verrou":true},{"t":"La clé étrangère","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":40,"apc":{"module":"Multimédia, systèmes d'information et bases de données","famille":"Systèmes d'information","agir":"Organiser l'information d'une organisation","situation":"Une bibliothèque veut enregistrer ses livres et ses emprunts : chaque emprunt concerne un livre et un élève, à une date donnée.","tache":"Propose trois tables avec leurs champs, en soulignant les clés primaires et en indiquant les clés étrangères."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-info-r41",{"duree":20,"titre":"Notion de SGBD","accroche":"Le logiciel qui gère la base.","intro":"Une base de données est gérée par un logiciel spécialisé, le SGBD, qui permet de la créer, de l'interroger et de la protéger.","objectifs":["définir un SGBD","citer ses fonctions","donner des exemples de SGBD"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Un <strong>système de gestion de base de données</strong> (SGBD) est un logiciel qui permet de créer, de stocker, de consulter, de modifier et de protéger les données d'une base, tout en gérant les accès de plusieurs utilisateurs.</div>"},{"t":"Les fonctions","verrou":true},{"t":"Exemples","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"info","rang":41,"apc":{"module":"Multimédia, systèmes d'information et bases de données","famille":"Systèmes d'information","agir":"Organiser l'information d'une organisation","situation":"Une petite pharmacie gère ses stocks dans un tableur ; deux employés modifient le fichier en même temps et écrasent mutuellement leurs saisies, et n'importe qui peut supprimer des lignes.","tache":"Montre comment un SGBD résoudrait ces deux problèmes et propose un SGBD adapté."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r01",{"duree":20,"titre":"Équations et inéquations du second degré","accroche":"Un discriminant suffit à tout savoir.","intro":"Le trinôme ax² + bx + c revient à chaque Probatoire. Son discriminant indique le nombre de solutions, et son signe résout les inéquations.","objectifs":["calculer le discriminant","résoudre une équation du second degré","résoudre une inéquation du second degré"],"parties":[{"t":"Le discriminant","html":"<div class='def'><b>Définition</b>Pour ax² + bx + c = 0 (a ≠ 0), le <strong>discriminant</strong> est Δ = b² − 4ac. Si Δ > 0, il y a deux solutions x = (−b ± √Δ) / (2a) ; si Δ = 0, une solution −b / (2a) ; si Δ &lt; 0, aucune solution réelle.</div>"},{"t":"Le signe du trinôme","html":"<p>Le trinôme a le signe de a <strong>à l'extérieur</strong> des racines et le signe contraire entre elles. Sans racine, il garde le signe de a.</p><p class='formule'>x² − 5x + 6 &lt; 0 ⇔ x ∈ ]2 ; 3[</p>","retenir":"Signe de a à l'extérieur des racines.","labo":{"type":"parabole","a":1,"b":-5,"c":6}},{"t":"La forme canonique","html":"<p class='formule'>ax² + bx + c = a[(x + b/(2a))² − Δ/(4a²)]</p><p>Le Probatoire D l'utilise pour factoriser puis résoudre.</p>"},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Question de cours.</strong> Le discriminant de ax² + bx + c est :</p><ol type='a'><li>Δ = b² + 4ac</li><li>Δ = 4ac − b²</li><li>Δ = b² − 4ac</li><li>Δ = b − 4ac</li></ol><details><summary>Voir la réponse</summary><p><strong>Δ = b² − 4ac</strong>. C'est lui qui décide du nombre de racines réelles.</p></details><p><strong>Exercice.</strong></p><p>Résous 2x² + 3x − 2 = 0.</p><details><summary>Voir la réponse</summary><p>(Réponse : Δ = 25 ; x = 1/2 ou x = −2.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Un éleveur de Ngaoundéré veut clôturer un enclos rectangulaire avec 60 m de grillage ; l'enclos doit avoir une aire d'au moins 200 m².</p><p><strong>Tâche 1.</strong> Montre que la largeur x vérifie x² − 30x + 200 ≤ 0.</p><p><strong>Tâche 2.</strong> Résous l'inéquation et conclus.</p><details><summary>Voir une réponse attendue</summary><p>Longueur 30 − x ; x(30 − x) ≥ 200 ⇔ x² − 30x + 200 ≤ 0. Δ = 100, racines 10 et 20 : x ∈ [10 ; 20]. La largeur doit être comprise entre 10 m et 20 m.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans la rédaction."}],"revision":["Δ = b² − 4ac.","Solutions selon le signe de Δ.","Signe de a à l'extérieur des racines."],"exo":"<p>Résous 2x² + 3x − 2 = 0. <em>(Réponse : Δ = 25 ; x = 1/2 ou x = −2.)</em></p>","quiz":[{"q":"Le discriminant de ax² + bx + c est :","r":["Δ = b² + 4ac","Δ = 4ac − b²","Δ = b² − 4ac","Δ = b − 4ac"],"b":2,"e":"C'est lui qui décide du nombre de racines réelles."},{"q":"Si Δ > 0, l'équation ax² + bx + c = 0 a :","r":["une seule solution réelle, appelée racine double","aucune solution réelle","une infinité de solutions","deux solutions réelles distinctes"],"b":3,"e":"Elles valent (−b ± √Δ)/(2a)."},{"q":"Si Δ = 0, l'équation a :","r":["une solution double −b/(2a)","deux solutions distinctes","aucune solution","trois solutions"],"b":0,"e":"Le trinôme est alors un carré parfait."},{"q":"Les solutions de x² − 5x + 6 = 0 sont :","r":["−2 et −3","2 et 3","1 et 6","5 et 6"],"b":1,"e":"Δ = 25 − 24 = 1 ; x = (5 ± 1)/2."},{"q":"x² + x + 1 = 0 a dans ℝ :","r":["deux solutions","une solution","aucune solution","la solution 1"],"b":2,"e":"Δ = 1 − 4 = −3, négatif."},{"q":"Un trinôme est du signe de a :","r":["entre les racines, bornes exclues","partout","nulle part","à l'extérieur des racines"],"b":3,"e":"Il est du signe opposé à a entre les racines."},{"q":"L'ensemble des solutions de x² − 30x + 200 ≤ 0 est :","r":["[10 ; 20]","]−∞ ; 10] ∪ [20 ; +∞[","[−20 ; −10]","∅"],"b":0,"e":"Racines 10 et 20 ; a > 0, donc négatif entre les racines."},{"q":"La somme des racines de ax² + bx + c = 0 vaut :","r":["c/a","−b/a","b/a","−c/a"],"b":1,"e":"Relations entre coefficients et racines."},{"q":"Le produit des racines de ax² + bx + c = 0 vaut :","r":["−b/a","b/c","c/a","a/c"],"b":2,"e":"Relations entre coefficients et racines."},{"q":"La forme canonique de x² − 4x + 1 est :","r":["(x − 4)² + 1","(x + 2)² − 3","(x − 2)² + 1","(x − 2)² − 3"],"b":3,"e":"x² − 4x + 4 − 3."}],"c":"1re C","m":"maths","rang":1,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Une couturière de Bafoussam veut un tissu rectangulaire dont la longueur dépasse la largeur de 3 m, pour une aire de 40 m².","tache":"Détermine les dimensions du tissu."},"gratuit":true});
VRT_L("1re-c-maths-r02",{"duree":20,"titre":"Systèmes se ramenant au second degré","accroche":"Deux nombres dont on connaît la somme et le produit.","intro":"Certains systèmes non linéaires se résolvent grâce à une équation auxiliaire du second degré.","objectifs":["utiliser somme et produit","exploiter une substitution","vérifier les solutions"],"parties":[{"t":"Somme et produit","html":"<div class='def'><b>Définition</b>Si x + y = S et xy = P, alors x et y sont les solutions de <strong>X² − SX + P = 0</strong>, à condition que S² − 4P ≥ 0.</div>"},{"t":"Exemple","verrou":true},{"t":"Forme x² + y²","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":2,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un propriétaire de Limbé clôture une parcelle rectangulaire de 34 m de périmètre et de 60 m² d'aire.","tache":"Détermine la longueur et la largeur."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r03",{"duree":20,"titre":"Polynômes de degré 3 et factorisation","accroche":"Une racine évidente ouvre la voie.","intro":"Une racine connue d'un polynôme permet de le factoriser, puis de finir avec le second degré.","objectifs":["reconnaître une racine","factoriser par x − a","résoudre une équation de degré 3"],"parties":[{"t":"Racine et factorisation","html":"<div class='def'><b>Définition</b>Le réel a est une <strong>racine</strong> de P si P(a) = 0. Alors P(x) se factorise par (x − a) : P(x) = (x − a)Q(x).</div>"},{"t":"Identification","verrou":true},{"t":"Résolution","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":3,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un fabricant de boîtes à Douala modélise le volume d'une boîte par V(x) = x³ − 6x² + 11x − 6 et cherche les valeurs où ce volume s'annule.","tache":"Trouve ces valeurs."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r05",{"duree":20,"titre":"Signe d'un polynôme de degré 3","accroche":"Le tableau de signes fait tout le travail.","intro":"Une fois factorisé, un polynôme de degré 3 se lit dans un tableau de signes.","objectifs":["factoriser","dresser un tableau de signes","résoudre une inéquation"],"parties":[{"t":"La méthode","html":"<div class='def'><b>Définition</b>Pour étudier le <strong>signe</strong> d'un polynôme, on le factorise en facteurs du premier ou second degré, puis on dresse un tableau de signes.</div>"},{"t":"Exemple","verrou":true},{"t":"Inéquation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":5,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Le bénéfice d'une petite unité de Kribi est modélisé par B(x) = x(x − 2)(x + 2), pour x exprimé en centaines d'articles, x positif.","tache":"Détermine les quantités qui donnent un bénéfice positif."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r06",{"duree":20,"titre":"Équations irrationnelles","accroche":"On élève au carré, puis on trie.","intro":"Une équation avec racine carrée se résout en respectant une condition essentielle.","objectifs":["déterminer les conditions","résoudre","vérifier les solutions"],"parties":[{"t":"Le principe","html":"<div class='def'><b>Définition</b>Une équation <strong>irrationnelle</strong> contient l'inconnue sous un radical. <strong>√A = B ⇔ B ≥ 0 et A = B²</strong>.</div>"},{"t":"Exemple","verrou":true},{"t":"Vérification","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":6,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Pour une rampe à Kumba, la longueur en mètres vérifie √(2x + 3) = x.","tache":"Détermine la valeur de x et justifie."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r07",{"duree":20,"titre":"Inéquations irrationnelles","accroche":"Deux schémas à connaître.","intro":"Selon le sens de l'inégalité, on utilise des conditions différentes.","objectifs":["utiliser les équivalences","résoudre","présenter sur un axe"],"parties":[{"t":"Les équivalences","html":"<div class='def'><b>Définition</b><strong>√A &lt; B ⇔ A ≥ 0, B > 0 et A &lt; B²</strong>. Pour √A > B : ou bien B &lt; 0 et A ≥ 0, ou bien B ≥ 0 et A > B².</div>"},{"t":"Exemple","verrou":true},{"t":"Rédaction","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":7,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"La vitesse d'un jet d'eau à Mbalmayo vérifie √(x + 2) &lt; x, avec x en dizaines de cm.","tache":"Détermine les valeurs de x possibles."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r04",{"duree":20,"titre":"Intégration : équations et prix","accroche":"Un prix qui se calcule à l'envers.","intro":"Le Probatoire demande de traduire une situation par une équation, puis de conclure.","objectifs":["choisir l'inconnue","mettre en équation","conclure en contexte"],"parties":[{"t":"Modéliser","html":"<div class='def'><b>Définition</b><strong>Modéliser</strong>, c'est traduire une situation par une équation ou une inéquation.</div>"},{"t":"Exemple","verrou":true},{"t":"Rédaction","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":4,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un vendeur de beignets de Yaoundé constate qu'à un prix p il vend (200 − p) beignets et veut une recette de 7 500 F.","tache":"Propose un prix et justifie."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r08",{"duree":20,"titre":"Systèmes linéaires à deux inconnues","accroche":"Deux droites, un point.","intro":"Résoudre un système, c'est chercher le point commun de deux droites.","objectifs":["résoudre par substitution","utiliser le déterminant","interpréter"],"parties":[{"t":"Le système","html":"<div class='def'><b>Définition</b>Le système ax + by = c ; a'x + b'y = c' a pour <strong>déterminant</strong> D = ab' − a'b. Si D ≠ 0, il a une solution unique.</div>"},{"t":"La méthode de Cramer","verrou":true},{"t":"Interprétation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":8,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Au marché de Foumbot, 2 tas de tomates et 3 tas de piment coûtent 1 200 F ; un tas de tomates coûte 100 F de plus qu'un tas de piment.","tache":"Trouve le prix de chaque tas."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r09",{"duree":20,"titre":"Systèmes linéaires à trois inconnues","accroche":"Pivot de Gauss : une inconnue à la fois.","intro":"La méthode du pivot triangularise le système. Ce type de système revient très souvent au Probatoire.","objectifs":["appliquer le pivot","remonter les inconnues","vérifier"],"parties":[{"t":"La méthode","html":"<div class='def'><b>Définition</b>Le <strong>pivot de Gauss</strong> remplace les lignes par des combinaisons pour obtenir un système triangulaire équivalent.</div>"},{"t":"Exemple","verrou":true},{"t":"Modéliser","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":9,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un fermier de Foumban achète à crédit des bêtes. 10 poussins, 2 pourceaux et 1 chevreau coûtent 45 000 F ; 20 poussins, 1 pourceau et 2 chevreaux coûtent 45 000 F ; 30 poussins, 2 pourceaux et 2 chevreaux coûtent 65 000 F.","tache":"Détermine le prix unitaire de chaque espèce."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r13",{"duree":20,"titre":"Formules de transformation","accroche":"Transformer un produit, simplifier une somme.","intro":"Les formules d'addition et de duplication simplifient les expressions trigonométriques.","objectifs":["utiliser les formules d'addition","utiliser la duplication","écrire a cos x + b sin x"],"parties":[{"t":"Addition","html":"<div class='def'><b>Définition</b><strong>cos(a + b) = cos a cos b − sin a sin b</strong> ; <strong>sin(a + b) = sin a cos b + cos a sin b</strong>.</div>"},{"t":"Duplication","verrou":true},{"t":"Forme R cos(x − φ)","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":13,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un élève de Dschang étudie une tension alternative de la forme √3 cos t + sin t.","tache":"Écris-la sous la forme R cos(t − φ)."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r14",{"duree":20,"titre":"Équations et inéquations trigonométriques","accroche":"Deux familles de solutions.","intro":"Il faut savoir traduire une équation par une égalité d'angles, puis choisir les solutions dans l'intervalle.","objectifs":["résoudre cos x = cos a","résoudre sin x = sin a","résoudre une inéquation sur un intervalle"],"parties":[{"t":"Les équations de base","html":"<div class='def'><b>Définition</b><strong>cos x = cos a ⇔ x = a + 2kπ ou x = −a + 2kπ</strong>. <strong>sin x = sin a ⇔ x = a + 2kπ ou x = π − a + 2kπ</strong>, k entier.</div>"},{"t":"Exemple","verrou":true},{"t":"Se ramener au second degré","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":14,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un technicien de Song Loulou cherche sur [0 ; 2π[ les instants où une tension vérifie 2 cos t − 1 = 0.","tache":"Détermine les solutions."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r20",{"duree":20,"titre":"Transformations trigonométriques : entraînement","accroche":"Se ramener à un polynôme en cos x.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>cos 2x = 2cos²x − 1 transforme une expression en un polynôme en cos x.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":20,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un électricien de Bertoua calcule une puissance qui dépend de l'angle x sous la forme E = 2 cos²x − cos 2x ; il veut une formule plus simple avant de faire ses mesures pour x = 0, π/3 et π/2.","tache":"Simplifie E, puis calcule sa valeur pour les trois angles."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r21",{"duree":20,"titre":"Équations trigonométriques : entraînement","accroche":"Un sujet de Probatoire.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Sur un intervalle, on donne à k les valeurs qui conviennent.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":21,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Une balançoire de Kribi suit une loi en cos(2t − π/3), et on cherche les instants où la valeur vaut √3/2.","tache":"Donne la méthode."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r18",{"duree":20,"titre":"Premiers outils du dénombrement","accroche":"Compter sans tout écrire.","intro":"Deux principes simples, somme et produit, résolvent la plupart des comptages.","objectifs":["utiliser le principe additif","utiliser le principe multiplicatif","utiliser la factorielle"],"parties":[{"t":"Les principes","html":"<div class='def'><b>Définition</b><strong>Principe additif</strong> : on additionne si les cas s'excluent. <strong>Principe multiplicatif</strong> : on multiplie pour des choix successifs.</div>"},{"t":"Réunion","verrou":true},{"t":"Factorielle","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":18,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Une école de Garoua propose 3 entrées et 4 plats au déjeuner du samedi.","tache":"Détermine le nombre de menus possibles."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r19",{"duree":20,"titre":"p-listes, arrangements et combinaisons","accroche":"L'ordre compte-t-il ? Peut-on répéter ?","intro":"Deux questions suffisent à choisir la bonne formule.","objectifs":["reconnaître chaque situation","appliquer les formules","résoudre un tirage"],"parties":[{"t":"Les trois formules","html":"<div class='def'><b>Définition</b>Choisir p éléments parmi n : <strong>p-liste</strong> nᵖ (ordre, répétition) ; <strong>arrangement</strong> n!/(n − p)! (ordre, sans répétition) ; <strong>combinaison</strong> n!/[p!(n − p)!] (sans ordre, sans répétition).</div>"},{"t":"Exemples","verrou":true},{"t":"Au Probatoire","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":19,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Une PME de Douala choisit 6 responsables parmi 10 candidats, et prévoit une enveloppe à 100 F par groupe possible, pour un budget de 12 500 F.","tache":"Le budget suffit-il ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r24",{"duree":20,"titre":"Dénombrement : entraînement","accroche":"Une union, deux comptages.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Pour « au moins un », compter le complémentaire est souvent plus rapide.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":24,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Dans un club de 30 membres à Kumba, 10 sont des garçons ; on désigne 2 représentants.","tache":"Combien de choix avec au moins une fille ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r25",{"duree":20,"titre":"p-listes et arrangements : entraînement","accroche":"Numéros de téléphone et mots de passe.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Arrangement et p-liste diffèrent par la répétition.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":25,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un opérateur de Yaoundé crée des codes à 5 chiffres pouvant se répéter.","tache":"Détermine le nombre de codes."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r22",{"duree":20,"titre":"Le barycentre","accroche":"Le point d'équilibre d'un système de points pondérés.","intro":"Le barycentre généralise le milieu : il tient compte du poids de chaque point.","objectifs":["définir le barycentre","le construire","utiliser la réduction vectorielle"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Si a + b ≠ 0, le <strong>barycentre</strong> G de (A ; a) et (B ; b) est l'unique point tel que a·GA⃗ + b·GB⃗ = 0⃗. Alors AG⃗ = b/(a + b) · AB⃗.</div>"},{"t":"Réduction","verrou":true},{"t":"Associativité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":22,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un porteur de Bafang transporte deux seaux de 10 kg et 30 kg aux extrémités d'un bâton de 2 m.","tache":"Où doit-il placer l'épaule pour l'équilibre ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r27",{"duree":20,"titre":"Barycentre : entraînement","accroche":"Associativité en action.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Le barycentre partiel simplifie la construction.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":27,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Trois villages A, B, C comptent 1 000, 1 000 et 2 000 habitants ; le maire veut un forage au point d'équilibre.","tache":"Indique la construction."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r23",{"duree":20,"titre":"Lignes de niveau","accroche":"Un ensemble de points défini par une égalité.","intro":"Les fonctions vectorielles du barycentre permettent de reconnaître des droites et des cercles.","objectifs":["réduire une somme vectorielle","reconnaître un cercle","reconnaître une droite"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une <strong>ligne de niveau</strong> k d'une fonction f du plan est l'ensemble des points M tels que f(M) = k.</div>"},{"t":"Les cas classiques","verrou":true},{"t":"Méthode","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":23,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Pour un forage, l'ingénieur de Mbalmayo cherche les points M tels que MA² + MB² = 24 m², avec AB = 4 m.","tache":"Décris cet ensemble."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r28",{"duree":20,"titre":"Lignes de niveau et arcs capables : entraînement","accroche":"Un angle droit vu d'un point.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>L'ensemble des points M tels que (MA⃗, MB⃗) = π/2 est le cercle de diamètre [AB] privé de A et B.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":28,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Au stade de Garoua, un photographe veut voir les deux poteaux d'un but sous un angle droit.","tache":"Décris les positions possibles."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r26",{"duree":20,"titre":"Notion de fonctions et d'applications","accroche":"Une machine qui associe au plus un résultat.","intro":"Avant d'étudier une fonction, il faut connaître son ensemble de définition.","objectifs":["déterminer un ensemble de définition","distinguer fonction et application","composer des fonctions"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>Une <strong>fonction</strong> associe à chaque élément de E au plus une image dans F. Une <strong>application</strong> associe à chaque élément de E exactement une image.</div>"},{"t":"Ensemble de définition","verrou":true},{"t":"Composée","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":26,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Le prix au kilo d'une denrée à Bafoussam est modélisé par p(x) = 1 200/(x − 2), où x est le jour du mois.","tache":"Pour quels jours la formule a-t-elle un sens ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r30",{"duree":20,"titre":"Fonctions et applications : entraînement","accroche":"Un ensemble de définition piège.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Il faut réunir toutes les conditions : dénominateur, radical, et éventuel quotient sous radical.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":30,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un tarif de taxi à Douala est f(x) = √(x² − 4) × 100 F, x étant la distance en km.","tache":"Indique les distances acceptées par la formule."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r29",{"duree":20,"titre":"Symétries et translations des courbes","accroche":"Construire une courbe à partir d'une autre.","intro":"Repérer une symétrie réduit l'étude d'une fonction ; une translation donne une courbe nouvelle à partir d'une courbe connue.","objectifs":["prouver un axe de symétrie","prouver un centre de symétrie","utiliser une translation"],"parties":[{"t":"Éléments de symétrie","html":"<div class='def'><b>Définition</b>La droite x = a est un <strong>axe de symétrie</strong> si f(2a − x) = f(x). Le point I(a ; b) est un <strong>centre de symétrie</strong> si f(2a − x) + f(x) = 2b.</div>"},{"t":"Translations","verrou":true},{"t":"Courbes associées","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":29,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un artisan de Foumban dessine une calebasse dont le profil suit y = x² − 4x + 1.","tache":"Indique l'axe de symétrie du profil."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r33",{"duree":20,"titre":"Symétries des courbes : entraînement","accroche":"Démontrer un centre de symétrie.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Pour un centre, on calcule f(2a − x) + f(x).</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":33,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Une graphiste de Douala a tracé la courbe de f(x) = x² − 4x + 3 sur [0 ; 5] ; son client veut un motif symétrique et lui demande la courbe de g(x) = f(|x|) sur [−5 ; 5].","tache":"Explique la construction de la courbe de g à partir de celle de f et précise ses points d'intersection avec l'axe des abscisses."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r32",{"duree":20,"titre":"Limites et asymptotes","accroche":"Ce qui se passe au bout de la courbe.","intro":"Les limites décrivent le comportement d'une fonction aux bornes de son domaine et donnent les asymptotes.","objectifs":["calculer des limites usuelles","lever une indétermination","reconnaître une asymptote"],"parties":[{"t":"Les asymptotes","html":"<div class='def'><b>Définition</b>Si lim f(x) = ±∞ quand x tend vers a, la droite x = a est <strong>asymptote verticale</strong>. Si lim f(x) = b en ±∞, la droite y = b est <strong>asymptote horizontale</strong>.</div>"},{"t":"Fonctions rationnelles","verrou":true},{"t":"Indéterminations","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":32,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Le coût moyen de production d'un savonnier de Bafoussam est C(x) = (2x + 600)/x pour x pains.","tache":"Que devient ce coût pour de très grandes quantités ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r35",{"duree":20,"titre":"Limites : entraînement","accroche":"La quantité conjuguée.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Pour une forme ∞ − ∞ avec racine, on multiplie par la quantité conjuguée.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":35,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un calcul de trajectoire d'un ballon au stade Ahmadou-Ahidjo conduit à √(x² + 1) − x pour x grand.","tache":"Que vaut cette expression pour x très grand ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r34",{"duree":20,"titre":"Continuité","accroche":"Une courbe tracée sans lever le crayon.","intro":"La continuité garantit l'existence de solutions pour certaines équations.","objectifs":["définir la continuité en un point","reconnaître les fonctions continues","utiliser le théorème des valeurs intermédiaires"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>f est <strong>continue en a</strong> si lim f(x) = f(a) quand x tend vers a.</div>"},{"t":"Fonctions continues","verrou":true},{"t":"Valeurs intermédiaires","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":34,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un réservoir à Ngaoundéré se remplit selon une fonction continue ; il contient 200 L à 8 h et 1 000 L à 10 h.","tache":"Le volume a-t-il atteint 600 L entre 8 h et 10 h ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r37",{"duree":20,"titre":"Continuité : entraînement","accroche":"Encadrer une solution.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>On encadre la solution unique par dichotomie ou balayage.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":37,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"La température d'un four de boulangerie à Douala passe de 50 °C à 220 °C en 30 minutes.","tache":"Justifie qu'elle a été égale à 180 °C."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r36",{"duree":20,"titre":"Nombre dérivé et fonction dérivée","accroche":"La pente d'une courbe en un point.","intro":"Le nombre dérivé mesure la vitesse de variation et donne l'équation de la tangente.","objectifs":["définir le nombre dérivé","écrire une tangente","calculer des dérivées"],"parties":[{"t":"Le nombre dérivé","html":"<div class='def'><b>Définition</b>f est dérivable en a si (f(a + h) − f(a))/h a une limite finie quand h tend vers 0 ; cette limite est le <strong>nombre dérivé</strong> f'(a).</div>"},{"t":"La tangente","verrou":true},{"t":"Dérivées usuelles","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":36,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Le trajet d'une moto-taxi à Douala est modélisé par d(t) = t², en km, t en heures.","tache":"Quelle est la vitesse instantanée à t = 1 h ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r39",{"duree":20,"titre":"Nombre dérivé : entraînement","accroche":"Tangente à la courbe de la racine carrée.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>(√x)' = 1/(2√x) pour x > 0.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":39,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un toboggan d'un parc de Yaoundé suit la courbe y = √x.","tache":"Donne la pente au point d'abscisse 4."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r38",{"duree":20,"titre":"Utiliser la fonction dérivée","accroche":"Le signe de f' donne les variations.","intro":"La dérivée permet d'étudier les variations et de trouver un maximum ou un minimum.","objectifs":["relier signe de f' et variations","dresser un tableau de variation","résoudre un problème d'optimisation"],"parties":[{"t":"Le théorème","html":"<div class='def'><b>Définition</b>Si f' > 0 sur un intervalle, f y est <strong>strictement croissante</strong> ; si f' &lt; 0, f y est <strong>strictement décroissante</strong>.</div>"},{"t":"Exemple","html":"<p>f(x) = x³ − 3x, f'(x) = 3(x − 1)(x + 1). f croît sur ]−∞ ; −1], décroît sur [−1 ; 1], croît sur [1 ; +∞[. Maximum local f(−1) = 2, minimum local f(1) = −2.</p>","labo":{"type":"courbe","fn":"x3","xmin":-2,"xmax":2,"ymin":-8,"ymax":8,"x0":1}},{"t":"Optimisation","html":"<p>Clôture de 100 m le long d'un mur : A(x) = x(100 − 2x), A'(x) = 100 − 4x. Maximum pour x = 25 : A = 1 250 m².</p>","retenir":"Un extremum se lit là où f' s'annule en changeant de signe."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Question de cours.</strong> Si f'(x) &gt; 0 sur un intervalle, f y est :</p><ol type='a'><li>strictement décroissante</li><li>constante</li><li>strictement croissante</li><li>nulle</li></ol><details><summary>Voir la réponse</summary><p><strong>strictement croissante</strong>. Le signe de la dérivée donne le sens de variation.</p></details><p><strong>Exercice.</strong></p><p>Quel est le maximum de f(x) = −x² + 4x ?</p><details><summary>Voir la réponse</summary><p>(Réponse : 4, pour x = 2.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Un menuisier de Bertoua découpe un carré de côté x aux quatre coins d'une plaque de 30 cm sur 30 cm pour fabriquer une boîte sans couvercle. Le volume est V(x) = x(30 − 2x)², x ∈ ]0 ; 15[.</p><p><strong>Tâche 1.</strong> Calcule V'(x) et étudie son signe.</p><p><strong>Tâche 2.</strong> Pour quelle valeur de x le volume est-il maximal ? Calcule-le.</p><details><summary>Voir une réponse attendue</summary><p>V'(x) = (30 − 2x)(30 − 6x), positif sur ]0 ; 5[, négatif sur ]5 ; 15[. Maximum en x = 5 cm : V = 5 × 20² = 2 000 cm³.</p></details></div>","retenir":"Savoir-être mobilisé : Persévérance dans la recherche."}],"revision":["Signe de f'.","Tableau de variation.","Extremum."],"exo":"<p>Quel est le maximum de f(x) = −x² + 4x ? <em>(Réponse : 4, pour x = 2.)</em></p>","quiz":[{"q":"Si f'(x) > 0 sur un intervalle, f y est :","r":["strictement décroissante","constante","strictement croissante","nulle"],"b":2,"e":"Le signe de la dérivée donne le sens de variation."},{"q":"Si f' s'annule en changeant de signe en a, f admet en a :","r":["une asymptote","une discontinuité","rien","un extremum local"],"b":3,"e":"Maximum ou minimum."},{"q":"f(x) = x³ − 3x. f'(x) vaut :","r":["3x² − 3","3x² − 3x","x² − 3","3x − 3"],"b":0,"e":"On dérive terme à terme."},{"q":"f(x) = x³ − 3x est décroissante sur :","r":["[1 ; +∞[","[−1 ; 1]","]−∞ ; −1]","ℝ"],"b":1,"e":"f'(x) = 3(x² − 1) &lt; 0 entre −1 et 1."},{"q":"Le maximum de B(x) = −2x² + 24x − 40 est atteint en :","r":["x = 12","x = 2","x = 6","x = 10"],"b":2,"e":"B'(x) = −4x + 24 = 0."},{"q":"La dérivée de u × v est :","r":["u'v'","u'v − uv'","uv'","u'v + uv'"],"b":3,"e":"Formule du produit."},{"q":"La dérivée de u/v est :","r":["(u'v − uv')/v²","u'/v'","(u'v + uv')/v²","u'v − uv'"],"b":0,"e":"Formule du quotient."},{"q":"La dérivée de (2x + 1)/(x − 1) est :","r":["3/(x − 1)²","−3/(x − 1)²","2/(x − 1)","−1/(x − 1)²"],"b":1,"e":"(2(x − 1) − (2x + 1))/(x − 1)²."},{"q":"Pour trouver le sommet d'une bosse y = −x³ + 3x + 2 entre −2 et 2, on résout :","r":["y = 0, soit x = 0 ou x = ±1","y'' = 0, soit le point d'inflexion d'abscisse x = 0","y' = 0, soit x = ±1, puis on choisit x = 1","x = 0"],"b":2,"e":"y' = −3x² + 3 ; maximum en x = 1."},{"q":"Un tableau de variation se construit à partir :","r":["des valeurs de f en 0 seulement","de la courbe uniquement","du discriminant","du signe de la dérivée"],"b":3,"e":"On y reporte aussi les extrema."}],"c":"1re C","m":"maths","rang":38,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Ben, à Edéa, dispose de 100 m de grillage pour clore une parcelle rectangulaire adossée à un mur.","tache":"Détermine la plus grande superficie possible."},"gratuit":true});
VRT_L("1re-c-maths-r43",{"duree":20,"titre":"Utiliser la dérivée : entraînement","accroche":"Le nombre de solutions d'une équation.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Le tableau de variation et les valeurs extrêmes donnent le nombre de solutions de f(x) = 0.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":43,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Le profit d'une coopérative de Bertoua suit f(x) = x³ − 3x² + 1, pour une production x.","tache":"Combien de fois le profit s'annule-t-il ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r40",{"duree":20,"titre":"Intégration : bénéfice d'une PME","accroche":"Produire assez pour gagner.","intro":"Le Probatoire C 2022 étudiait le bénéfice d'une PME : coût, recette, seuil de rentabilité.","objectifs":["écrire le bénéfice","résoudre B(x) > 0","conclure avec la capacité"],"parties":[{"t":"Le modèle","html":"<div class='def'><b>Définition</b>Le <strong>bénéfice</strong> est B(x) = R(x) − C(x), recette moins coût.</div>"},{"t":"Exemple","verrou":true},{"t":"Conclusion","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":40,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Des jeunes de Yaoundé montent une PME : coût C(x) = x² + 202 500 F, prix de vente 1 500 F l'unité, capacité 1 300.","tache":"Quel est le nombre minimal d'articles pour un bénéfice ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r47",{"duree":20,"titre":"Représentation des fonctions polynômes","accroche":"Du tableau de variation à la courbe.","intro":"L'étude complète d'un polynôme suit un plan fixe.","objectifs":["suivre le plan d'étude","placer les points remarquables","tracer la courbe"],"parties":[{"t":"Le plan d'étude","html":"<div class='def'><b>Définition</b>Étudier une fonction, c'est donner son <strong>ensemble de définition</strong>, ses <strong>limites</strong>, sa <strong>dérivée</strong>, son <strong>tableau de variation</strong>, puis tracer sa courbe.</div>"},{"t":"Exemple","verrou":true},{"t":"Le tracé","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":47,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un ingénieur de Kribi trace le profil d'une dune avec y = x³ − 3x + 1, entre −2 et 2.","tache":"Donne les hauteurs extrêmes."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r50",{"duree":20,"titre":"Polynômes : entraînement","accroche":"Une étude complète en quatre temps.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Un polynôme de degré 3 a souvent un centre de symétrie.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":50,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Une piste de BMX à Buea suit y = −x³ + 3x + 2.","tache":"Où se trouve le sommet de la bosse, entre −2 et 2 ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r49",{"duree":20,"titre":"Représentation des fonctions rationnelles","accroche":"Asymptotes et centre de symétrie.","intro":"Les fonctions rationnelles simples ont des asymptotes qui guident le tracé.","objectifs":["étudier une homographique","étudier x + 1/x","tracer avec les asymptotes"],"parties":[{"t":"Homographique","html":"<div class='def'><b>Définition</b>Pour f(x) = (ax + b)/(cx + d), la droite x = −d/c est <strong>asymptote verticale</strong> et la droite y = a/c est <strong>asymptote horizontale</strong>. Leur intersection est centre de symétrie.</div>"},{"t":"Exemple","verrou":true},{"t":"Asymptote oblique","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":49,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Le rendement d'un champ de maïs à Bafia est modélisé par f(x) = (x + 1)/(x − 1) pour x > 1.","tache":"Décris l'évolution du rendement."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r53",{"duree":20,"titre":"Fonctions rationnelles : entraînement","accroche":"Une division pour faire apparaître l'asymptote.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Écrire f(x) = ax + b + c/(x − d) montre l'asymptote oblique y = ax + b.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":53,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Le coût moyen d'une fabrique de briques de Ngaoundéré suit f(x) = ax + b + c/(x + 1), en milliers de francs, pour x centaines de briques. Le comptable a relevé f(0) = 5, f(1) = 4 et f(3) = 5.","tache":"Trouve a, b et c."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r31",{"duree":20,"titre":"Intégration : équilibre et fonctions","accroche":"Le barycentre au service du portage.","intro":"Ce problème relie barycentre et étude de fonction, comme dans les sujets de Probatoire.","objectifs":["modéliser un équilibre","utiliser une fonction","conclure"],"parties":[{"t":"Modèle","html":"<div class='def'><b>Définition</b>Le point d'équilibre d'un système de charges est le <strong>barycentre</strong> des positions pondérées par les masses.</div>"},{"t":"Fonction de la masse","verrou":true},{"t":"Conclusion","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":31,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Une vendeuse de Kumba porte sur l'épaule un bâton de 2 m avec 10 kg de plantains à un bout et un panier de masse m à l'autre.","tache":"Exprime la position de l'épaule et commente."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r10",{"duree":20,"titre":"Droites et distance d'un point à une droite","accroche":"Mesurer l'écart à une route.","intro":"Une équation cartésienne suffit pour calculer la distance d'un point à une droite.","objectifs":["écrire une équation cartésienne","utiliser un vecteur normal","calculer une distance"],"parties":[{"t":"Équation et vecteur normal","html":"<div class='def'><b>Définition</b>La droite d'équation <strong>ax + by + c = 0</strong> admet n⃗(a ; b) comme <strong>vecteur normal</strong> et u⃗(−b ; a) comme vecteur directeur.</div>"},{"t":"La distance","verrou":true},{"t":"Droites particulières","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":10,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un village de la région de l'Est est au point A(1 ; 2), et une route rectiligne a pour équation 3x + 4y − 1 = 0, en km.","tache":"À quelle distance le village est-il de la route ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r15",{"duree":20,"titre":"Droites : entraînement","accroche":"Une parallèle passant par un point.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Deux droites parallèles ont le même vecteur normal.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":15,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un géomètre de Mfou trace une clôture parallèle à une route d'équation 2x − y + 3 = 0, passant par la borne A(1 ; −1).","tache":"Donne l'équation de la clôture."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r11",{"duree":20,"titre":"Cercles","accroche":"Un centre, un rayon, une équation.","intro":"L'équation d'un cercle permet d'étudier sa position par rapport à une droite.","objectifs":["écrire l'équation d'un cercle","trouver centre et rayon","étudier une position relative"],"parties":[{"t":"Équation","html":"<div class='def'><b>Définition</b>Le cercle de centre Ω(a ; b) et de rayon r a pour équation <strong>(x − a)² + (y − b)² = r²</strong>.</div>"},{"t":"Forme développée","verrou":true},{"t":"Position d'une droite","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":11,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Une antenne de téléphonie au point (2 ; −3) couvre un disque de 4 km de rayon ; le village de Ndikiniméki est au point (5 ; 1).","tache":"Le village est-il couvert ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r16",{"duree":20,"titre":"Cercles : entraînement","accroche":"Droite et cercle se coupent-ils ?","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>On compare la distance du centre à la droite avec le rayon, puis on résout le système.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":16,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un sentier rectiligne x + y = 7 traverse un parc circulaire x² + y² = 25 à Ebolowa.","tache":"Donne les points d'entrée et de sortie."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r12",{"duree":20,"titre":"Intégration : couverture d'un réseau","accroche":"Calculer avant d'installer une antenne.","intro":"La géométrie analytique sert à décider de l'emplacement d'un équipement.","objectifs":["modéliser par un cercle","calculer une distance","décider"],"parties":[{"t":"Modèle","html":"<div class='def'><b>Définition</b>La zone couverte par une antenne de portée r est un <strong>disque</strong> de centre l'antenne et de rayon r.</div>"},{"t":"Démarche","verrou":true},{"t":"Décision","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":12,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un opérateur veut couvrir trois villages A(0 ; 0), B(6 ; 0) et C(0 ; 3), en km, avec une antenne de 4 km de portée placée en G(2 ; 1).","tache":"Les trois villages sont-ils couverts ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r17",{"duree":20,"titre":"Intégration : une piste et un lac","accroche":"La piste longe-t-elle le lac sans le traverser ?","intro":"La position relative d'une droite et d'un cercle répond à des questions d'aménagement.","objectifs":["traduire par une droite et un cercle","calculer une distance","conclure"],"parties":[{"t":"Modèle","html":"<div class='def'><b>Définition</b>Une piste rectiligne est une <strong>droite</strong>, un lac circulaire un <strong>disque</strong>.</div>"},{"t":"Exemple","verrou":true},{"t":"Marge","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":17,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"La commune de Yokadouma trace une piste x + y = 8 près d'un lac (x − 1)² + (y − 1)² = 4, en km.","tache":"La piste touche-t-elle le lac ? À quelle distance minimale passe-t-elle ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r41",{"duree":20,"titre":"Composée de deux symétries orthogonales","accroche":"Deux miroirs font une rotation.","intro":"Composer deux réflexions donne une rotation ou une translation selon la position des axes.","objectifs":["composer deux réflexions","reconnaître la transformation obtenue","décomposer une rotation"],"parties":[{"t":"Le résultat","html":"<div class='def'><b>Définition</b>Si les axes Δ et Δ' sont <strong>sécants</strong> en O, s_Δ' ∘ s_Δ est la <strong>rotation</strong> de centre O et d'angle 2(Δ ; Δ'). S'ils sont <strong>parallèles</strong>, c'est une <strong>translation</strong> de vecteur double du vecteur qui va de Δ à Δ' perpendiculairement.</div>"},{"t":"Décomposition","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":41,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un artisan de Foumban veut reproduire un motif tourné de 60° à l'aide de deux miroirs.","tache":"Quel angle doit-il donner aux miroirs ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r45",{"duree":20,"titre":"Composée de réflexions : entraînement","accroche":"Décomposer une rotation, comme au Probatoire C.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>r(A ; θ) = s_(AB) ∘ s_Δ où Δ passe par A et vérifie 2(Δ ; (AB)) = θ.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":45,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un menuisier de Foumban fabrique un motif en étoile : il fait tourner une planchette [AB] de 4 cm autour de A d'un angle de −2π/3. Il doit tracer la droite Δ qui lui sert de guide, axe de symétrie entre B et son image B'.","tache":"Construis B' et indique comment tracer Δ."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r42",{"duree":20,"titre":"Composée de deux rotations","accroche":"Tourner deux fois autour du même point.","intro":"Composer deux rotations de même centre revient à additionner leurs angles.","objectifs":["composer des rotations de même centre","traiter des centres différents","reconnaître l'identité"],"parties":[{"t":"Même centre","html":"<div class='def'><b>Définition</b>r(O ; α) ∘ r(O ; β) est la <strong>rotation</strong> r(O ; α + β). Si α + β = 2kπ, c'est l'<strong>identité</strong>.</div>"},{"t":"Centres différents","verrou":true},{"t":"Méthode","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":42,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Une roue de manège à Douala tourne de 45°, puis encore de 75° autour du même axe.","tache":"Quelle rotation obtient-on au total ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r46",{"duree":20,"titre":"Composée d'homothéties et de translations","accroche":"Agrandir, puis agrandir encore.","intro":"Les homothéties de même centre se composent en multipliant les rapports.","objectifs":["composer deux homothéties de même centre","composer homothétie et translation","déterminer centre et rapport"],"parties":[{"t":"Même centre","html":"<div class='def'><b>Définition</b>h(O ; k) ∘ h(O ; k') est l'<strong>homothétie</strong> h(O ; kk').</div>"},{"t":"Homothétie et translation","verrou":true},{"t":"Trouver un centre","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":46,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un imprimeur de Yaoundé agrandit une affiche au double, puis encore de 1,5 depuis le même coin.","tache":"Quel est l'agrandissement total ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r44",{"duree":20,"titre":"Expression analytique d'une transformation","accroche":"Des formules pour chaque transformation.","intro":"Une transformation du plan peut s'écrire avec les coordonnées : x' et y' en fonction de x et y.","objectifs":["écrire une translation, une homothétie, une rotation","reconnaître une transformation","trouver ses éléments"],"parties":[{"t":"Les formules","html":"<div class='def'><b>Définition</b>Translation de vecteur (a ; b) : <strong>x' = x + a ; y' = y + b</strong>. Homothétie de centre Ω(a ; b), rapport k : <strong>x' − a = k(x − a) ; y' − b = k(y − b)</strong>.</div>"},{"t":"Rotation de centre O","verrou":true},{"t":"Reconnaître","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":44,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un logiciel de couture à Douala transforme un patron par x' = −2x + 3, y' = −2y + 6.","tache":"Décris la transformation."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r48",{"duree":20,"titre":"Transformations analytiques : entraînement","accroche":"Reconnaître un quart de tour.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Pour une rotation de centre O, (1 ; 0) va en (cos θ ; sin θ).</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":48,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un dessinateur de Bamenda fait pivoter un logo selon x' = y, y' = −x.","tache":"Décris ce mouvement."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r51",{"duree":20,"titre":"Espaces et sous-espaces vectoriels","accroche":"Des vecteurs qui restent entre eux.","intro":"Un sous-espace vectoriel contient le vecteur nul et reste stable par combinaison linéaire.","objectifs":["reconnaître un sous-espace","trouver une base","donner la dimension"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>F est un <strong>sous-espace vectoriel</strong> de E s'il contient 0⃗ et si, pour u⃗, v⃗ de F et λ réel, λu⃗ + v⃗ appartient à F.</div>"},{"t":"Exemples","verrou":true},{"t":"Base et dimension","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":51,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un élève de Kumba affirme que l'ensemble des points d'une route x + y = 1 forme un sous-espace vectoriel.","tache":"Corrige-le."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r55",{"duree":20,"titre":"Sous-espaces vectoriels : entraînement","accroche":"Montrer qu'un ensemble est une droite vectorielle.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Un ensemble défini par ax + by = 0, (a ; b) ≠ (0 ; 0), est une droite vectorielle.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":55,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un logiciel de couture de Douala utilise l'application φ(x ; y) = (x + 2y ; 2x + y). L'ingénieur cherche les vecteurs dont la direction est conservée : E₁ = {u : φ(u) = 3u} et E₂ = {u : φ(u) = −u}.","tache":"Montre que E₁ et E₂ sont des droites vectorielles et donne un vecteur directeur de chacune."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r52",{"duree":20,"titre":"Applications linéaires","accroche":"Une transformation qui respecte les combinaisons.","intro":"Une application linéaire transforme une somme en somme et un multiple en multiple.","objectifs":["reconnaître une application linéaire","déterminer noyau et image","décider si elle est bijective"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>f est <strong>linéaire</strong> si f(λu⃗ + v⃗) = λf(u⃗) + f(v⃗) pour tous vecteurs u⃗, v⃗ et tout réel λ.</div>"},{"t":"Noyau et image","verrou":true},{"t":"Bijectivité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":52,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un tableur de comptabilité d'une coopérative de Mbalmayo calcule (recette ; dépense) par f(x ; y) = (x + y ; 2x + 2y).","tache":"Explique pourquoi deux ventes différentes peuvent donner le même résultat."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r56",{"duree":20,"titre":"Applications linéaires : entraînement","accroche":"Trouver le noyau en résolvant un système.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Ker f se trouve en résolvant f(u⃗) = 0⃗.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":56,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un jeu vidéo d'étudiants de Buea déplace les personnages par l'application φ(x ; y) = (2x − y ; x + y). Ils veulent être sûrs de pouvoir toujours revenir à la position de départ.","tache":"Montre que φ est un automorphisme et explique ce que cela garantit."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r54",{"duree":20,"titre":"Matrices et applications linéaires","accroche":"Un tableau de quatre nombres décrit tout.","intro":"La matrice d'une application linéaire dans une base contient les images des vecteurs de base.","objectifs":["écrire une matrice","calculer un déterminant","reconnaître un automorphisme"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>matrice</strong> de f dans la base (i⃗, j⃗) a pour colonnes les coordonnées de f(i⃗) et de f(j⃗).</div>"},{"t":"Déterminant","verrou":true},{"t":"Probatoire C 2022","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":54,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un logiciel de broderie de Bamenda transforme les points d'un motif par φ(i⃗) = 2i⃗ − j⃗ et φ(j⃗) = mi⃗ + 3j⃗ ; pour certaines valeurs de m, le motif s'aplatit en un trait.","tache":"Trouve la valeur de m pour laquelle φ n'est pas un automorphisme et explique ce qui arrive au motif."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r59",{"duree":20,"titre":"Matrices : entraînement","accroche":"Changer de base pour simplifier.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Si f(e⃗₁) = e⃗₁ et f(e⃗₂) = −e⃗₂, la matrice de f dans (e⃗₁, e⃗₂) est diagonale : [[1 ; 0] ; [0 ; −1]].</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":59,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"La même équipe de Buea utilise maintenant φ(x ; y) = (x + y ; x + y). Un joueur se plaint que deux personnages différents arrivent au même endroit.","tache":"Montre que φ n'est pas un automorphisme, donne son noyau et son image."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r57",{"duree":20,"titre":"Intégration : une transformation de logo","accroche":"Une matrice pour un miroir.","intro":"Les applications linéaires décrivent les transformations utilisées en dessin numérique.","objectifs":["traduire une transformation en matrice","interpréter une matrice diagonale","conclure"],"parties":[{"t":"Modèle","html":"<div class='def'><b>Définition</b>Une matrice [[1 ; 0] ; [0 ; −1]] dans une base orthonormée décrit la <strong>symétrie</strong> par rapport à l'axe des abscisses.</div>"},{"t":"Démarche","verrou":true},{"t":"Conclusion","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":57,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Une graphiste de Douala veut un logo et son reflet dans l'eau.","tache":"Propose une application linéaire et justifie."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r58",{"duree":20,"titre":"Généralités sur les suites numériques","accroche":"Une liste de nombres qui suit une règle.","intro":"Une suite peut être donnée par une formule ou par une relation de récurrence.","objectifs":["calculer des termes","étudier le sens de variation","utiliser le raisonnement par récurrence"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une <strong>suite</strong> associe à chaque entier n un réel uₙ. Elle est définie <strong>explicitement</strong> (uₙ = 2n + 1) ou <strong>par récurrence</strong> (u₀ = 1, uₙ₊₁ = 2uₙ + 1).</div>"},{"t":"Sens de variation","verrou":true},{"t":"Récurrence","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":58,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Une tontine de quartier à Douala commence avec 1 membre et chaque mois chaque membre en invite un, plus le fondateur un de plus : uₙ₊₁ = 2uₙ + 1.","tache":"Combien de membres au bout de 3 mois ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r61",{"duree":20,"titre":"Suites : entraînement","accroche":"Une suite croissante à partir d'un rang.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>uₙ₊₁ − uₙ peut changer de signe : la suite est alors monotone seulement à partir d'un certain rang.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":61,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Les ventes d'une boutique à Bafoussam suivent uₙ = n² − 4n, en dizaines, n étant le mois.","tache":"À partir de quel mois les ventes augmentent-elles ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r60",{"duree":20,"titre":"Suites arithmétiques et géométriques","accroche":"Ajouter ou multiplier la même quantité.","intro":"Ces deux suites modélisent salaires, épargne et populations.","objectifs":["reconnaître chaque suite","calculer le terme général","calculer une somme"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>Une suite est <strong>arithmétique</strong> de raison r si uₙ₊₁ = uₙ + r ; elle est <strong>géométrique</strong> de raison q si vₙ₊₁ = q·vₙ.</div>"},{"t":"Formules","verrou":true},{"t":"Intérêts composés","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":60,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un fermier de Foumbot place 1 000 000 F à 15 % d'intérêts composés pour financer un élevage de 3 000 000 F dans 8 ans.","tache":"Ce placement suffira-t-il ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r64",{"duree":20,"titre":"Suites arithmétiques et géométriques : entraînement","accroche":"Une suite auxiliaire au Probatoire D-TI.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Pour une suite récurrente compliquée, on introduit une suite auxiliaire arithmétique ou géométrique.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":64,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Le 1ᵉʳ janvier 2023, une petite ville du Cameroun compte 40 000 habitants ; la population augmente de 5 % par an et reçoit 1 000 immigrants par an.","tache":"Calcule la population au 1ᵉʳ janvier 2025."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r62",{"duree":20,"titre":"Caractéristiques de position et de dispersion","accroche":"Moyenne, médiane, variance d'une série regroupée.","intro":"Pour une série regroupée en classes, on remplace chaque classe par son centre.","objectifs":["calculer la moyenne","calculer variance et écart type","trouver la médiane par interpolation"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>Pour une série en classes de centres cᵢ et d'effectifs nᵢ (total N) : <strong>moyenne</strong> x̄ = Σnᵢcᵢ/N ; <strong>variance</strong> V = Σnᵢcᵢ²/N − x̄² ; <strong>écart type</strong> σ = √V.</div>"},{"t":"Exemple","verrou":true},{"t":"Médiane","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":62,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Une association de Douala relève les dépenses quotidiennes de ses membres, regroupées en classes, pour fixer une cotisation.","tache":"Indique les calculs utiles."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r68",{"duree":20,"titre":"Statistiques : entraînement","accroche":"Un effectif manquant, comme au Probatoire D 2022.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>La moyenne connue et l'effectif total donnent un système.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":68,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Une classe de 1re D de Yaoundé relève les dépenses quotidiennes de ses 60 élèves.","tache":"Donne la démarche pour trouver les effectifs manquants."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r63",{"duree":20,"titre":"Représentations graphiques des séries en classes","accroche":"Histogramme et polygone des effectifs cumulés.","intro":"Le graphique donne une lecture rapide de la série et permet de lire la médiane.","objectifs":["tracer un histogramme","tracer le polygone des effectifs cumulés","lire la médiane"],"parties":[{"t":"L'histogramme","html":"<div class='def'><b>Définition</b>Dans un <strong>histogramme</strong>, chaque classe est représentée par un rectangle dont l'<strong>aire</strong> est proportionnelle à l'effectif.</div>"},{"t":"Classes inégales","verrou":true},{"t":"Effectifs cumulés","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":63,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un journaliste de Yaoundé présente le temps passé devant la télévision le dimanche, en classes inégales.","tache":"Comment doit-il tracer l'histogramme ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r69",{"duree":20,"titre":"Représentations graphiques : entraînement","accroche":"Un sujet de Probatoire D-TI 2026.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Avec des fréquences, on remplace N par 100.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":69,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Une radio de Garoua veut savoir si la moitié des auditeurs regarde la télévision plus de 3 h le dimanche.","tache":"Réponds avec la médiane."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r70",{"duree":20,"titre":"Intégration : statistiques d'une association","accroche":"Des chiffres pour organiser une construction.","intro":"Le Probatoire D 2024 blanc partait d'un village qui finance une école : contributions, âges, choix de superviseurs.","objectifs":["calculer une moyenne","lire la classe modale","dénombrer un choix"],"parties":[{"t":"Les outils","html":"<div class='def'><b>Définition</b><strong>Moyenne</strong>, <strong>médiane</strong> et <strong>classe modale</strong> résument une série ; le dénombrement compte les choix possibles.</div>"},{"t":"Exemple","verrou":true},{"t":"Choix","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":70,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Trois groupes d'un village de l'Ouest financent une école ; leurs 54 membres ont entre 25 et 50 ans.","tache":"Calcule l'âge moyen et le nombre de façons de choisir 3 superviseurs."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r65",{"duree":20,"titre":"Droites orthogonales dans l'espace","accroche":"Orthogonales sans se couper.","intro":"Dans l'espace, deux droites peuvent être orthogonales sans être sécantes.","objectifs":["définir l'orthogonalité","utiliser le produit scalaire","raisonner dans un cube"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Deux droites de l'espace sont <strong>orthogonales</strong> si leurs parallèles menées par un même point sont perpendiculaires, c'est-à-dire si leurs vecteurs directeurs ont un produit scalaire nul.</div>"},{"t":"Dans le cube","html":"<p>Dans le cube ABCDEFGH, (AB) est parallèle à (EF), et (EF) est perpendiculaire à (EH) : donc (AB) et (EH) sont orthogonales, sans se couper.</p>","labo":{"type":"vecteur"}},{"t":"Piège du Probatoire","html":"<p>« Deux droites perpendiculaires à une même troisième sont parallèles » est <strong>faux</strong> dans l'espace.</p>","retenir":"Orthogonales ne veut pas dire sécantes."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Question de cours.</strong> Deux droites de l'espace sont orthogonales si :</p><ol type='a'><li>leurs parallèles menées par un même point sont perpendiculaires</li><li>elles se coupent toujours en un point de l'espace</li><li>elles sont parallèles à un même plan et non coplanaires</li><li>elles sont confondues</li></ol><details><summary>Voir la réponse</summary><p><strong>leurs parallèles menées par un même point sont perpendiculaires</strong>. Elles peuvent ne pas se couper.</p></details><p><strong>Exercice.</strong></p><p>u⃗(1 ; 2 ; −1) et v⃗(3 ; −1 ; 1) sont-ils orthogonaux ?</p><details><summary>Voir la réponse</summary><p>(Réponse : oui, 3 − 2 − 1 = 0.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> On considère un cube ABCDEFGH et, dans un repère, les vecteurs u⃗(1 ; −1 ; 2) et v⃗(2 ; 4 ; 1).</p><p><strong>Tâche 1.</strong> Les droites (AC) et (BF) sont-elles orthogonales ? Sont-elles sécantes ?</p><p><strong>Tâche 2.</strong> Les vecteurs u⃗ et v⃗ sont-ils orthogonaux ?</p><details><summary>Voir une réponse attendue</summary><p>(BF) est orthogonale au plan (ABC), donc à (AC) ; elles ne sont pas sécantes. u⃗ · v⃗ = 2 − 4 + 2 = 0 : orthogonaux.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans la rédaction."}],"revision":["u⃗ · v⃗ = 0.","Pas forcément sécantes.","Contre-exemple du cube."],"exo":"<p>u⃗(1 ; 2 ; −1) et v⃗(3 ; −1 ; 1) sont-ils orthogonaux ? <em>(Réponse : oui, 3 − 2 − 1 = 0.)</em></p>","quiz":[{"q":"Deux droites de l'espace sont orthogonales si :","r":["leurs parallèles menées par un même point sont perpendiculaires","elles se coupent toujours en un point de l'espace","elles sont parallèles à un même plan et non coplanaires","elles sont confondues"],"b":0,"e":"Elles peuvent ne pas se couper."},{"q":"Deux droites orthogonales sont-elles forcément sécantes ?","r":["oui","non","seulement dans un cube","seulement si elles sont parallèles"],"b":1,"e":"Ex. : deux arêtes non coplanaires d'un cube."},{"q":"Dans un cube ABCDEFGH, les droites (AB) et (FG) sont :","r":["parallèles","sécantes","orthogonales","confondues"],"b":2,"e":"(FG) est parallèle à (BC), perpendiculaire à (AB)."},{"q":"Deux droites perpendiculaires sont :","r":["parallèles et non coplanaires","non coplanaires","confondues","orthogonales et sécantes"],"b":3,"e":"Perpendiculaires = orthogonales + sécantes."},{"q":"Deux vecteurs directeurs u et v de droites orthogonales vérifient :","r":["u · v = 0","u = v","u ∧ v = 0","‖u‖ = ‖v‖"],"b":0,"e":"Produit scalaire nul."},{"q":"Si (d) est orthogonale à deux droites sécantes d'un plan, elle est :","r":["parallèle au plan","orthogonale au plan","contenue dans le plan","sans relation"],"b":1,"e":"Critère d'orthogonalité droite-plan."},{"q":"Deux droites parallèles à une même troisième sont :","r":["orthogonales","sécantes","parallèles entre elles","non coplanaires toujours"],"b":2,"e":"Transitivité du parallélisme."},{"q":"Si (d) ⊥ (d') et (d') // (d''), alors :","r":["(d) est parallèle à (d'')","(d) = (d'')","rien","(d) est orthogonale à (d'')"],"b":3,"e":"L'orthogonalité se transmet par parallélisme."},{"q":"Dans un cube, la diagonale [AG] et l'arête [BC] sont :","r":["non orthogonales","orthogonales","parallèles","confondues"],"b":0,"e":"AG · BC ≠ 0 avec AG(1;1;1) et BC(0;1;0)."},{"q":"Dans un repère orthonormé, u(1 ; 2 ; 0) et v(2 ; −1 ; 5) sont :","r":["colinéaires","orthogonaux","égaux","ni l'un ni l'autre"],"b":1,"e":"u · v = 1 × 2 + 2 × (−1) + 0 × 5 = 0 : les vecteurs sont orthogonaux."}],"c":"1re C","m":"maths","rang":65,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un charpentier de Bandjoun vérifie qu'une poutre et un chevron qui ne se touchent pas sont bien d'équerre.","tache":"Comment le vérifier avec des vecteurs ?"},"gratuit":true});
VRT_L("1re-c-maths-r73",{"duree":20,"titre":"Droites orthogonales : entraînement","accroche":"Vrai ou faux, comme au Probatoire C 2022.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Pour montrer que deux droites sont orthogonales, il suffit qu'une droite soit orthogonale à un plan contenant l'autre.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":73,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un élève de Bafang dessine un cube en carton pour un exposé.","tache":"Utilise le cube pour réfuter l'affirmation."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r66",{"duree":20,"titre":"Plans orthogonaux","accroche":"Un mur et le sol.","intro":"Deux plans orthogonaux se reconnaissent à leurs vecteurs normaux.","objectifs":["définir des plans orthogonaux","utiliser les vecteurs normaux","vérifier par le calcul"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Deux plans sont <strong>orthogonaux</strong> si l'un contient une droite orthogonale à l'autre ; de façon équivalente, leurs <strong>vecteurs normaux</strong> sont orthogonaux.</div>"},{"t":"Exemple","verrou":true},{"t":"Vecteur normal","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":66,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un maçon de Ngaoundéré vérifie qu'un mur d'équation x − y = 3 est orthogonal à une dalle x + y + z = 0 dans son repère.","tache":"Conclus."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r74",{"duree":20,"titre":"Plans orthogonaux : entraînement","accroche":"Trouver un paramètre.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>On écrit n⃗ · n⃗' = 0 et on résout en m.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":74,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un menuisier de Bamenda règle l'inclinaison d'un panneau dont le plan dépend d'un réglage m.","tache":"Explique comment trouver le réglage qui le rend orthogonal à la table."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r67",{"duree":20,"titre":"Droite et plan orthogonaux","accroche":"Un poteau bien vertical.","intro":"Une droite orthogonale à un plan l'est à toutes ses droites.","objectifs":["caractériser une droite orthogonale à un plan","utiliser vecteur directeur et vecteur normal","écrire un plan"],"parties":[{"t":"Théorème","html":"<div class='def'><b>Définition</b>Une droite est <strong>orthogonale à un plan</strong> si elle est orthogonale à deux droites sécantes de ce plan ; son vecteur directeur est alors colinéaire au vecteur normal.</div>"},{"t":"Exemple","verrou":true},{"t":"Écrire un plan","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":67,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"À la construction d'une antenne à Bertoua, le mât doit être orthogonal au sol d'équation z = 0.","tache":"Quelle direction doit avoir le mât ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r75",{"duree":20,"titre":"Droite et plan orthogonaux : entraînement","accroche":"Le point d'intersection, comme au Probatoire C 2026.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>On remplace la représentation paramétrique dans l'équation du plan.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":75,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un architecte de Douala vérifie qu'un pilier traverse une dalle à angle droit.","tache":"Donne les deux étapes."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r76",{"duree":20,"titre":"Repères de l'espace","accroche":"Trois coordonnées pour situer un point.","intro":"Un repère de l'espace permet de calculer avec des vecteurs.","objectifs":["lire des coordonnées","calculer une distance","tester colinéarité et coplanarité"],"parties":[{"t":"Coordonnées","html":"<div class='def'><b>Définition</b>Dans un repère (O ; i⃗, j⃗, k⃗), le vecteur AB⃗ a pour coordonnées (x_B − x_A ; y_B − y_A ; z_B − z_A). En repère orthonormé, AB = √[(x_B − x_A)² + (y_B − y_A)² + (z_B − z_A)²].</div>"},{"t":"Exemple","verrou":true},{"t":"Coplanarité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":76,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un drone de livraison à Yaoundé part de A(1 ; 2 ; 3) vers B(3 ; 0 ; 4), en centaines de mètres.","tache":"Quelle distance parcourt-il en ligne droite ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r81",{"duree":20,"titre":"Repères de l'espace : entraînement","accroche":"Quatre points coplanaires ?","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>A, B, C, D sont coplanaires si AD⃗ s'écrit αAB⃗ + βAC⃗.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":81,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un charpentier de Bafoussam vérifie que quatre fixations d'un toit sont dans un même plan.","tache":"Donne la méthode."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r77",{"duree":20,"titre":"Représentations des droites et des plans","accroche":"Paramétrique ou cartésienne.","intro":"Une droite de l'espace se décrit par un point et un vecteur ; un plan par une équation.","objectifs":["écrire une représentation paramétrique","écrire une équation cartésienne de plan","passer d'une forme à l'autre"],"parties":[{"t":"Droite","html":"<div class='def'><b>Définition</b>La droite passant par A et de vecteur directeur u⃗(a ; b ; c) a pour <strong>représentation paramétrique</strong> x = x_A + ta, y = y_A + tb, z = z_A + tc, t réel.</div>"},{"t":"Plan","verrou":true},{"t":"Vecteur normal par le calcul","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":77,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un câble est tendu à Kribi depuis A(1 ; 2 ; 0) dans la direction (1 ; 1 ; 2).","tache":"Écris une représentation paramétrique du câble."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r82",{"duree":20,"titre":"Droites et plans : entraînement","accroche":"Le plan qui contient deux droites sécantes.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Deux droites sécantes déterminent un plan.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":82,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Pour monter un auvent, un charpentier de Bafoussam fixe deux barres qui se croisent en A(1 ; 0 ; 2) : l'une de direction u(1 ; 2 ; 0), l'autre de direction v(0 ; 1 ; 1). La bâche doit être plane.","tache":"Détermine une équation cartésienne du plan de la bâche."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r79",{"duree":20,"titre":"Positions relatives de droites et de plans","accroche":"Parallèles, sécants ou confondus.","intro":"Comparer vecteurs directeurs et normaux permet de connaître la position de deux objets.","objectifs":["comparer deux plans","comparer une droite et un plan","trouver une intersection"],"parties":[{"t":"Deux plans","html":"<div class='def'><b>Définition</b>Deux plans sont <strong>parallèles</strong> si leurs vecteurs normaux sont colinéaires ; sinon ils sont <strong>sécants</strong> suivant une droite.</div>"},{"t":"Exemple","verrou":true},{"t":"Droite et plan","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":79,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Deux toits d'un hangar à Garoua ont pour équations 2x − y + z − 1 = 0 et x + y − z + 2 = 0.","tache":"Se coupent-ils ? Donne la direction du faîtage."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r86",{"duree":20,"titre":"Positions relatives : entraînement","accroche":"Le point où une droite perce un plan.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>On remplace la représentation paramétrique dans l'équation du plan.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":86,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un faisceau laser part de (1 ; 2 ; 0) dans la direction (1 ; −1 ; 3) vers un écran x + y + z = 6.","tache":"Où frappe-t-il l'écran ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r80",{"duree":20,"titre":"Distance d'un point à un plan ou à une droite","accroche":"La plus courte distance est perpendiculaire.","intro":"La distance d'un point à un plan se calcule par une formule ; celle à une droite passe par le projeté orthogonal.","objectifs":["calculer une distance à un plan","trouver un projeté orthogonal","calculer une distance à une droite"],"parties":[{"t":"Distance à un plan","html":"<div class='def'><b>Définition</b>La distance de A(x_A ; y_A ; z_A) au plan ax + by + cz + d = 0 est <strong>|ax_A + by_A + cz_A + d| / √(a² + b² + c²)</strong>.</div>"},{"t":"Exemple","verrou":true},{"t":"Distance à une droite","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":80,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Une lampe est fixée au point A(2 ; 3 ; 5) d'une salle de classe à Bafang ; un mur a pour équation x + 2y + 2z − 4 = 0, en mètres.","tache":"À quelle distance du mur est la lampe ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r87",{"duree":20,"titre":"Distances : entraînement","accroche":"Projeté sur une droite.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Le projeté H de A sur la droite (O ; u⃗) est H = t u⃗ avec t = (OA⃗ · u⃗)/‖u⃗‖².</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":87,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un poteau est au point A(1 ; 0 ; 0), et une clôture suit la droite (O ; (1 ; 1 ; 0)), en dizaines de mètres.","tache":"Calcule la distance du poteau à la clôture."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r83",{"duree":20,"titre":"Intégration : distances dans un bâtiment","accroche":"Un câble, un mur, une lampe.","intro":"Les calculs de l'espace aident à poser des équipements dans un bâtiment.","objectifs":["choisir un repère","calculer une distance","conclure sur la faisabilité"],"parties":[{"t":"Modèle","html":"<div class='def'><b>Définition</b>On place le bâtiment dans un <strong>repère orthonormé</strong> et on modélise murs et sol par des plans.</div>"},{"t":"Démarche","verrou":true},{"t":"Conclusion","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":83,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un électricien de Bafang doit relier une lampe A(2 ; 3 ; 5) au mur x + 2y + 2z − 4 = 0 avec un câble de 4 m.","tache":"Le câble suffit-il ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r84",{"duree":20,"titre":"Équation cartésienne d'une sphère","accroche":"Un ballon dans un repère.","intro":"Une sphère est l'ensemble des points situés à une même distance d'un centre.","objectifs":["écrire l'équation d'une sphère","trouver centre et rayon","tester l'appartenance d'un point"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La sphère de centre Ω(a ; b ; c) et de rayon R a pour équation <strong>(x − a)² + (y − b)² + (z − c)² = R²</strong>.</div>"},{"t":"Forme développée","verrou":true},{"t":"Appartenance","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":84,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Une cuve sphérique de château d'eau à Ngaoundéré a pour équation x² + y² + z² − 2x + 4y − 6z − 2 = 0, en mètres.","tache":"Donne son centre et son rayon."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r91",{"duree":20,"titre":"Sphères : entraînement","accroche":"Est-ce bien une sphère ?","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>x² + y² + z² + αx + βy + γz + δ = 0 est une sphère seulement si le second membre obtenu est positif.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":91,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un logiciel 3D d'un étudiant de Buea affiche une erreur pour l'équation x² + y² + z² − 2x + 6 = 0.","tache":"Explique l'erreur."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r85",{"duree":20,"titre":"Intersection d'une sphère et d'un plan","accroche":"Couper une orange.","intro":"Un plan coupe une sphère selon un cercle, la touche en un point ou l'évite.","objectifs":["comparer distance et rayon","trouver le cercle d'intersection","reconnaître un plan tangent"],"parties":[{"t":"Les trois cas","html":"<div class='def'><b>Définition</b>Soit d la distance du centre au plan. Si <strong>d &lt; R</strong>, l'intersection est un cercle de rayon √(R² − d²) ; si <strong>d = R</strong>, le plan est tangent ; si <strong>d > R</strong>, l'intersection est vide.</div>"},{"t":"Exemple","verrou":true},{"t":"Centre du cercle","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":85,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un pâtissier de Douala coupe un gâteau sphérique de rayon 5 cm à 3 cm du centre.","tache":"Quel est le rayon de la tranche obtenue ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r92",{"duree":20,"titre":"Sphère et plan : entraînement","accroche":"Calculer la distance d'abord.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>On calcule la distance du centre au plan, puis on compare au rayon.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":92,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un globe terrestre de rayon 4 dm est posé contre une étagère inclinée.","tache":"Comment savoir si l'étagère le touche en un point ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r88",{"duree":20,"titre":"Arcs capables : angle géométrique","accroche":"Voir un segment sous le même angle.","intro":"L'ensemble des points d'où l'on voit un segment sous un angle donné est formé d'arcs de cercle.","objectifs":["reconnaître un arc capable","construire son centre","traiter le cas de l'angle droit"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Pour 0 &lt; α &lt; π, l'ensemble des points M tels que l'angle géométrique AMB = α est la réunion de deux <strong>arcs capables</strong> symétriques par rapport à (AB), privés de A et B.</div>"},{"t":"Cas de l'angle droit","verrou":true},{"t":"Construction","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":88,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un photographe de Limbé veut voir les deux extrémités d'une façade sous un angle de 90°.","tache":"Où peut-il se placer ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r93",{"duree":20,"titre":"Arcs capables : entraînement","accroche":"Construire le centre d'un arc.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>La tangente en A à l'arc capable fait avec (AB) un angle égal à α.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":93,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un architecte de Yaoundé veut que la scène soit vue sous un angle de 60° depuis chaque siège d'un arc de gradins.","tache":"Quelle courbe suivent les gradins ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r89",{"duree":20,"titre":"Arcs capables : angle orienté modulo 2π","accroche":"Un seul arc quand le sens compte.","intro":"Avec un angle orienté (MA⃗, MB⃗) = α + 2kπ, on obtient un seul arc.","objectifs":["distinguer angle géométrique et angle orienté","déterminer l'arc","traiter les cas particuliers"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Pour α non multiple de π, l'ensemble des points M tels que <strong>(MA⃗, MB⃗) = α + 2kπ</strong> est un <strong>arc de cercle</strong> d'extrémités A et B, privé de A et B.</div>"},{"t":"Cas particuliers","verrou":true},{"t":"Choix de l'arc","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":89,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un robot de nettoyage d'une salle de Bertoua doit voir deux balises A et B sous un angle orienté de π/2.","tache":"Décris sa trajectoire possible."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r90",{"duree":20,"titre":"Arcs capables : angle orienté modulo π","accroche":"Le cercle entier réapparaît.","intro":"Avec un angle de droites, défini modulo π, on obtient le cercle complet privé de A et B.","objectifs":["comprendre le modulo π","déterminer l'ensemble","comparer avec le modulo 2π"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Pour α non multiple de π, l'ensemble des points M tels que <strong>(MA⃗, MB⃗) = α + kπ</strong> est un <strong>cercle</strong> passant par A et B, privé de A et B.</div>"},{"t":"Comparaison","verrou":true},{"t":"Cas particulier","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":90,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Deux bornes A(0 ; 0) et B(6 ; 0) délimitent l'entrée d'une cour à Kumba. Le gardien veut savoir où il peut se placer pour voir l'entrée sous un angle droit.","tache":"Détermine l'ensemble des points M tels que (MA, MB) = π/2 + kπ."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r94",{"duree":20,"titre":"Arcs capables orientés : entraînement","accroche":"Choisir le bon modulo.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Angle de vecteurs : modulo 2π, un arc. Angle de droites : modulo π, un cercle.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":94,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Deux balises sont en A(0 ; 0) et B(4 ; 0) sur un terrain de Kumba.","tache":"Où doit se placer un observateur pour les voir sous un angle orienté droit ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r71",{"duree":20,"titre":"Présentation du concept de graphe","accroche":"Des points et des liens.","intro":"Un graphe modélise des relations : routes entre villes, amitiés, vols.","objectifs":["définir sommets et arêtes","reconnaître un graphe simple","reconnaître un graphe complet"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Un <strong>graphe</strong> est formé de <strong>sommets</strong> reliés par des <strong>arêtes</strong>. Son <strong>ordre</strong> est le nombre de sommets.</div>"},{"t":"Graphe simple et complet","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":71,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Ali, à Yaoundé, veut inviter 5 amis, dont certains ne s'entendent pas : A avec D ; B avec C, D, E ; D avec E.","tache":"Représente la situation par un graphe."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r78",{"duree":20,"titre":"Graphes : entraînement","accroche":"La fête réussie du Probatoire D-TI 2026.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Des invités sans conflit forment un ensemble de sommets deux à deux non adjacents.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":78,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Ali prépare son anniversaire à Mbalmayo et veut une fête sans dispute.","tache":"Quels amis inviter ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r72",{"duree":20,"titre":"Nombre d'arêtes et somme des degrés","accroche":"Chaque arête compte deux fois.","intro":"La somme des degrés est toujours le double du nombre d'arêtes.","objectifs":["calculer un degré","utiliser la formule des degrés","compter les arêtes d'un graphe complet"],"parties":[{"t":"Théorème","html":"<div class='def'><b>Définition</b>Le <strong>degré</strong> d'un sommet est le nombre d'arêtes qui y aboutissent. <strong>La somme des degrés est égale au double du nombre d'arêtes.</strong></div>"},{"t":"Conséquence","verrou":true},{"t":"Graphe complet","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":72,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Une compagnie aérienne veut relier 5 villes du Cameroun deux à deux.","tache":"Combien de vols aller simple doit-elle prévoir ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-maths-r95",{"duree":20,"titre":"Degrés : entraînement","accroche":"Vérifier un graphe donné.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>La somme des degrés doit être paire.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"maths","rang":95,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un club de lecture de Garoua représente ses rencontres par un graphe.","tache":"Comment vérifier le comptage des rencontres ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-physique-r01",{"duree":20,"titre":"Mesures et incertitudes","accroche":"Aucune mesure n'est parfaite.","intro":"Toute mesure s'accompagne d'une incertitude. Savoir l'évaluer, c'est savoir quelle confiance accorder au résultat.","objectifs":["utiliser les unités du Système international","évaluer une incertitude","écrire un résultat correctement"],"parties":[{"t":"Mesure et incertitude","html":"<div class='def'><b>Définition</b>Le résultat d'une mesure s'écrit <strong>x = x̄ ± U</strong>, où U est l'<strong>incertitude</strong>, avec l'unité. L'incertitude relative vaut U/x̄.</div>"},{"t":"Série de mesures","html":"<p>Pour n mesures répétées de moyenne x̄ et d'écart type σ, l'incertitude vaut U = k·σ/√n, k étant le facteur d'élargissement.</p><p class='formule'>n = 12, σ = 0,27 cm, k = 2,18 : U = 2,18 × 0,27/√12 ≈ 0,17 cm</p>","labo":{"type":"calcul","f":"incert","vals":{"x":20,"d":0.5}}},{"t":"Écrire le résultat","html":"<p>f' = (10,41 ± 0,17) cm. On arrondit l'incertitude à deux chiffres significatifs au plus, et la valeur au même rang.</p>","retenir":"Valeur, incertitude, unité."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Vérification des savoirs.</strong> Toute mesure est entachée :</p><ol type='a'><li>d'aucune erreur</li><li>d'une erreur toujours nulle</li><li>d'une erreur connue exactement</li><li>d'une incertitude</li></ol><details><summary>Voir la réponse</summary><p><strong>d'une incertitude</strong>. On ne connaît jamais la valeur vraie.</p></details><p><strong>Application directe des savoirs.</strong></p><p>Une longueur vaut 20 cm à 0,5 cm près : incertitude relative ?</p><details><summary>Voir la réponse</summary><p>(Réponse : 2,5 %.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Pour vérifier un pendule de laboratoire, deux groupes du lycée de Mbouda mesurent sa période. Groupe A : 10 mesures, moyenne 1,52 s, écart type 0,04 s (k = 2,26). Groupe B : 5 mesures, moyenne 1,49 s, écart type 0,06 s (k = 2,78).</p><p><strong>Consigne 1.</strong> Écris le résultat de chaque groupe avec son incertitude.</p><p><strong>Consigne 2.</strong> Les deux résultats sont-ils compatibles ? Justifie.</p><details><summary>Voir une réponse attendue</summary><p>U_A = 2,26 × 0,04/√10 ≈ 0,03 s : T = (1,52 ± 0,03) s. U_B = 2,78 × 0,06/√5 ≈ 0,07 s : T = (1,49 ± 0,07) s. Les intervalles [1,49 ; 1,55] et [1,42 ; 1,56] se chevauchent : les résultats sont compatibles.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans la démarche expérimentale."}],"revision":["x = x̄ ± U.","U = kσ/√n.","Arrondir au même rang."],"exo":"<p>Une longueur vaut 20 cm à 0,5 cm près : incertitude relative ? <em>(Réponse : 2,5 %.)</em></p>","quiz":[{"q":"Toute mesure est entachée :","r":["d'aucune erreur","d'une erreur toujours nulle","d'une erreur connue exactement","d'une incertitude"],"b":3,"e":"On ne connaît jamais la valeur vraie."},{"q":"Le résultat d'une mesure s'écrit :","r":["valeur ± incertitude, avec l'unité","valeur seule, avec tous les chiffres affichés","incertitude seule","valeur ± incertitude, sans unité"],"b":0,"e":"Ex. : T = (1,52 ± 0,03) s."},{"q":"L'erreur systématique est :","r":["une erreur au hasard","une erreur qui décale toutes les mesures dans le même sens","une erreur nulle","une erreur de calcul commise par l'opérateur lors de la conversion"],"b":1,"e":"Ex. : un appareil mal étalonné."},{"q":"L'erreur aléatoire :","r":["est toujours dans le même sens, d'une mesure à l'autre","est nulle","varie au hasard d'une mesure à l'autre","disparaît avec un appareil faux"],"b":2,"e":"On la réduit en multipliant les mesures."},{"q":"Pour réduire l'incertitude aléatoire, on :","r":["fait une seule mesure","change d'unité","arrondit au hasard chaque résultat obtenu","répète la mesure et on calcule la moyenne"],"b":3,"e":"L'incertitude de la moyenne diminue avec le nombre de mesures."},{"q":"L'incertitude relative de (2,00 ± 0,04) m vaut :","r":["2 %","4 %","0,04 %","0,5 %"],"b":0,"e":"0,04 / 2,00 = 0,02."},{"q":"Deux résultats sont compatibles si :","r":["leurs valeurs sont identiques","leurs intervalles d'incertitude se chevauchent","leurs unités diffèrent","l'un est plus grand que l'autre, à l'unité près"],"b":1,"e":"Ils peuvent correspondre à la même valeur vraie."},{"q":"Le nombre de chiffres significatifs de 0,0350 est :","r":["4","5","3","2"],"b":2,"e":"Les zéros de tête ne comptent pas."},{"q":"L'incertitude d'une moyenne vaut U = k × σ / √n. Si n augmente :","r":["U augmente","U ne change pas","U devient négatif","U diminue"],"b":3,"e":"Le dénominateur √n grandit."},{"q":"La précision d'un appareil est liée :","r":["à sa plus petite graduation","à sa couleur","à son prix","à la taille totale de l'instrument"],"b":0,"e":"On ne lit pas mieux que la graduation."}],"c":"1re C","m":"physique","rang":1,"apc":{"module":"Mesures, énergie mécanique et chaleur","famille":"Utilisation rationnelle de l'énergie","agir":"Évaluer et économiser l'énergie dans les activités quotidiennes","situation":"Au laboratoire du lycée de Mbouda, douze groupes mesurent la distance focale d'une même lentille et obtiennent une moyenne de 10,41 cm avec un écart type de 0,27 cm.","tache":"Présente le résultat avec son incertitude (k = 2,18)."},"gratuit":true});
VRT_L("1re-c-physique-r02",{"duree":20,"titre":"Notion de modèle","accroche":"Une représentation simplifiée du réel.","intro":"Les physiciens remplacent le réel par des modèles qui permettent de prévoir.","objectifs":["définir un modèle","donner des exemples","connaître les limites d'un modèle"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Un <strong>modèle</strong> est une représentation simplifiée d'un phénomène, qui permet de l'expliquer et de prévoir son évolution dans un <strong>domaine de validité</strong>.</div>"},{"t":"Exemples","verrou":true},{"t":"Limites","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"physique","rang":2,"apc":{"module":"Mesures, énergie mécanique et chaleur","famille":"Utilisation rationnelle de l'énergie","agir":"Évaluer et économiser l'énergie dans les activités quotidiennes","situation":"Un élève de Garoua modélise le ballon de football par un point pour calculer sa trajectoire.","tache":"Ce modèle permet-il d'étudier l'effet donné au ballon ? Justifie."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-physique-r03",{"duree":20,"titre":"Travail d'une force","accroche":"Une force qui déplace son point d'application travaille.","intro":"Le travail mesure l'énergie transférée par une force lors d'un déplacement.","objectifs":["calculer le travail d'une force constante","calculer le travail du poids","calculer le travail d'un couple"],"parties":[{"t":"Force constante","html":"<div class='def'><b>Définition</b>Le <strong>travail</strong> d'une force constante F⃗ sur un déplacement AB⃗ est <strong>W = F × AB × cos α</strong>, en joules (J). Il est moteur si W > 0, résistant si W &lt; 0.</div>"},{"t":"Poids et ressort","verrou":true},{"t":"Couple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"physique","rang":3,"apc":{"module":"Mesures, énergie mécanique et chaleur","famille":"Utilisation rationnelle de l'énergie","agir":"Évaluer et économiser l'énergie dans les activités quotidiennes","situation":"Un pousseur du marché de Mokolo tire son chariot avec une force de 50 N inclinée de 30° sur 10 m.","tache":"Calcule le travail fourni."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-physique-r04",{"duree":20,"titre":"Puissance d'une force","accroche":"Le même travail, plus ou moins vite.","intro":"La puissance mesure la rapidité avec laquelle une force effectue un travail.","objectifs":["définir la puissance","utiliser P = F·v","calculer la puissance d'un couple"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>puissance moyenne</strong> est P = W/Δt, en watts (W). Pour une force constante, la puissance instantanée vaut <strong>P = F × v × cos α</strong>.</div>"},{"t":"Couple","verrou":true},{"t":"Unités","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"physique","rang":4,"apc":{"module":"Mesures, énergie mécanique et chaleur","famille":"Utilisation rationnelle de l'énergie","agir":"Évaluer et économiser l'énergie dans les activités quotidiennes","situation":"Le moteur d'une moulinette à maïs d'une meunière de Bafoussam exerce un couple de 20 N·m à 1 500 tr/min.","tache":"Quelle est sa puissance mécanique ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-physique-r05",{"duree":20,"titre":"Énergie cinétique et théorème de l'énergie cinétique","accroche":"Plus on va vite, plus il faut freiner longtemps.","intro":"L'énergie cinétique dépend de la masse et du carré de la vitesse. Le théorème relie sa variation aux travaux des forces.","objectifs":["calculer une énergie cinétique","énoncer le théorème","calculer une distance de freinage"],"parties":[{"t":"Énergie cinétique","html":"<div class='def'><b>Définition</b>Un solide de masse m en translation à la vitesse v possède l'<strong>énergie cinétique</strong> Ec = ½mv², en joules.</div>"},{"t":"Le théorème","verrou":true},{"t":"Freinage","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"physique","rang":5,"apc":{"module":"Mesures, énergie mécanique et chaleur","famille":"Utilisation rationnelle de l'énergie","agir":"Évaluer et économiser l'énergie dans les activités quotidiennes","situation":"Sur l'axe Douala-Yaoundé, un car de 1 000 kg roulant à 72 km/h freine avec une force de 5 000 N.","tache":"Quelle distance lui faut-il pour s'arrêter ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-physique-r06",{"duree":20,"titre":"Énergie potentielle","accroche":"De l'énergie en réserve.","intro":"Un solide en hauteur ou un ressort comprimé stockent de l'énergie potentielle.","objectifs":["calculer l'énergie potentielle de pesanteur","choisir une référence","calculer l'énergie élastique"],"parties":[{"t":"Pesanteur","html":"<div class='def'><b>Définition</b>L'<strong>énergie potentielle de pesanteur</strong> vaut Ep = mgz + constante, z étant l'altitude comptée sur un axe vertical vers le haut ; on choisit souvent Ep = 0 au niveau de référence.</div>"},{"t":"Exemple","verrou":true},{"t":"Élastique","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"physique","rang":6,"apc":{"module":"Mesures, énergie mécanique et chaleur","famille":"Utilisation rationnelle de l'énergie","agir":"Évaluer et économiser l'énergie dans les activités quotidiennes","situation":"Un ouvrier de Kribi hisse un sac de ciment de 50 kg sur un échafaudage de 2 m.","tache":"Quelle énergie potentielle le sac a-t-il gagnée ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-physique-r07",{"duree":20,"titre":"Énergie mécanique et sa conservation","accroche":"Sans frottement, rien ne se perd.","intro":"L'énergie mécanique se conserve si seules des forces conservatives travaillent.","objectifs":["définir l'énergie mécanique","appliquer la conservation","tenir compte des frottements"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>L'<strong>énergie mécanique</strong> est Em = Ec + Ep. En l'absence de frottements, elle se <strong>conserve</strong>.</div>"},{"t":"Chute libre","verrou":true},{"t":"Frottements","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"physique","rang":7,"apc":{"module":"Mesures, énergie mécanique et chaleur","famille":"Utilisation rationnelle de l'énergie","agir":"Évaluer et économiser l'énergie dans les activités quotidiennes","situation":"Un enfant de Limbé descend un toboggan de 2 m de haut ; il arrive en bas à 5 m/s.","tache":"Montre que des frottements ont agi."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-physique-r08",{"duree":20,"titre":"La chaleur et ses modes de transfert","accroche":"Conduction, convection, rayonnement.","intro":"La chaleur est un transfert d'énergie qui va spontanément du corps chaud vers le corps froid.","objectifs":["distinguer chaleur et température","citer les modes de transfert","calculer une quantité de chaleur"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>chaleur</strong> Q est l'énergie transférée d'un corps chaud à un corps froid. Sans changement d'état, <strong>Q = m·c·Δθ</strong>, c étant la chaleur massique.</div>"},{"t":"Modes de transfert","verrou":true},{"t":"Changement d'état","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"physique","rang":8,"apc":{"module":"Mesures, énergie mécanique et chaleur","famille":"Utilisation rationnelle de l'énergie","agir":"Évaluer et économiser l'énergie dans les activités quotidiennes","situation":"Une vendeuse de bouillie de Ngaoundéré chauffe 2 kg d'eau de 25 °C à 100 °C (c = 4 190 J/kg/°C).","tache":"Calcule l'énergie nécessaire."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-physique-r09",{"duree":20,"titre":"Calorimétrie et échanges de chaleur","accroche":"Dans un calorimètre, rien ne s'échappe.","intro":"Le calorimètre isole un système pour mesurer les échanges de chaleur.","objectifs":["énoncer le principe des échanges","trouver une température d'équilibre","mesurer une chaleur massique"],"parties":[{"t":"Principe","html":"<div class='def'><b>Définition</b>Dans un <strong>calorimètre</strong> isolé, la somme des quantités de chaleur échangées est nulle : <strong>ΣQ = 0</strong>, c'est-à-dire chaleur cédée = chaleur reçue.</div>"},{"t":"Exemple","verrou":true},{"t":"Capacité du calorimètre","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"physique","rang":9,"apc":{"module":"Mesures, énergie mécanique et chaleur","famille":"Utilisation rationnelle de l'énergie","agir":"Évaluer et économiser l'énergie dans les activités quotidiennes","situation":"Pour estimer la température du foyer d'un forgeron de Foumban, on plonge un morceau de fer chauffé dans de l'eau d'un calorimètre.","tache":"Explique la démarche."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-physique-r10",{"duree":20,"titre":"Lentilles minces : caractéristiques","accroche":"Converger ou diverger.","intro":"Une lentille mince dévie la lumière ; ses foyers et sa vergence la caractérisent.","objectifs":["distinguer les lentilles","définir foyers et distance focale","calculer une vergence"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>Une <strong>lentille mince</strong> convergente a des bords minces ; une divergente, des bords épais. La <strong>vergence</strong> vaut C = 1/f', en dioptries (δ), f' étant en mètres : C > 0 pour une convergente.</div>"},{"t":"Les rayons particuliers","html":"<ul><li>Un rayon passant par le centre optique O n'est pas dévié.</li><li>Un rayon parallèle à l'axe émerge en passant par F'.</li><li>Un rayon passant par F émerge parallèle à l'axe.</li></ul>","labo":{"type":"lentille","f":10,"oa":-30}},{"t":"Vergences","html":"<p>C = (n − 1)(1/R₁ − 1/R₂). Lentille biconvexe, R = 5 cm, n = 1,5 : C = 20 δ, f' = 5 cm. Lentilles accolées : C = C₁ + C₂ (théorème des vergences).</p>","retenir":"C = 1/f' en dioptries."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Vérification des savoirs.</strong> Une lentille convergente est :</p><ol type='a'><li>plus mince au centre qu'aux bords</li><li>plus épaisse au centre qu'aux bords</li><li>plate</li><li>opaque</li></ol><details><summary>Voir la réponse</summary><p><strong>plus épaisse au centre qu'aux bords</strong>. Elle fait converger les rayons.</p></details><p><strong>Application directe des savoirs.</strong></p><p>Vergence d'une lentille de f' = 20 cm ?</p><details><summary>Voir la réponse</summary><p>(Réponse : 5 δ.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Un opticien du marché Central dispose de trois lentilles : L₁ de vergence +5 δ, L₂ de vergence −4 δ, et L₃ biconvexe en verre d'indice 1,5 dont les deux faces ont un rayon de courbure de 10 cm.</p><p><strong>Consigne 1.</strong> Calcule la distance focale de chaque lentille et donne sa nature.</p><p><strong>Consigne 2.</strong> Laquelle choisir pour fabriquer une loupe ? Justifie.</p><details><summary>Voir une réponse attendue</summary><p>L₁ : f' = 20 cm, convergente. L₂ : f' = −25 cm, divergente. L₃ : C = (1,5 − 1)(1/0,1 + 1/0,1) = 10 δ, f' = 10 cm, convergente. Pour une loupe, on choisit la convergente la plus puissante : L₃.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans la démarche expérimentale."}],"revision":["Convergente ou divergente.","Rayons particuliers.","C = 1/f'."],"exo":"<p>Vergence d'une lentille de f' = 20 cm ? <em>(Réponse : 5 δ.)</em></p>","quiz":[{"q":"Une lentille convergente est :","r":["plus mince au centre qu'aux bords","plus épaisse au centre qu'aux bords","plate","opaque"],"b":1,"e":"Elle fait converger les rayons."},{"q":"Le foyer image F' d'une lentille convergente est :","r":["le centre optique, par lequel les rayons passent sans déviation","un point de l'objet","le point où convergent les rayons parallèles à l'axe","le bord de la lentille"],"b":2,"e":"Il est situé après la lentille."},{"q":"La vergence C d'une lentille vaut :","r":["f'","f' × 2","f' / 2","1 / f'"],"b":3,"e":"f' en mètres, C en dioptries."},{"q":"Une lentille de distance focale 0,1 m a une vergence de :","r":["10 δ","0,1 δ","1 δ","100 δ"],"b":0,"e":"C = 1 / f' = 1 / 0,1 = 10 dioptries."},{"q":"Une lentille divergente a une vergence :","r":["positive","négative","nulle","infinie"],"b":1,"e":"Sa distance focale est négative."},{"q":"Un rayon passant par le centre optique :","r":["est dévié vers le foyer","est réfléchi","n'est pas dévié","est absorbé"],"b":2,"e":"Propriété du centre optique."},{"q":"Un rayon passant par le foyer objet F ressort :","r":["par le centre","vers le foyer objet","perpendiculaire à l'axe","parallèle à l'axe optique"],"b":3,"e":"Principe du retour inverse."},{"q":"L'unité de la vergence est :","r":["la dioptrie (δ)","le mètre (m)","le watt","le degré"],"b":0,"e":"La vergence est l'inverse d'une longueur : 1 δ = 1 m⁻¹."},{"q":"Plus une lentille est bombée :","r":["moins elle est convergente","plus elle est convergente","plus elle est divergente","rien ne change"],"b":1,"e":"Sa distance focale diminue."},{"q":"La loupe est :","r":["une lentille divergente","un miroir plan","une lentille convergente","un prisme"],"b":2,"e":"Elle grossit les objets proches."}],"c":"1re C","m":"physique","rang":10,"apc":{"module":"Optique et lumière","famille":"Protection et amélioration de la vision","agir":"Choisir et utiliser des instruments d'optique","situation":"Un réparateur de lunettes du marché Central reçoit une lentille sans étiquette.","tache":"Comment savoir si elle est convergente ?"},"gratuit":true});
VRT_L("1re-c-physique-r11",{"duree":20,"titre":"Image donnée par une lentille et relation de conjugaison","accroche":"Calculer où se forme l'image.","intro":"La relation de conjugaison et le grandissement donnent la position et la taille de l'image.","objectifs":["construire une image","appliquer la relation de conjugaison","calculer le grandissement"],"parties":[{"t":"Conjugaison","html":"<div class='def'><b>Définition</b>Avec des distances algébriques mesurées depuis O : <strong>1/OA' − 1/OA = 1/f'</strong>. Le <strong>grandissement</strong> vaut γ = A'B'/AB = OA'/OA.</div>"},{"t":"Exemple","verrou":true},{"t":"Construction","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"physique","rang":11,"apc":{"module":"Optique et lumière","famille":"Protection et amélioration de la vision","agir":"Choisir et utiliser des instruments d'optique","situation":"Un photographe de Douala place un sujet à 30 cm d'un objectif de distance focale 10 cm.","tache":"Où mettre le capteur ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-physique-r12",{"duree":20,"titre":"L'œil et ses défauts","accroche":"Accommoder, corriger.","intro":"L'œil se comporte comme une lentille convergente de vergence variable devant un écran, la rétine.","objectifs":["décrire l'œil réduit","définir PP et PR","corriger myopie et hypermétropie"],"parties":[{"t":"L'œil réduit","html":"<div class='def'><b>Définition</b>L'<strong>œil réduit</strong> est modélisé par une lentille convergente (cristallin) placée devant un écran fixe (rétine). L'<strong>accommodation</strong> modifie sa vergence pour garder l'image nette.</div>"},{"t":"Défauts","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"physique","rang":12,"apc":{"module":"Optique et lumière","famille":"Protection et amélioration de la vision","agir":"Choisir et utiliser des instruments d'optique","situation":"Un élève de Bertoua voit mal le tableau du fond de la classe ; l'ophtalmologue mesure son PR à 2 m.","tache":"Identifie le défaut et propose une correction."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-physique-r13",{"duree":20,"titre":"La loupe","accroche":"Voir plus grand ce qui est petit.","intro":"La loupe est une lentille convergente de courte distance focale.","objectifs":["expliquer le fonctionnement","définir puissance et grossissement","calculer"],"parties":[{"t":"Principe","html":"<div class='def'><b>Définition</b>La <strong>loupe</strong> est une lentille convergente de petite distance focale. L'objet placé entre le foyer F et O en donne une image <strong>virtuelle, droite et agrandie</strong>.</div>"},{"t":"Puissance et grossissement","verrou":true},{"t":"Usage","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"physique","rang":13,"apc":{"module":"Optique et lumière","famille":"Protection et amélioration de la vision","agir":"Choisir et utiliser des instruments d'optique","situation":"Un horloger du marché de Mokolo utilise une loupe de distance focale 5 cm.","tache":"Calcule sa puissance intrinsèque et son grossissement commercial."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-physique-r14",{"duree":20,"titre":"La lunette astronomique et le télescope","accroche":"Regarder la Lune depuis la cour du lycée.","intro":"Lunette et télescope donnent une image agrandie d'objets très éloignés.","objectifs":["décrire une lunette afocale","calculer le grossissement","décrire le télescope de Newton"],"parties":[{"t":"La lunette","html":"<div class='def'><b>Définition</b>Une <strong>lunette astronomique</strong> associe un objectif de grande distance focale f₁ et un oculaire de petite distance focale f₂. Elle est <strong>afocale</strong> si F₁' et F₂ sont confondus : O₁O₂ = f₁ + f₂.</div>"},{"t":"Grossissement","verrou":true},{"t":"Le télescope de Newton","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"physique","rang":14,"apc":{"module":"Optique et lumière","famille":"Protection et amélioration de la vision","agir":"Choisir et utiliser des instruments d'optique","situation":"Le club d'astronomie d'un lycée de Maroua veut observer Jupiter avec une lunette de f₁ = 1 m et f₂ = 5 cm.","tache":"Calcule la longueur de la lunette et son grossissement."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-physique-r15",{"duree":20,"titre":"Puissance et grossissement d'un instrument","accroche":"Comparer des instruments d'optique.","intro":"Puissance et grossissement permettent de comparer les instruments.","objectifs":["définir la puissance","définir le grossissement","calculer le diamètre apparent"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>La <strong>puissance</strong> d'un instrument est P = α'/AB (δ), α' étant l'angle sous lequel on voit l'image. Le <strong>grossissement</strong> est G = α'/α, α étant l'angle sous lequel on verrait l'objet à l'œil nu.</div>"},{"t":"Grossissement commercial","verrou":true},{"t":"Diamètre apparent","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"physique","rang":15,"apc":{"module":"Optique et lumière","famille":"Protection et amélioration de la vision","agir":"Choisir et utiliser des instruments d'optique","situation":"Un vendeur du marché Mboppi propose deux loupes : 10 δ et 20 δ.","tache":"Laquelle grossit le plus ? Justifie."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-physique-r16",{"duree":20,"titre":"Spectres lumineux","accroche":"La lumière blanche contient toutes les couleurs.","intro":"Un prisme décompose la lumière ; le spectre renseigne sur la source et sur la matière traversée.","objectifs":["décrire le spectre de la lumière blanche","distinguer émission et absorption","situer le visible parmi les ondes"],"parties":[{"t":"Spectres","html":"<div class='def'><b>Définition</b>Un <strong>spectre d'émission</strong> est formé de raies colorées sur fond noir ; un <strong>spectre d'absorption</strong>, de raies noires sur le fond coloré du spectre continu.</div>"},{"t":"Ondes électromagnétiques","verrou":true},{"t":"Température et couleur","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"physique","rang":16,"apc":{"module":"Optique et lumière","famille":"Protection et amélioration de la vision","agir":"Choisir et utiliser des instruments d'optique","situation":"Un forgeron de Bamessing chauffe une barre d'acier jusqu'à ce qu'elle devienne orange (λ ≈ 600 nm).","tache":"Estime sa température."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-physique-r17",{"duree":20,"titre":"Interaction lumière-matière","accroche":"Un photon, un saut d'énergie.","intro":"La lumière échange de l'énergie avec la matière par paquets : les photons.","objectifs":["calculer l'énergie d'un photon","interpréter une transition","distinguer émission et absorption"],"parties":[{"t":"Le photon","html":"<div class='def'><b>Définition</b>La lumière de fréquence ν est formée de <strong>photons</strong> d'énergie <strong>E = hν = hc/λ</strong>, h = 6,62 × 10⁻³⁴ J·s. En pratique : E (eV) ≈ 1 240/λ (nm).</div>"},{"t":"Transitions","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"physique","rang":17,"apc":{"module":"Optique et lumière","famille":"Protection et amélioration de la vision","agir":"Choisir et utiliser des instruments d'optique","situation":"Les lampes à vapeur de sodium des carrefours de Douala émettent une lumière jaune-orange de 589 nm.","tache":"Calcule l'énergie d'un photon émis."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-physique-r18",{"duree":20,"titre":"Les générateurs électriques","accroche":"La pile ne délivre pas toute sa f.é.m.","intro":"Un générateur réel a une force électromotrice et une résistance interne.","objectifs":["schématiser un générateur","appliquer U = E − rI","associer des générateurs"],"parties":[{"t":"Caractéristique","html":"<div class='def'><b>Définition</b>Un générateur linéaire a pour caractéristique <strong>U = E − rI</strong>, E étant sa force électromotrice (V) et r sa résistance interne (Ω).</div>"},{"t":"Associations","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"physique","rang":18,"apc":{"module":"Électricité et électromagnétisme","famille":"Utilisation rationnelle de l'énergie électrique","agir":"Exploiter des générateurs et des récepteurs avec un bon rendement","situation":"Un réparateur de radios de Bafang associe 4 piles de 1,5 V en série pour un poste.","tache":"Calcule la f.é.m. obtenue."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-physique-r19",{"duree":20,"titre":"Les récepteurs électriques","accroche":"Moteurs et électrolyseurs ont une f.c.é.m.","intro":"Un récepteur actif convertit l'énergie électrique en une autre forme que la chaleur.","objectifs":["schématiser un récepteur","appliquer U = E' + r'I","distinguer récepteurs passifs et actifs"],"parties":[{"t":"Caractéristique","html":"<div class='def'><b>Définition</b>Un récepteur actif linéaire (moteur, électrolyseur) vérifie <strong>U = E' + r'I</strong>, E' étant sa force contre-électromotrice.</div>"},{"t":"Récepteurs passifs","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"physique","rang":19,"apc":{"module":"Électricité et électromagnétisme","famille":"Utilisation rationnelle de l'énergie électrique","agir":"Exploiter des générateurs et des récepteurs avec un bon rendement","situation":"Un ventilateur alimenté par un panneau solaire à Maroua a une f.c.é.m. de 6 V et une résistance interne de 2 Ω.","tache":"Calcule la tension à ses bornes pour 0,5 A."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-physique-r20",{"duree":20,"titre":"Point de fonctionnement d'un circuit","accroche":"Là où générateur et récepteur s'accordent.","intro":"Le point de fonctionnement est l'intersection des caractéristiques du générateur et du récepteur.","objectifs":["trouver graphiquement le point","appliquer la loi de Pouillet","exploiter la caractéristique d'une diode"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>point de fonctionnement</strong> d'un circuit est le point (I ; U) commun aux caractéristiques du générateur et du récepteur.</div>"},{"t":"Loi de Pouillet","verrou":true},{"t":"Diode","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"physique","rang":20,"apc":{"module":"Électricité et électromagnétisme","famille":"Utilisation rationnelle de l'énergie électrique","agir":"Exploiter des générateurs et des récepteurs avec un bon rendement","situation":"Une lampe de chantier à Edéa, de résistance 10 Ω, est branchée sur une batterie de 12 V et 2 Ω.","tache":"Détermine le point de fonctionnement."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-physique-r21",{"duree":20,"titre":"Champ magnétique et flux magnétique","accroche":"Compter les lignes de champ qui traversent une bobine.","intro":"Le flux magnétique mesure la quantité de champ qui traverse une surface.","objectifs":["décrire un champ magnétique","calculer le champ d'un solénoïde","calculer un flux"],"parties":[{"t":"Champ magnétique","html":"<div class='def'><b>Définition</b>Le <strong>champ magnétique</strong> B⃗ se mesure en teslas (T) au teslamètre. Dans un solénoïde long : B = μ₀NI/L, μ₀ = 4π × 10⁻⁷ SI.</div>"},{"t":"Flux","html":"<p class='formule'>Φ = N × B × S × cos θ (en webers, Wb)</p><p>θ est l'angle entre B⃗ et la normale à la spire.</p>","labo":{"type":"calcul","f":"filb","vals":{"I":10,"d":2}}},{"t":"Exemple","html":"<p>100 spires de 50 cm² dans B = 0,2 T, normale parallèle à B⃗ : Φ = 100 × 0,2 × 0,005 = 0,1 Wb.</p>","retenir":"Flux maximal pour θ = 0."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Vérification des savoirs.</strong> Le champ magnétique s'exprime en :</p><ol type='a'><li>webers</li><li>teslas</li><li>volts</li><li>ampères</li></ol><details><summary>Voir la réponse</summary><p><strong>teslas</strong>. L'unité du champ magnétique est le tesla, de symbole T.</p></details><p><strong>Application directe des savoirs.</strong></p><p>Flux pour θ = 90° ?</p><details><summary>Voir la réponse</summary><p>(Réponse : 0.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Une bobine de 200 spires de rayon 3 cm est placée dans un champ magnétique uniforme de 0,05 T, sa normale parallèle au champ.</p><p><strong>Consigne 1.</strong> Calcule le flux magnétique maximal.</p><p><strong>Consigne 2.</strong> Calcule le flux quand la bobine a tourné de 60°.</p><details><summary>Voir une réponse attendue</summary><p>S = π × 0,03² ≈ 2,83 × 10⁻³ m² ; Φ = 200 × 0,05 × 2,83 × 10⁻³ ≈ 2,8 × 10⁻² Wb. À 60° : Φ ≈ 1,4 × 10⁻² Wb.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans la démarche expérimentale."}],"revision":["Tesla.","Solénoïde.","Φ = NBS cos θ."],"exo":"<p>Flux pour θ = 90° ? <em>(Réponse : 0.)</em></p>","quiz":[{"q":"Le champ magnétique s'exprime en :","r":["webers","teslas","volts","ampères"],"b":1,"e":"L'unité du champ magnétique est le tesla, de symbole T."},{"q":"Le flux magnétique à travers une surface vaut :","r":["Φ = B / S","Φ = B + S","Φ = B S cos θ","Φ = S / B"],"b":2,"e":"θ angle entre B et la normale."},{"q":"Le flux s'exprime en :","r":["teslas","henrys","ohms","webers"],"b":3,"e":"Le flux s'exprime en webers : 1 Wb = 1 T·m²."},{"q":"Le flux est maximal quand le champ est :","r":["perpendiculaire à la surface","parallèle à la surface du circuit","nul","variable"],"b":0,"e":"θ = 0 entre B et la normale."},{"q":"Le flux est nul quand le champ est :","r":["perpendiculaire à la surface","parallèle à la surface","très intense","uniforme"],"b":1,"e":"Aucune ligne ne traverse la surface."},{"q":"Une bobine de 100 spires de 10 cm² dans un champ de 0,2 T normal : flux total :","r":["2 Wb","0,2 Wb","0,02 Wb","200 Wb"],"b":2,"e":"N B S = 100 × 0,2 × 10⁻³."},{"q":"Les lignes de champ d'un aimant droit sortent :","r":["par le pôle sud","par le milieu","de nulle part","par le pôle nord"],"b":3,"e":"Elles rentrent par le pôle sud."},{"q":"Un solénoïde parcouru par un courant crée à l'intérieur :","r":["un champ uniforme","aucun champ","un champ très variable","un champ électrique seulement"],"b":0,"e":"Parallèle à son axe."},{"q":"Le champ dans un solénoïde vaut :","r":["μ₀ / (n I)","μ₀ n I","n / I","I / n"],"b":1,"e":"n est le nombre de spires par mètre."},{"q":"Une boussole s'oriente selon :","r":["la lumière et la température ambiantes","le vent","le champ magnétique local","la température"],"b":2,"e":"Son aiguille est un petit aimant."}],"c":"1re C","m":"physique","rang":21,"apc":{"module":"Électricité et électromagnétisme","famille":"Utilisation rationnelle de l'énergie électrique","agir":"Exploiter des générateurs et des récepteurs avec un bon rendement","situation":"Un électricien de Douala étudie une bobine de 100 spires de 50 cm² placée dans un champ de 0,2 T.","tache":"Calcule le flux maximal."},"gratuit":true});
VRT_L("1re-c-physique-r22",{"duree":20,"titre":"Induction et auto-induction","accroche":"Un flux qui varie crée une tension.","intro":"Toute variation de flux à travers un circuit y fait naître une force électromotrice induite.","objectifs":["énoncer la loi de Faraday","appliquer la loi de Lenz","décrire l'auto-induction"],"parties":[{"t":"Loi de Faraday","html":"<div class='def'><b>Définition</b>Une variation de flux crée une <strong>f.é.m. induite</strong> e = −ΔΦ/Δt. Le courant induit s'oppose, par ses effets, à la cause qui lui donne naissance (<strong>loi de Lenz</strong>).</div>"},{"t":"Exemple","verrou":true},{"t":"Auto-induction","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"physique","rang":22,"apc":{"module":"Électricité et électromagnétisme","famille":"Utilisation rationnelle de l'énergie électrique","agir":"Exploiter des générateurs et des récepteurs avec un bon rendement","situation":"Une lampe de vélo d'un élève de Bamenda s'allume grâce à une dynamo.","tache":"Explique l'origine du courant."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-physique-r23",{"duree":20,"titre":"Les générateurs électromagnétiques","accroche":"De Song Loulou à la dynamo de vélo.","intro":"L'alternateur transforme une énergie mécanique de rotation en énergie électrique alternative.","objectifs":["décrire un alternateur","relier fréquence et vitesse de rotation","citer des exemples"],"parties":[{"t":"Principe","html":"<div class='def'><b>Définition</b>Un <strong>alternateur</strong> comprend un rotor (aimant ou électroaimant) qui tourne devant un stator (bobines). La variation de flux crée une tension alternative.</div>"},{"t":"Fréquence","verrou":true},{"t":"Exemples","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"physique","rang":23,"apc":{"module":"Électricité et électromagnétisme","famille":"Utilisation rationnelle de l'énergie électrique","agir":"Exploiter des générateurs et des récepteurs avec un bon rendement","situation":"Un groupe électrogène d'un quartier de Bertoua doit fournir du 50 Hz avec un alternateur à 2 paires de pôles.","tache":"À quelle vitesse le moteur doit-il tourner ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-physique-r24",{"duree":20,"titre":"Énergie, puissance et rendement électriques","accroche":"Toute l'énergie n'arrive pas à destination.","intro":"Dans une chaîne énergétique, chaque convertisseur perd une partie de l'énergie, surtout en chaleur.","objectifs":["faire le bilan d'un générateur","faire le bilan d'un récepteur","calculer le rendement d'une chaîne"],"parties":[{"t":"Générateur","html":"<div class='def'><b>Définition</b>Un générateur fournit la puissance totale EI, en perd rI² par effet Joule et délivre UI. Son <strong>rendement</strong> vaut ρ = UI/EI = U/E.</div>"},{"t":"Récepteur","verrou":true},{"t":"Chaîne énergétique","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"physique","rang":24,"apc":{"module":"Électricité et électromagnétisme","famille":"Utilisation rationnelle de l'énergie électrique","agir":"Exploiter des générateurs et des récepteurs avec un bon rendement","situation":"Un kit solaire d'une école de Kousseri alimente une pompe : batterie de rendement 83 %, moteur de rendement 86 %.","tache":"Calcule le rendement global et propose une amélioration."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r01",{"duree":20,"titre":"Présentation du programme et évaluation diagnostique","accroche":"Ce que tu vas apprendre cette année en SVT.","intro":"La première séance présente le programme de Première et vérifie les acquis de Seconde.","objectifs":["connaître les grands modules","repérer ses acquis","s'organiser"],"parties":[{"t":"Le programme","html":"<div class='def'><b>Définition</b>Le <strong>programme de SVTEEHB de Première</strong> traite de l'énergie dans les organismes, de la santé (immunité, nutrition, santé reproductive) et de la Terre et de l'environnement.</div>"},{"t":"Les acquis à vérifier","html":"<ul><li>La cellule et ses organites.</li><li>La digestion et la circulation.</li><li>Les roches et les paysages.</li></ul>","labo":{"type":"etapes","items":[["Énergie","respiration, fermentation."],["Santé","immunité, nutrition."],["Terre","roches, plaques, climat."]]}},{"t":"Méthode de travail","html":"<p>Réviser chaque séance, schématiser, s'entraîner aux situations d'intégration.</p>","retenir":"Un schéma vaut mieux qu'un long texte."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Évaluation des savoirs (QCM).</strong> Le programme de SVTEEHB de 1re C aborde notamment :</p><ol type='a'><li>l'énergétique, l'immunité, la santé et la géologie externe et interne</li><li>la botanique, la zoologie et la classification des plantes à fleurs</li><li>la génétique des populations et l'évolution des espèces</li><li>la chimie organique et les réactions d'oxydoréduction</li></ol><details><summary>Voir la réponse</summary><p><strong>l'énergétique, l'immunité, la santé et la géologie externe et interne</strong>. Il couvre biologie, santé, environnement et sciences de la Terre.</p></details><p><strong>Évaluation des savoir-faire.</strong></p><p>Cite un organite et sa fonction.</p><details><summary>Voir la réponse</summary><p>(Exemple : la mitochondrie, respiration.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Compétence visée.</strong> Améliorer la production d'énergie par l'organisme.</p><p><strong>Situation.</strong> En début d'année, un élève de 1re C de Bertoua doit montrer qu'il maîtrise les acquis de Seconde : la cellule, la digestion, les roches.</p><p><strong>Consigne 1.</strong> Schématise une cellule animale légendée.</p><p><strong>Consigne 2.</strong> Cite le rôle d'un organite, d'une enzyme digestive et donne un exemple de roche sédimentaire.</p><details><summary>Voir une réponse attendue</summary><p>Schéma : membrane, cytoplasme, noyau, mitochondries. Mitochondrie : respiration ; amylase : hydrolyse de l'amidon ; calcaire ou grès.</p></details></div>","retenir":"Savoir-être mobilisé : Sens de la responsabilité."}],"revision":["Trois grands domaines.","Acquis.","Méthode."],"exo":"<p>Cite un organite et sa fonction. <em>(Exemple : la mitochondrie, respiration.)</em></p>","quiz":[{"q":"Le programme de SVTEEHB de 1re C aborde notamment :","r":["l'énergétique, l'immunité, la santé et la géologie externe et interne","la botanique, la zoologie et la classification des plantes à fleurs","la génétique des populations et l'évolution des espèces","la chimie organique et les réactions d'oxydoréduction"],"b":0,"e":"Il couvre biologie, santé, environnement et sciences de la Terre."},{"q":"L'évaluation diagnostique sert à :","r":["donner la note du premier trimestre aux élèves","repérer les acquis et les lacunes au début de l'année","remplacer les premières leçons du programme de l'année","choisir la série de chaque élève pour l'année suivante"],"b":1,"e":"Elle oriente les révisions nécessaires."},{"q":"L'épreuve de SVT au Probatoire comporte :","r":["un QCM de quarante questions et une dictée scientifique notée sur vingt","une dissertation et un commentaire de texte scientifique","une évaluation des ressources et une évaluation des compétences","un travail pratique et un exposé oral devant le jury"],"b":2,"e":"C'est le format de l'approche par compétences."},{"q":"Une compétence est :","r":["une définition apprise par cœur puis récitée sans erreur","la note obtenue à un devoir surveillé ou à un examen","un chapitre du programme officiel enseigné dans la classe pendant un trimestre","la capacité à mobiliser des savoirs pour résoudre une situation"],"b":3,"e":"Elle s'évalue à partir de situations de vie."},{"q":"Une situation-problème présente :","r":["un contexte réel, des documents et une tâche","seulement une question de cours à réciter","une liste de mots-clés sans contexte","un dessin libre sans consigne précise"],"b":0,"e":"Elle demande d'utiliser les connaissances pour agir."},{"q":"Dans une démarche scientifique, l'hypothèse est suivie :","r":["de la conclusion directe","d'une expérience pour la tester","d'une affiche de synthèse","d'un slogan de sensibilisation"],"b":1,"e":"L'expérience confirme ou infirme l'hypothèse."},{"q":"La dépense énergétique est étudiée dans la partie :","r":["immunologie et santé","géologie externe","énergétique biologique","santé de la reproduction"],"b":2,"e":"Elle relie respiration, alimentation et activité."},{"q":"Les séismes sont étudiés dans la partie :","r":["énergétique biologique","immunologie et santé","alimentation humaine","géologie interne"],"b":3,"e":"On y étudie les ondes sismiques et la structure du globe."},{"q":"Le VIH est étudié dans la partie :","r":["immunologie et santé","géologie externe","écosystèmes et énergie","climat et atmosphère"],"b":0,"e":"On y étudie le soi, le non-soi et les cellules immunitaires."},{"q":"Une bonne méthode de travail en SVT consiste à :","r":["apprendre le cours par cœur sans chercher à comprendre","relier chaque notion à un document et à une situation","ignorer les schémas et ne retenir que les définitions","réviser seulement la veille de chaque devoir surveillé"],"b":1,"e":"Les épreuves exploitent des documents."}],"c":"1re C","m":"svt","rang":1,"apc":{"module":"Énergie et accidents cardiovasculaires","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme","situation":"Un élève arrivant en 1re C au lycée de Bertoua veut s'organiser pour l'année.","tache":"Propose-lui trois conseils."},"gratuit":true});
VRT_L("1re-c-svt-r02",{"duree":20,"titre":"Rappels : rôles des aliments et digestion","accroche":"Du plat de ndolé aux nutriments.","intro":"La digestion transforme les aliments en nutriments assimilables.","objectifs":["citer les rôles des aliments","décrire la digestion","nommer les enzymes"],"parties":[{"t":"Rôles des aliments","html":"<div class='def'><b>Définition</b>Les aliments ont un rôle <strong>énergétique</strong> (glucides, lipides), <strong>bâtisseur</strong> (protides, calcium) et <strong>fonctionnel</strong> (vitamines, sels minéraux).</div>"},{"t":"Digestion","verrou":true},{"t":"Bilan","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":2,"apc":{"module":"Énergie et accidents cardiovasculaires","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme","situation":"Une mère de Douala prépare du ndolé avec plantain et viande.","tache":"Indique les nutriments obtenus après digestion de ce repas."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r03",{"duree":20,"titre":"Rappels : absorption intestinale et circulation","accroche":"Des villosités au sang.","intro":"Les nutriments passent dans le sang et la lymphe, qui les distribuent aux cellules.","objectifs":["décrire l'absorption","distinguer sang et lymphe","expliquer la distribution"],"parties":[{"t":"Absorption","html":"<div class='def'><b>Définition</b>L'<strong>absorption intestinale</strong> est le passage des nutriments de l'intestin grêle vers le sang et la lymphe, à travers les <strong>villosités</strong>.</div>"},{"t":"Deux voies","verrou":true},{"t":"Distribution","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":3,"apc":{"module":"Énergie et accidents cardiovasculaires","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme","situation":"Un élève de Kribi se demande comment le sucre de son jus arrive jusqu'à ses muscles.","tache":"Décris le trajet."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r09",{"duree":20,"titre":"Évaluer la dépense énergétique","accroche":"Combien d'énergie dépense ton corps ?","intro":"La dépense énergétique se mesure par la chaleur produite ou par le dioxygène consommé.","objectifs":["définir la dépense énergétique","utiliser le coefficient thermique de l'O₂","calculer le quotient respiratoire"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>dépense énergétique</strong> est la quantité d'énergie utilisée par l'organisme par unité de temps. On l'évalue par <strong>calorimétrie directe</strong> (chaleur) ou <strong>indirecte</strong> (dioxygène consommé).</div>"},{"t":"Calcul","verrou":true},{"t":"Quotient respiratoire","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":9,"apc":{"module":"Énergie et accidents cardiovasculaires","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme","situation":"Un entraîneur de Garoua mesure qu'un athlète consomme 120 L de dioxygène en une heure d'effort.","tache":"Calcule sa dépense énergétique."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r47",{"duree":20,"titre":"Dépense énergétique : entraînement","accroche":"Calculer QR et dépense.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["exploiter un document","rédiger une réponse","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Dépense = V(O₂) × 20,1 kJ/L ; QR = V(CO₂)/V(O₂).</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":47,"apc":{"module":"Énergie et accidents cardiovasculaires","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme","situation":"Au club santé d'un lycée de Bafia, on mesure les échanges gazeux d'un élève avant et après une course.","tache":"Comment comparer ses dépenses ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r10",{"duree":20,"titre":"Facteurs de variation de la dépense énergétique et métabolisme basal","accroche":"Effort, froid, croissance.","intro":"La dépense énergétique varie selon l'activité et l'état de l'organisme.","objectifs":["citer les facteurs","interpréter un tableau","adapter la ration"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>dépense énergétique</strong> totale comprend le métabolisme de base et les dépenses liées à l'activité, à la thermorégulation, à la croissance et à la digestion.</div>"},{"t":"Facteurs","verrou":true},{"t":"Définition","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":10,"apc":{"module":"Énergie et accidents cardiovasculaires","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme","situation":"Un docker du port de Douala et un employé de bureau mangent la même ration.","tache":"Lequel risque un déficit énergétique ? Justifie."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r48",{"duree":20,"titre":"Facteurs et métabolisme basal : entraînement","accroche":"Lire un tableau de dépenses.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["exploiter un document","rédiger une réponse","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Le métabolisme de base est la dépense minimale ; l'activité s'y ajoute.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":48,"apc":{"module":"Énergie et accidents cardiovasculaires","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme","situation":"Un coach de Bafoussam veut adapter la ration d'un footballeur.","tache":"Comment utiliser un tableau de dépenses ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r11",{"duree":20,"titre":"Les apports énergétiques des repas","accroche":"17, 38, 17 : les nombres de l'énergie.","intro":"L'énergie des aliments se calcule à partir de leur composition en nutriments.","objectifs":["connaître les valeurs énergétiques","calculer l'apport d'un repas","comparer apport et dépense"],"parties":[{"t":"Valeurs","html":"<div class='def'><b>Définition</b>La <strong>valeur énergétique</strong> d'un nutriment est l'énergie libérée par 1 g : glucides 17 kJ/g, lipides 38 kJ/g, protides 17 kJ/g.</div>"},{"t":"Calcul","verrou":true},{"t":"Équilibre","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":11,"apc":{"module":"Énergie et accidents cardiovasculaires","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme","situation":"Un élève de Limbé mange au déjeuner 150 g de riz cuit (40 g de glucides), 20 g d'huile et 30 g de poisson (protides).","tache":"Calcule l'énergie apportée."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r49",{"duree":20,"titre":"Apports énergétiques : entraînement","accroche":"Le piège du QCM 2026.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["exploiter un document","rédiger une réponse","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Glucides et protides : 17 kJ/g ; lipides : 38 kJ/g.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":49,"apc":{"module":"Énergie et accidents cardiovasculaires","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme","situation":"Une vendeuse de beignets de Mbouda affirme que ses beignets « ne font pas grossir » parce qu'ils contiennent peu de sucre. Un beignet de 80 g contient 40 g de glucides, 15 g de lipides et 5 g de protides. On donne : 17 kJ/g pour les glucides et les protides, 38 kJ/g pour les lipides.","tache":"Calcule l'énergie apportée par un beignet et corrige la vendeuse."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r04",{"duree":20,"titre":"Mécanisme et localisation de la respiration","accroche":"Du cytoplasme à la mitochondrie.","intro":"La respiration se déroule en trois grandes étapes dans deux compartiments de la cellule.","objectifs":["décrire la glycolyse","décrire le cycle de Krebs","localiser la chaîne respiratoire"],"parties":[{"t":"Les étapes","html":"<div class='def'><b>Définition</b>La respiration comprend la <strong>glycolyse</strong> (cytoplasme : glucose → 2 pyruvates + 2 ATP), le <strong>cycle de Krebs</strong> (matrice mitochondriale : CO₂ libéré) et la <strong>chaîne respiratoire</strong> (membrane interne : O₂ consommé, ATP produit).</div>"},{"t":"Localisation","verrou":true},{"t":"Bilan","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":4,"apc":{"module":"Énergie et accidents cardiovasculaires","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme","situation":"Au laboratoire, on isole des mitochondries de foie de bœuf et on mesure le dioxygène consommé en 10 minutes : sans substrat, 0 µmol ; avec du glucose, 0 µmol ; avec du pyruvate, 12 µmol. Un élève pense que les mitochondries « brûlent » directement le glucose.","tache":"Analyse ces résultats et réponds à l'élève."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r05",{"duree":20,"titre":"Transporteurs et rendement de la respiration","accroche":"Des navettes d'électrons.","intro":"Les transporteurs d'hydrogène relient les étapes de la respiration à la production d'ATP.","objectifs":["nommer les transporteurs","expliquer leur rôle","calculer le rendement"],"parties":[{"t":"Transporteurs","html":"<div class='def'><b>Définition</b>Les <strong>transporteurs</strong> NAD⁺ et FAD captent les électrons et protons libérés lors de l'oxydation du glucose (formant NADH,H⁺ et FADH₂) et les apportent à la chaîne respiratoire.</div>"},{"t":"Production d'ATP","verrou":true},{"t":"Rendement","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":5,"apc":{"module":"Énergie et accidents cardiovasculaires","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme","situation":"Un élève de Kumba se demande pourquoi il a chaud après une course.","tache":"Explique avec le rendement de la respiration."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r06",{"duree":20,"titre":"Quelques exemples de fermentation","accroche":"Tout se passe dans le cytoplasme.","intro":"La fermentation commence comme la respiration, par la glycolyse, mais s'arrête dans le cytoplasme.","objectifs":["décrire les étapes","localiser la fermentation","comparer les types de fermentation"],"parties":[{"t":"Mécanisme","html":"<div class='def'><b>Définition</b>La <strong>fermentation</strong> comprend la glycolyse (glucose → 2 pyruvates + 2 ATP), puis la transformation du pyruvate en éthanol et CO₂ (alcoolique) ou en lactate (lactique), dans le <strong>cytoplasme</strong>.</div>"},{"t":"Rôle de la seconde étape","verrou":true},{"t":"Exemples","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":6,"apc":{"module":"Énergie et accidents cardiovasculaires","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme","situation":"Une fabricante de yaourts de Ngaoundéré ensemence le lait avec des bactéries lactiques.","tache":"Explique la transformation."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r07",{"duree":20,"titre":"Comparer respiration et fermentation","accroche":"38 contre 2.","intro":"Respiration et fermentation diffèrent par leurs conditions, leurs produits et leur rendement.","objectifs":["comparer les deux voies","calculer les rendements","expliquer la différence"],"parties":[{"t":"Comparaison","html":"<div class='def'><b>Définition</b>La <strong>respiration</strong> est une oxydation complète en présence d'O₂ (38 ATP, rendement environ 40 %) ; la <strong>fermentation</strong> est une dégradation incomplète sans O₂ (2 ATP, rendement environ 2 %).</div>"},{"t":"Explication","verrou":true},{"t":"Conséquence","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":7,"apc":{"module":"Énergie et accidents cardiovasculaires","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme","situation":"Un boulanger de Yaoundé laisse sa pâte lever dans un récipient fermé.","tache":"Explique pourquoi la pâte gonfle et pourquoi elle ne s'arrête pas aussitôt."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r08",{"duree":20,"titre":"Intégration : de l'énergie pour l'effort","accroche":"Préparer une compétition.","intro":"Un athlète doit gérer sa production d'énergie selon le type d'effort.","objectifs":["mobiliser respiration et fermentation","conseiller un athlète","argumenter"],"parties":[{"t":"Notion","html":"<div class='def'><b>Définition</b>Un effort prolongé est couvert surtout par la <strong>respiration</strong> ; un effort intense et bref fait aussi appel à la <strong>fermentation lactique</strong>.</div>"},{"t":"Conseils","verrou":true},{"t":"Production","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":8,"apc":{"module":"Énergie et accidents cardiovasculaires","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme","situation":"Un coureur de la course de l'Espoir au mont Cameroun ressent des crampes dès la première montée.","tache":"Rédige des conseils argumentés."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r39",{"duree":20,"titre":"Flux et dissipation de l'énergie dans un écosystème","accroche":"Seuls 10 % passent au niveau suivant.","intro":"L'énergie traverse l'écosystème en sens unique et se dissipe à chaque niveau.","objectifs":["décrire le flux d'énergie","calculer un rendement écologique","construire une pyramide"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>flux d'énergie</strong> part de la lumière captée par les producteurs et passe d'un niveau trophique à l'autre ; à chaque niveau, une grande partie est <strong>dissipée</strong> en chaleur par la respiration.</div>"},{"t":"Rendement","verrou":true},{"t":"Pyramide","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":39,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Un éleveur de l'Adamaoua se demande pourquoi produire de la viande demande beaucoup plus de surface que produire des céréales.","tache":"Explique avec le flux d'énergie."},"verrou":true,"nq":10,"labo":true});
