VRT_L("1re-c-svt-r40",{"duree":20,"titre":"Réservoirs de carbone, cycle du carbone et flux d'énergie","accroche":"Trop de CO₂ dans l'air.","intro":"Les activités humaines libèrent du carbone stocké depuis des millions d'années.","objectifs":["citer les activités en cause","interpréter l'augmentation du CO₂","proposer des solutions"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Les activités humaines modifient le <strong>cycle du carbone</strong> en transférant le carbone des réservoirs fossiles et forestiers vers l'atmosphère.</div>"},{"t":"Causes","verrou":true},{"t":"Conséquences","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":40,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Dans l'Adamaoua, les feux de brousse brûlent chaque année de grandes surfaces.","tache":"Explique leur effet sur le cycle du carbone et propose des mesures."},"verrou":true,"nq":10,"labo":true});
