VRT_L("1re-c-svt-r79",{"duree":20,"titre":"Intégration : un bilan carbone pour le lycée","accroche":"Mesurer pour réduire.","intro":"Un club environnement veut évaluer et réduire les émissions de CO₂ de son établissement.","objectifs":["identifier les sources de CO₂","proposer des réductions","argumenter"],"parties":[{"t":"Notion","html":"<div class='def'><b>Définition</b>Un <strong>bilan carbone</strong> estime les émissions de CO₂ d'une activité : énergie, transport, déchets.</div>"},{"t":"Sources","verrou":true},{"t":"Actions","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":79,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Le club environnement d'un lycée de Yaoundé veut réduire les émissions de CO₂ de l'établissement.","tache":"Propose un plan d'action en trois points."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r15",{"duree":20,"titre":"Le soi et le non-soi","accroche":"Une carte d'identité moléculaire.","intro":"Chaque individu porte à la surface de ses cellules des molécules qui le caractérisent.","objectifs":["définir le soi","citer les marqueurs du soi","expliquer la compatibilité"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>soi</strong> est l'ensemble des molécules propres à un individu, déterminées par ses gènes, et tolérées par son système immunitaire.</div>"},{"t":"Marqueurs","verrou":true},{"t":"Définition","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":15,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes","situation":"À l'hôpital de district de Mbalmayo, un patient du groupe A a besoin d'une transfusion.","tache":"Quels groupes de donneurs conviennent ? Justifie."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r53",{"duree":20,"titre":"Soi et non-soi : entraînement","accroche":"Interpréter une expérience de greffe.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["exploiter un document","rédiger une réponse","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Une greffe entre individus de CMH différents est rejetée.</div>"},{"t":"Exercice résolu","html":"<p><strong>Document.</strong> Une souris A reçoit une greffe de peau d'une souris A (même lignée) et une greffe d'une souris B (autre lignée). Seule la seconde est rejetée en dix jours.</p><p><strong>Réponse.</strong> La peau de la lignée B porte un CMH différent : elle est reconnue comme non-soi et rejetée.</p>","labo":{"type":"abo"}},{"t":"Le piège à éviter","html":"<div class='attention'><b>Attention</b>Penser que le rejet est dû à la taille du greffon.</div>","retenir":"Penser que le rejet est dû à la taille du greffon."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Évaluation des savoirs (QCM).</strong> Un receveur A+ peut recevoir sans risque des hématies :</p><ol type='a'><li>B+ ou AB+, s'il est rhésus positif</li><li>A+, A−, O+ ou O−</li><li>AB+, AB− ou B+</li><li>B−, O+ ou AB−</li></ol><details><summary>Voir la réponse</summary><p><strong>A+, A−, O+ ou O−</strong>. Il tolère A et O, et Rh+ comme Rh−.</p></details><p><strong>Évaluation des savoir-faire.</strong></p><p>Une autogreffe est-elle rejetée ?</p><details><summary>Voir la réponse</summary><p>(Réponse : non, elle appartient au soi.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Compétence visée.</strong> Lutter contre les problèmes liés à la santé reproductive des jeunes.</p><p><strong>Situation.</strong> On greffe à une souris A de la peau d'une souris B : rejet en 10 jours. Une seconde greffe B sur la même souris est rejetée en 4 jours ; une greffe C, en 10 jours.</p><p><strong>Consigne 1.</strong> Pourquoi la seconde greffe B est-elle rejetée plus vite ?</p><p><strong>Consigne 2.</strong> Que montre le rejet de la greffe C en 10 jours ?</p><details><summary>Voir une réponse attendue</summary><p>La première greffe a créé une mémoire immunitaire spécifique du non-soi B. La réponse est spécifique : face au non-soi C, nouveau, le rejet est aussi lent qu'une première fois.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans l'analyse."}],"revision":["Une greffe entre individus de CMH différents est rejetée.","Penser que le rejet est dû à la taille du greffon."],"exo":"<p>Une autogreffe est-elle rejetée ? <em>(Réponse : non, elle appartient au soi.)</em></p>","quiz":[{"q":"Un receveur A+ peut recevoir sans risque des hématies :","r":["B+ ou AB+, s'il est rhésus positif","A+, A−, O+ ou O−","AB+, AB− ou B+","B−, O+ ou AB−"],"b":1,"e":"Il tolère A et O, et Rh+ comme Rh−."},{"q":"Un receveur O− peut recevoir des hématies :","r":["O+ et O−","A− et O−","O− seulement","de tous les groupes"],"b":2,"e":"Il possède anti-A et anti-B et ne doit pas recevoir l'antigène D."},{"q":"Un mélange de sang B et de sérum anti-B :","r":["reste homogène","devient bleu","coagule toujours sans lien avec le groupe","s'agglutine"],"b":3,"e":"Les anticorps anti-B se fixent sur les hématies B."},{"q":"Si le sang s'agglutine avec les sérums anti-A et anti-B, le groupe est :","r":["AB","O, car aucun sérum ne réagit seul","A, car le sérum anti-A agglutine","B, car le sérum anti-B agglutine"],"b":0,"e":"Les hématies portent les deux antigènes."},{"q":"Si le sang ne s'agglutine avec aucun sérum, le groupe est :","r":["AB","O","A","B"],"b":1,"e":"Les hématies ne portent ni A ni B."},{"q":"Si le sang s'agglutine avec le seul sérum anti-A, le groupe est :","r":["B","AB","A","O"],"b":2,"e":"Les hématies portent l'antigène A."},{"q":"Une mère Rh− qui porte un enfant Rh+ risque :","r":["aucun problème particulier pour les grossesses suivantes","de changer de groupe sanguin après l'accouchement","de devenir elle-même Rh+ pendant la grossesse suivante, à cause du fœtus","de produire des anticorps anti-D dangereux pour une grossesse suivante"],"b":3,"e":"Une injection d'anti-D après l'accouchement prévient ce risque."},{"q":"Les frères et sœurs ont une probabilité d'être HLA identiques de :","r":["1/4","1/2","1","0"],"b":0,"e":"Chacun hérite d'un des deux haplotypes de chaque parent."},{"q":"Une greffe de peau prise sur soi-même (autogreffe) :","r":["est toujours rejetée","n'est pas rejetée","provoque une allergie","demande des immunosuppresseurs à vie"],"b":1,"e":"Le greffon porte les marqueurs du soi."},{"q":"Le test de groupage se lit :","r":["par l'odeur du mélange entre le sang et le sérum test","par la couleur du sérum test","par la présence ou l'absence d'agglutination","par la température du mélange"],"b":2,"e":"L'agglutination montre la présence de l'antigène."}],"c":"1re C","m":"svt","rang":53,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes","situation":"Un chirurgien de Yaoundé prépare une greffe de rein entre deux cousins.","tache":"Pourquoi teste-t-il leur compatibilité ?"},"gratuit":true});
VRT_L("1re-c-svt-r16",{"duree":20,"titre":"Les principales cellules immunitaires","accroche":"Une armée aux rôles variés.","intro":"Les cellules immunitaires naissent dans la moelle osseuse et coopèrent pour défendre l'organisme.","objectifs":["citer les cellules","préciser leur rôle","situer leur origine"],"parties":[{"t":"Les cellules","html":"<div class='def'><b>Définition</b>Les <strong>leucocytes</strong> (globules blancs) assurent l'immunité : phagocytes (macrophages, granulocytes), lymphocytes B, lymphocytes T4 et T8.</div>"},{"t":"Rôles","verrou":true},{"t":"Origine","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":16,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes","situation":"Un laborantin de Limbé observe un frottis sanguin coloré.","tache":"Comment reconnaître un lymphocyte d'un granulocyte ?"},"verrou":true,"nq":10,"labo":true});
