VRT_L("1re-c-svt-r17",{"duree":20,"titre":"Le VIH : contamination et mode d'action","accroche":"Un virus qui détruit les défenseurs.","intro":"Le VIH infecte les lymphocytes T4 et affaiblit progressivement les défenses.","objectifs":["citer les voies de transmission","décrire le cycle du virus","décrire le dépistage"],"parties":[{"t":"Le virus","html":"<div class='def'><b>Définition</b>Le <strong>VIH</strong> est un rétrovirus : son information génétique est un ARN, copié en ADN par la <strong>transcriptase inverse</strong>. Sa protéine gp120 se fixe sur le récepteur CD4 des LT4.</div>"},{"t":"Transmission","verrou":true},{"t":"Cycle et dépistage","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":17,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes","situation":"Un jeune de Kousseri craint d'avoir été contaminé en partageant le repas d'une personne séropositive.","tache":"Rassure-le avec des arguments scientifiques."},"verrou":true,"nq":10,"labo":true});
