VRT_L("1re-c-svt-r42",{"duree":20,"titre":"L'effet de serre","accroche":"Sans lui, il ferait −18 °C.","intro":"Certains gaz de l'atmosphère retiennent une partie de l'infrarouge émis par la Terre.","objectifs":["définir l'effet de serre","citer les gaz à effet de serre","distinguer effet naturel et renforcé"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>L'<strong>effet de serre</strong> est le réchauffement de la surface dû à des gaz atmosphériques (vapeur d'eau, CO₂, méthane) qui absorbent l'infrarouge émis par la Terre et en renvoient une partie vers le sol.</div>"},{"t":"Importance","verrou":true},{"t":"Effet renforcé","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":42,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Les pêcheurs de Kribi observent que la mer gagne sur la plage d'année en année.","tache":"Relie cette observation à l'effet de serre."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r80",{"duree":20,"titre":"Effet de serre : entraînement","accroche":"Interpréter un bilan.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["exploiter un document","rédiger une réponse","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Plus il y a de gaz à effet de serre, plus la surface reçoit d'infrarouge renvoyé.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":80,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Dans un exposé à Bertoua, un élève affirme que l'effet de serre est toujours nuisible.","tache":"Nuance son affirmation."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r24",{"duree":20,"titre":"Les mouvements atmosphériques","accroche":"Harmattan et mousson.","intro":"Les différences de température créent des différences de pression qui mettent l'air en mouvement.","objectifs":["expliquer la naissance des vents","décrire la circulation générale","relier aux saisons du Cameroun"],"parties":[{"t":"Principe","html":"<div class='def'><b>Définition</b>L'air chauffé s'élève et crée une zone de <strong>basse pression</strong> ; l'air froid descend et crée une <strong>haute pression</strong>. Le <strong>vent</strong> souffle des hautes vers les basses pressions.</div>"},{"t":"Circulation générale","verrou":true},{"t":"Au Cameroun","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":24,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Le long de la côte de Limbé, les pirogues rentrent facilement à la plage en fin de journée.","tache":"Explique ce phénomène."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r62",{"duree":20,"titre":"Mouvements atmosphériques : entraînement","accroche":"L'exploitation de document du Probatoire 2026.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["exploiter un document","rédiger une réponse","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>La terre se réchauffe plus vite que l'océan.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":62,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Les pêcheurs de Tiko partent tôt le matin et rentrent l'après-midi.","tache":"Explique ce choix grâce aux brises."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r25",{"duree":20,"titre":"Les mouvements océaniques","accroche":"Des fleuves dans la mer.","intro":"Les vents et les différences de densité mettent en mouvement les eaux océaniques.","objectifs":["décrire les courants de surface","décrire la circulation profonde","expliquer le rôle climatique"],"parties":[{"t":"Courants de surface","html":"<div class='def'><b>Définition</b>Les <strong>courants de surface</strong> sont entraînés par les vents ; le courant de Guinée longe la côte du golfe de Guinée.</div>"},{"t":"Circulation profonde","verrou":true},{"t":"Rôle","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":25,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Les pêcheurs du golfe de Guinée remarquent des saisons où le poisson abonde près des côtes.","tache":"Propose une explication."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r63",{"duree":20,"titre":"Mouvements océaniques : entraînement","accroche":"Expliquer un courant profond.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["exploiter un document","rédiger une réponse","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Densité de l'eau : augmente quand la température baisse et quand la salinité augmente.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":63,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Un élève de Kribi compare l'eau de surface de la plage et l'eau profonde ramenée par un plongeur.","tache":"Explique pourquoi l'eau profonde est plus froide."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r26",{"duree":20,"titre":"Altération et érosion des roches","accroche":"La roche devient sol.","intro":"Sous l'action de l'eau, de la chaleur et des êtres vivants, les roches se dégradent.","objectifs":["distinguer altération et érosion","décrire l'altération physique et chimique","relier aux sols tropicaux"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>L'<strong>altération</strong> est la dégradation des roches sur place ; l'<strong>érosion</strong> est l'enlèvement des produits de cette dégradation par l'eau, le vent ou la glace.</div>"},{"t":"Deux types d'altération","verrou":true},{"t":"En milieu tropical","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":26,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Sur une route de l'Ouest, un talus de granite est devenu une terre rouge friable.","tache":"Explique cette transformation."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r64",{"duree":20,"titre":"Altération et érosion : entraînement","accroche":"Lire un profil de sol.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["exploiter un document","rédiger une réponse","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Un profil d'altération va de la roche saine en profondeur au sol en surface.</div>"},{"t":"Exercice résolu","html":"<p><strong>Document.</strong> Un profil montre de bas en haut : granite sain, granite fissuré, arène, argile rouge, sol humifère.</p><p><strong>Réponse.</strong> L'altération progresse de la surface vers la profondeur : plus on monte, plus la roche est transformée.</p>","labo":{"type":"pente"}},{"t":"Le piège à éviter","html":"<div class='attention'><b>Attention</b>Croire que la roche saine est en surface.</div>","retenir":"Croire que la roche saine est en surface."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Évaluation des savoirs (QCM).</strong> Une roche fissurée par des alternances de chaleur le jour et de fraîcheur la nuit subit :</p><ol type='a'><li>une altération chimique</li><li>une altération physique</li><li>une sédimentation</li><li>une diagenèse</li></ol><details><summary>Voir la réponse</summary><p><strong>une altération physique</strong>. Les dilatations et contractions répétées la font éclater.</p></details><p><strong>Évaluation des savoir-faire.</strong></p><p>Qu'est-ce que l'arène granitique ?</p><details><summary>Voir la réponse</summary><p>(Réponse : un sable issu de la désagrégation du granite.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Compétence visée.</strong> Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique.</p><p><strong>Situation.</strong> Sous climat tropical humide, un granite riche en feldspaths se transforme en argiles et oxydes rouges épais ; sous climat sec, il se fragmente en blocs.</p><p><strong>Consigne 1.</strong> Nomme les deux types d'altération.</p><p><strong>Consigne 2.</strong> Explique pourquoi les sols du Sud du Cameroun sont rouges et épais.</p><details><summary>Voir une réponse attendue</summary><p>Altération chimique (climat humide) et physique (climat sec). La chaleur et l'humidité favorisent l'hydrolyse des minéraux et l'accumulation d'oxydes de fer : sols ferrallitiques épais.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans l'analyse."}],"revision":["Un profil d'altération va de la roche saine en profondeur au sol en surface.","Croire que la roche saine est en surface."],"exo":"<p>Qu'est-ce que l'arène granitique ? <em>(Réponse : un sable issu de la désagrégation du granite.)</em></p>","quiz":[{"q":"Une roche fissurée par des alternances de chaleur le jour et de fraîcheur la nuit subit :","r":["une altération chimique","une altération physique","une sédimentation","une diagenèse"],"b":1,"e":"Les dilatations et contractions répétées la font éclater."},{"q":"Un feldspath transformé en argile subit :","r":["une altération physique (fragmentation)","un transport par charriage","une altération chimique (hydrolyse)","une fusion partielle"],"b":2,"e":"Sa composition minérale change."},{"q":"Un sol nu sur une pente forte en saison des pluies subit :","r":["aucune érosion","une sédimentation","un dépôt de calcaire","une érosion intense"],"b":3,"e":"Le ruissellement emporte la terre."},{"q":"Les ravines sont :","r":["des entailles creusées par le ruissellement","des cuvettes creusées par le vent","des dunes allongées dans le sens du vent","des grottes creusées par dissolution"],"b":0,"e":"Elles se forment sur les sols non protégés."},{"q":"La couverture végétale :","r":["augmente l'érosion du sol","protège le sol de l'érosion","n'a aucun effet sur le sol","provoque des glissements"],"b":1,"e":"Les feuilles amortissent la pluie et les racines retiennent la terre."},{"q":"Le classement des facteurs d'altération par importance en zone équatoriale place en tête :","r":["le gel et l'alternance gel-dégel","la neige et la glace des sommets","l'eau et la chaleur","le vent et le sable"],"b":2,"e":"Le climat chaud et humide favorise l'hydrolyse."},{"q":"Un sol épais d'altérites signifie :","r":["une altération faible et récente","une roche neuve, jamais altérée","un volcan actif sous le sol","une altération longue et intense"],"b":3,"e":"L'épaisseur traduit l'intensité et la durée de l'altération."},{"q":"Pour montrer l'action de l'acide sur le calcaire au laboratoire, on observe :","r":["une effervescence avec l'acide chlorhydrique dilué","une coloration bleue avec l'eau iodée","un précipité rouge brique avec la liqueur de Fehling chauffée","aucune réaction avec l'acide"],"b":0,"e":"Le calcaire libère du CO₂."},{"q":"Le vent est un agent d'érosion important :","r":["dans la forêt dense humide du Sud","dans les régions sèches du Nord","sous l'eau des lacs","dans les grottes calcaires"],"b":1,"e":"Il emporte les particules fines des sols secs."},{"q":"Un profil d'altération montre de haut en bas :","r":["la roche saine, puis les altérites, puis le sol","le magma, les altérites, puis le sol","le sol, les altérites, puis la roche saine","seulement de l'eau et du sable"],"b":2,"e":"L'altération diminue en profondeur."}],"c":"1re C","m":"svt","rang":64,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Un élève de Dschang observe un talus de route en tranchée.","tache":"Décris l'ordre des couches qu'il doit trouver."},"gratuit":true});
VRT_L("1re-c-svt-r27",{"duree":20,"titre":"Transport des produits d'altération et d'érosion","accroche":"Les rivières trient les grains.","intro":"Les produits de l'érosion sont transportés par l'eau et le vent, puis triés selon leur taille.","objectifs":["citer les modes de transport","expliquer le tri","relier énergie et transport"],"parties":[{"t":"Modes de transport","html":"<div class='def'><b>Définition</b>Les particules sont transportées par <strong>roulement</strong>, <strong>saltation</strong>, <strong>suspension</strong> ou en <strong>solution</strong> (ions dissous).</div>"},{"t":"Tri","verrou":true},{"t":"Exemples","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":27,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Après une forte pluie à Bafoussam, la rivière est boueuse et roule des cailloux.","tache":"Explique ce que transporte la rivière."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r65",{"duree":20,"titre":"Transport : entraînement","accroche":"Lire un diagramme de Hjulström simplifié.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["exploiter un document","rédiger une réponse","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Plus un grain est gros, plus il faut un courant rapide pour le transporter.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":65,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Au port de Douala, des dragues retirent chaque année plusieurs millions de mètres cubes de sable et de vase du chenal du Wouri ; sans cela, les gros navires toucheraient le fond en quelques mois.","tache":"Explique l'origine de ces dépôts."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r28",{"duree":20,"titre":"Sédimentation et diagenèse","accroche":"Du sable au grès.","intro":"Les sédiments se déposent puis se transforment lentement en roches.","objectifs":["définir sédimentation et diagenèse","décrire les étapes de la diagenèse","citer des exemples"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>La <strong>sédimentation</strong> est le dépôt des particules dans un bassin (lac, mer, delta). La <strong>diagenèse</strong> est l'ensemble des transformations qui changent un sédiment meuble en roche sédimentaire.</div>"},{"t":"Étapes","verrou":true},{"t":"Exemples","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":28,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Au bord du lac Tchad, des couches de boue s'accumulent chaque année.","tache":"Que deviendront-elles dans des millions d'années ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r66",{"duree":20,"titre":"Sédimentation et diagenèse : entraînement","accroche":"Le QCM du Probatoire 2026.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["exploiter un document","rédiger une réponse","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>La diagenèse est l'ensemble des transformations physico-chimiques qui changent les sédiments en roches sédimentaires.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":66,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Dans sa copie, un élève de Bertoua écrit : « Le granite de l'Ouest devient du sable par diagenèse, puis le sable devient du grès par altération. »","tache":"Corrige la phrase en définissant les deux mots."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r29",{"duree":20,"titre":"Roches sédimentaires et lutte contre l'érosion","accroche":"Des ressources à protéger.","intro":"Les roches sédimentaires sont utiles, mais l'érosion appauvrit les sols ; il faut la combattre.","objectifs":["citer l'importance des roches sédimentaires","citer les dégâts de l'érosion","proposer des moyens de lutte"],"parties":[{"t":"Importance","html":"<div class='def'><b>Définition</b>Les <strong>roches sédimentaires</strong> fournissent des matériaux (sable, argile, calcaire), de l'énergie (charbon, pétrole) et renseignent sur l'histoire de la Terre.</div>"},{"t":"Dégâts de l'érosion","verrou":true},{"t":"Lutte","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":29,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Sur les collines de l'Ouest, des champs sur forte pente perdent leur terre à chaque pluie.","tache":"Propose trois mesures."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r67",{"duree":20,"titre":"Roches sédimentaires : entraînement","accroche":"Identifier trois roches.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["exploiter un document","rédiger une réponse","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Test à l'acide, dureté et toucher permettent une première identification.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":67,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Un élève de Mbalmayo ramasse un caillou blanc près d'une ancienne carrière.","tache":"Propose deux tests pour l'identifier."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r30",{"duree":20,"titre":"Intégration : lutter contre le ravinement","accroche":"Des ravines menacent le quartier.","intro":"Les pluies violentes creusent des ravines dans les sols nus et menacent les habitations.","objectifs":["mobiliser altération, érosion et transport","proposer des solutions","rédiger un texte et un slogan"],"parties":[{"t":"Notion","html":"<div class='def'><b>Définition</b>Le <strong>ravinement</strong> est une forme d'érosion due à l'eau qui ruisselle et creuse des sillons dans un sol nu.</div>"},{"t":"Solutions","verrou":true},{"t":"Production","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":30,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"À Maroua, des ravines profondes se forment après chaque saison des pluies et menacent des maisons.","tache":"Rédige un texte argumenté et propose un slogan."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r68",{"duree":20,"titre":"Intégration : un glissement de terrain évitable","accroche":"Quand la colline cède.","intro":"Des pluies abondantes sur des pentes déboisées et surchargées peuvent provoquer des glissements de terrain.","objectifs":["identifier les causes","proposer des mesures de prévention","informer la population"],"parties":[{"t":"Notion","html":"<div class='def'><b>Définition</b>Un <strong>glissement de terrain</strong> est le déplacement d'une masse de sol ou de roche le long d'une pente, souvent après de fortes pluies.</div>"},{"t":"Causes","verrou":true},{"t":"Prévention","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":68,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Après de fortes pluies, un pan de colline s'est effondré sur des habitations dans un quartier de l'Ouest.","tache":"Propose un plan de prévention."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r31",{"duree":20,"titre":"Les ondes sismiques","accroche":"Un séisme fait vibrer toute la Terre.","intro":"Les séismes produisent des ondes qui traversent le globe et renseignent sur sa structure.","objectifs":["distinguer ondes P, S et L","lire un sismogramme","localiser un épicentre"],"parties":[{"t":"Les ondes","html":"<div class='def'><b>Définition</b>Un séisme émet des <strong>ondes P</strong> (longitudinales, les plus rapides, traversent solides et liquides), des <strong>ondes S</strong> (transversales, ne traversent pas les liquides) et des <strong>ondes L</strong> (de surface, les plus destructrices).</div>"},{"t":"Le sismogramme","verrou":true},{"t":"Localisation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":31,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Une station sismique de Yaoundé enregistre les ondes P puis, 40 secondes plus tard, les ondes S d'un séisme.","tache":"Que permet de calculer ce retard ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r69",{"duree":20,"titre":"Ondes sismiques : entraînement","accroche":"Calculer une distance au foyer.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["exploiter un document","rédiger une réponse","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>d = Δt × vP × vS / (vP − vS).</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":69,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Une station de Garoua note 20 s entre les ondes P et S d'un séisme.","tache":"Calcule la distance au foyer avec vP = 6 km/s et vS = 3,5 km/s."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r32",{"duree":20,"titre":"Les enveloppes internes du globe","accroche":"Croûte, manteau, noyau.","intro":"La sismologie a permis de découvrir les grandes enveloppes de la Terre et leurs limites.","objectifs":["nommer les enveloppes","nommer les discontinuités","distinguer lithosphère et asthénosphère"],"parties":[{"t":"Les enveloppes","html":"<div class='def'><b>Définition</b>La Terre comprend la <strong>croûte</strong>, le <strong>manteau</strong> et le <strong>noyau</strong> (externe liquide, interne solide), séparés par des discontinuités : Moho, Gutenberg (2 900 km), Lehmann (5 150 km).</div>"},{"t":"Croûtes","verrou":true},{"t":"Lithosphère et asthénosphère","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":32,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Un élève de Bamenda fabrique une maquette en coupe de la Terre.","tache":"Liste les enveloppes et les discontinuités à représenter."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r70",{"duree":20,"titre":"Enveloppes internes : entraînement","accroche":"Lire un profil de vitesse des ondes.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["exploiter un document","rédiger une réponse","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Une chute brutale de la vitesse des P et la disparition des S marquent le noyau externe.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":70,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Une station sismique enregistre les ondes d'un séisme lointain : la vitesse des ondes P augmente de 6 à 8 km/s vers 30 km de profondeur, puis chute brutalement de 13,6 à 8,1 km/s vers 2 900 km ; les ondes S disparaissent à cette même profondeur.","tache":"Indique les discontinuités révélées et ce qu'elles séparent."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r33",{"duree":20,"titre":"Composition et propriétés des enveloppes","accroche":"Plus on descend, plus c'est dense et chaud.","intro":"Chaque enveloppe a une composition, une densité et une température propres.","objectifs":["donner la composition des enveloppes","décrire l'évolution de la densité","décrire l'évolution de la température"],"parties":[{"t":"Composition","html":"<div class='def'><b>Définition</b>La croûte est riche en silicium, oxygène et aluminium ; le <strong>manteau</strong> est formé de <strong>péridotite</strong> ; le <strong>noyau</strong> est surtout fait de <strong>fer et de nickel</strong>.</div>"},{"t":"Densité","verrou":true},{"t":"Température","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":33,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Un élève de Kumba lit que la masse volumique moyenne de la Terre est d'environ 5,5 g/cm³, alors que le granite de son quartier n'a que 2,7 g/cm³ et le basalte du mont Cameroun 3 g/cm³.","tache":"Explique cette différence à l'aide de la structure interne du globe."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r71",{"duree":20,"titre":"Composition des enveloppes : entraînement","accroche":"Comparer des densités.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["exploiter un document","rédiger une réponse","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Densité moyenne de la Terre : environ 5,5 ; croûte : environ 2,8.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":71,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Lors d'un exposé à Bafoussam, un élève affirme que l'intérieur de la Terre est vide.","tache":"Réfute avec un argument."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r34",{"duree":20,"titre":"L'énergie interne de la Terre","accroche":"Une chaleur venue de l'intérieur.","intro":"La Terre produit de la chaleur qui s'évacue par le volcanisme, les séismes et la convection.","objectifs":["citer l'origine de l'énergie interne","décrire sa dissipation","citer des usages"],"parties":[{"t":"Origine","html":"<div class='def'><b>Définition</b>L'<strong>énergie interne</strong> de la Terre provient surtout de la <strong>désintégration d'éléments radioactifs</strong> (uranium, thorium, potassium) et de la chaleur primitive.</div>"},{"t":"Dissipation","verrou":true},{"t":"Usages","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":34,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Des habitants de Buea s'interrogent sur l'origine des éruptions du mont Cameroun.","tache":"Explique l'origine de l'énergie qui les provoque."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r72",{"duree":20,"titre":"Énergie interne : entraînement","accroche":"Lire un gradient géothermique.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["exploiter un document","rédiger une réponse","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>La température augmente d'environ 30 °C par km dans la croûte continentale.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":72,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Une société étudie la possibilité d'une centrale géothermique dans la région volcanique de l'Ouest.","tache":"Quel critère mesurer en priorité ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r35",{"duree":20,"titre":"Intégration : se préparer aux séismes","accroche":"Savoir où et comment agir.","intro":"La région du mont Cameroun connaît une activité sismique et volcanique : la population doit s'y préparer.","objectifs":["mobiliser les connaissances sur les séismes","proposer des consignes","rédiger un texte et une affiche"],"parties":[{"t":"Notion","html":"<div class='def'><b>Définition</b>Un <strong>séisme</strong> libère brutalement de l'énergie accumulée dans les roches ; ses ondes de surface causent l'essentiel des dégâts.</div>"},{"t":"Consignes","verrou":true},{"t":"Production","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":35,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Le mont Cameroun est entré en éruption en 1999 et en 2000, et des secousses sont parfois ressenties à Buea. Le proviseur du lycée veut organiser un exercice d'alerte pour 1 200 élèves répartis dans 24 salles.","tache":"Rédige les consignes à afficher dans les salles et propose l'organisation de l'évacuation."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r73",{"duree":20,"titre":"Intégration : un volcan à surveiller","accroche":"Vivre près du mont Cameroun.","intro":"Les habitants des pentes du mont Cameroun doivent connaître les risques et les consignes.","objectifs":["identifier les risques volcaniques","proposer une surveillance","informer la population"],"parties":[{"t":"Notion","html":"<div class='def'><b>Définition</b>Un <strong>volcan actif</strong> peut produire coulées de lave, gaz et séismes ; la surveillance (sismographes, gaz, déformation du sol) permet d'anticiper.</div>"},{"t":"Risques","verrou":true},{"t":"Prévention","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":73,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Des villages sur les pentes du mont Cameroun ont connu des coulées de lave lors d'éruptions passées.","tache":"Propose un plan d'information pour les habitants."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r36",{"duree":20,"titre":"La dérive des continents : les preuves","accroche":"L'Afrique et l'Amérique du Sud s'emboîtent.","intro":"Au début du XXᵉ siècle, Alfred Wegener a proposé que les continents se déplacent.","objectifs":["citer les arguments de Wegener","les interpréter","comprendre les objections"],"parties":[{"t":"L'hypothèse","html":"<div class='def'><b>Définition</b>La <strong>dérive des continents</strong> est l'hypothèse selon laquelle les continents, autrefois réunis en un supercontinent (la Pangée), se sont séparés et déplacés.</div>"},{"t":"Les preuves","verrou":true},{"t":"Objection","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":36,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"En regardant une carte au lycée de Kribi, un élève remarque que la côte du Cameroun semble s'emboîter avec celle du Brésil.","tache":"Quelle hypothèse cette observation soutient-elle ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r74",{"duree":20,"titre":"Dérive des continents : entraînement","accroche":"Exploiter une carte de fossiles.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["exploiter un document","rédiger une réponse","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Des fossiles terrestres identiques sur des continents séparés par un océan prouvent qu'ils étaient réunis.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":74,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Des fossiles du même reptile, le Mesosaurus, ont été trouvés au Brésil et en Afrique australe ; des fossiles de la même fougère, Glossopteris, en Inde, en Afrique, en Amérique du Sud et en Antarctique. Ces êtres ne pouvaient pas traverser un océan.","tache":"Explique ce que révèle cette répartition."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r37",{"duree":20,"titre":"La plaque lithosphérique","accroche":"La surface de la Terre est un puzzle.","intro":"La lithosphère est découpée en plaques rigides qui se déplacent sur l'asthénosphère.","objectifs":["définir une plaque","citer les grandes plaques","situer les limites"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une <strong>plaque lithosphérique</strong> est un fragment rigide de lithosphère (croûte et sommet du manteau) qui se déplace sur l'asthénosphère.</div>"},{"t":"Les plaques","verrou":true},{"t":"Limites","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":37,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Un élève de Dschang reporte sur une carte du monde les 20 plus forts séismes de l'année : 8 au bord du Pacifique (Chili, Japon, Indonésie), 4 sur la dorsale médio-atlantique, 3 dans l'Himalaya, 2 en Méditerranée, 3 ailleurs.","tache":"Que révèle cette répartition ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r75",{"duree":20,"titre":"Plaques lithosphériques : entraînement","accroche":"Lire une carte de séismes.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["exploiter un document","rédiger une réponse","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Les séismes se concentrent le long des limites de plaques.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":75,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Un élève de Bertoua s'étonne : le Japon subit des centaines de séismes forts, alors que le Cameroun n'en ressent que quelques-uns, faibles, surtout autour du mont Cameroun.","tache":"Explique cette différence."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r38",{"duree":20,"titre":"Les mouvements des plaques","accroche":"Écarter, rapprocher, coulisser.","intro":"Les plaques s'écartent, se rapprochent ou glissent les unes contre les autres.","objectifs":["distinguer les trois types de limites","relier chaque type à des phénomènes","expliquer le moteur"],"parties":[{"t":"Les mouvements","html":"<div class='def'><b>Définition</b>Les plaques ont trois types de mouvements relatifs : <strong>divergence</strong> (dorsales), <strong>convergence</strong> (subduction, collision) et <strong>coulissage</strong> (failles transformantes).</div>"},{"t":"Phénomènes associés","verrou":true},{"t":"Moteur","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":38,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Un documentaire montre que l'océan Atlantique s'élargit chaque année.","tache":"Explique ce phénomène."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r76",{"duree":20,"titre":"Mouvements des plaques : entraînement","accroche":"Calculer une vitesse d'écartement.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["exploiter un document","rédiger une réponse","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Vitesse = distance / durée.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":76,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Un élève de Limbé lit que l'Atlantique s'élargit d'environ 2 à 4 cm par an.","tache":"Calcule l'élargissement en 1 000 ans pour 3 cm/an."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r43",{"duree":20,"titre":"Rôle de la couche d'ozone","accroche":"Un bouclier contre les ultraviolets.","intro":"La couche d'ozone de la stratosphère protège les êtres vivants des rayons ultraviolets.","objectifs":["situer la couche d'ozone","expliquer son rôle","citer les causes de sa destruction"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>couche d'ozone</strong> (O₃) est située dans la stratosphère, entre environ 15 et 35 km d'altitude ; elle absorbe la plus grande partie des <strong>rayons ultraviolets</strong> dangereux.</div>"},{"t":"Importance","verrou":true},{"t":"Destruction et protection","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":43,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Un réparateur de réfrigérateurs à Douala récupère d'anciens appareils.","tache":"Quelle précaution doit-il prendre pour l'environnement ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r81",{"duree":20,"titre":"Couche d'ozone : entraînement","accroche":"Ne pas confondre ozone et effet de serre.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["exploiter un document","rédiger une réponse","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>L'ozone stratosphérique filtre les UV ; l'effet de serre retient l'infrarouge.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":81,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Dans un débat au lycée de Yaoundé, deux élèves confondent ozone et effet de serre.","tache":"Explique la différence."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-c-svt-r44",{"duree":20,"titre":"Lutter contre le réchauffement climatique","accroche":"Atténuer et s'adapter.","intro":"La lutte contre le réchauffement combine réduction des émissions et adaptation aux changements.","objectifs":["distinguer atténuation et adaptation","proposer des actions","connaître les engagements internationaux"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>L'<strong>atténuation</strong> réduit les émissions de gaz à effet de serre ; l'<strong>adaptation</strong> réduit la vulnérabilité aux effets du changement climatique.</div>"},{"t":"Actions","verrou":true},{"t":"Engagements","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re C","m":"svt","rang":44,"apc":{"module":"Terre, écosystèmes et environnement","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et lutter contre le réchauffement climatique","situation":"Le conseil municipal d'une ville du Centre veut agir contre le réchauffement climatique.","tache":"Propose trois actions et classe-les."},"verrou":true,"nq":10,"labo":true});
